begin;
-- DIRA LEARN: application review workflow + cohort scheduling rules
-- STATUS: written, NOT yet executed. Run `supabase db reset` and `supabase test db` and fix any errors.
-- The status workflow below is a DRAFT proposal (the SRS excerpt available to me does not define it); see docs/ASSUMPTIONS_AND_DECISIONS.md.

-- ---------- 1. Fix: applicants submit in one step (the form inserts status 'submitted') ----------
drop policy if exists apps_own_insert on applications;
create policy apps_own_insert on applications for insert to authenticated
  with check (applicant_id = auth.uid() and status in ('draft', 'submitted'));

-- ---------- 2. Application status workflow ----------
create or replace function application_transition_allowed(p_from application_status, p_to application_status)
returns boolean language sql immutable as $$
  select case p_from
    when 'submitted'   then p_to in ('under_review', 'rejected')
    when 'under_review' then p_to in ('shortlisted', 'waitlisted', 'accepted', 'rejected')
    when 'shortlisted' then p_to in ('under_review', 'waitlisted', 'accepted', 'rejected')
    when 'waitlisted'  then p_to in ('shortlisted', 'accepted', 'rejected')
    when 'rejected'    then p_to in ('under_review')       -- reconsideration, note required
    else false                                              -- draft is the applicant's; accepted is final
  end $$;

-- Staff change status through this function so every change is validated and logged.
create or replace function transition_application(p_app uuid, p_to application_status, p_note text default null)
returns void language plpgsql security definer set search_path = public as $$
declare cur application_status;
begin
  if not is_staff() then raise exception 'Only programme staff can review applications'; end if;
  select status into cur from applications where id = p_app for update;
  if cur is null then raise exception 'Application not found'; end if;
  if not application_transition_allowed(cur, p_to) then
    raise exception 'An application cannot move from % to %', cur, p_to;
  end if;
  if (p_to = 'rejected' or cur = 'rejected') and coalesce(btrim(p_note), '') = '' then
    raise exception 'A note is required when rejecting or reconsidering an application';
  end if;
  perform set_config('dira.application_transition', 'on', true);
  update applications set status = p_to where id = p_app;
  insert into application_events(application_id, from_status, to_status, note, actor_id)
    values (p_app, cur, p_to, nullif(btrim(p_note), ''), auth.uid());
end $$;
revoke all on function transition_application(uuid, application_status, text) from public;
grant execute on function transition_application(uuid, application_status, text) to authenticated;

-- Direct status edits are blocked unless they come through transition_application, the service role
-- (Edge Functions), or an applicant submitting their own draft.
create or replace function guard_application_status() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'submitted' and new.submitted_at is null then new.submitted_at := now(); end if;
    return new;
  end if;
  if new.status is distinct from old.status then
    if auth.uid() is null or current_setting('dira.application_transition', true) = 'on' then
      return new;
    end if;
    if auth.uid() = old.applicant_id and old.status = 'draft' and new.status = 'submitted' then
      new.submitted_at := coalesce(new.submitted_at, now());
      return new;
    end if;
    raise exception 'Application status can only be changed through the review workflow';
  end if;
  return new;
end $$;
create trigger trg_guard_application_status before insert or update on applications
  for each row execute function guard_application_status();

-- Log the applicant's own submission as the first history entry.
create or replace function log_application_submitted() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'submitted' and (tg_op = 'INSERT' or old.status = 'draft') then
    insert into application_events(application_id, from_status, to_status, actor_id)
      values (new.id, case when tg_op = 'UPDATE' then 'draft'::application_status end, 'submitted', new.applicant_id);
  end if;
  return new;
end $$;
create trigger trg_log_application_submitted after insert or update on applications
  for each row execute function log_application_submitted();

-- Reviewer notes cannot be attributed to someone else.
create or replace function set_event_actor() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null then new.actor_id := auth.uid(); end if;
  return new;
end $$;
create trigger trg_event_actor before insert on application_events for each row execute function set_event_actor();

-- Accepted-and-converted participants who are not in any cohort yet.
create view v_unplaced_participants with (security_invoker = true) as
  select p.id as participant_id, p.participant_no, pr.first_name, pr.last_name
  from participants p join profiles pr on pr.id = p.profile_id
  where p.status in ('enrolled', 'active')
    and not exists (select 1 from cohort_enrolments e join cohorts c on c.id = e.cohort_id
                    where e.participant_id = p.id and not c.archived);

-- ---------- 3. Cohort rules ----------
-- Capacity check now locks the cohort row so two coordinators cannot both take the last place.
create or replace function enforce_cohort_capacity() returns trigger language plpgsql security definer set search_path = public as $$
declare cap int; cur int; arch boolean;
begin
  select capacity, archived into cap, arch from cohorts where id = new.cohort_id for update;
  if arch then raise exception 'This cohort is archived'; end if;
  select count(*) into cur from cohort_enrolments where cohort_id = new.cohort_id;
  if cur >= cap then raise exception 'Cohort is at capacity (%)', cap; end if;
  return new;
end $$;

-- A participant belongs to one active (non-archived) cohort at a time.
create or replace function enforce_single_active_cohort() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from cohort_enrolments e join cohorts c on c.id = e.cohort_id
             where e.participant_id = new.participant_id and e.cohort_id <> new.cohort_id and not c.archived) then
    raise exception 'This participant is already enrolled in another active cohort';
  end if;
  return new;
end $$;
create trigger trg_single_cohort before insert on cohort_enrolments for each row execute function enforce_single_active_cohort();

-- Capacity cannot drop below the number already enrolled.
create or replace function guard_cohort_capacity() returns trigger language plpgsql security definer set search_path = public as $$
declare cur int;
begin
  select count(*) into cur from cohort_enrolments where cohort_id = new.id;
  if new.capacity < cur then raise exception 'Capacity cannot be lower than the % participants already enrolled', cur; end if;
  return new;
end $$;
create trigger trg_cohort_capacity_guard before update of capacity on cohorts for each row execute function guard_cohort_capacity();

-- A trainer assignment must be a trainer; a track-specific assignment must use a track of the cohort's programme.
create or replace function guard_trainer_assignment() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from profiles where id = new.trainer_id and role = 'trainer' and status = 'active') then
    raise exception 'Only an active trainer account can be assigned to a cohort';
  end if;
  if new.track_id is not null and not exists (
      select 1 from tracks t join cohorts c on c.programme_id = t.programme_id where t.id = new.track_id and c.id = new.cohort_id) then
    raise exception 'Track does not belong to this cohort''s programme';
  end if;
  return new;
end $$;
create trigger trg_guard_trainer_assignment before insert or update on trainer_assignments for each row execute function guard_trainer_assignment();

-- ---------- 4. Session scheduling rules (2-hour cap is already a table constraint) ----------
-- Draft setting: the programme's local time zone, used to decide which calendar day a session falls on.
insert into system_settings(key, value, is_approved, note) values
  ('programme_timezone', '"Africa/Nairobi"', false, 'Assumed from the location of the first user. DIRA Foundation to confirm.')
on conflict (key) do nothing;

-- One live schedule per curriculum session per cohort (cancelled/rescheduled rows are history).
create unique index uq_live_schedule on session_schedules(cohort_id, curriculum_session_id) where status in ('scheduled', 'completed');

create or replace function guard_session_schedule() returns trigger language plpgsql security definer set search_path = public as $$
declare
  cs record; co record; tz text; day date; clash record;
begin
  if tg_op = 'UPDATE' and old.status = 'completed'
     and (new.starts_at <> old.starts_at or new.ends_at <> old.ends_at or new.cohort_id <> old.cohort_id or new.curriculum_session_id <> old.curriculum_session_id) then
    raise exception 'A completed session cannot be moved';
  end if;
  if new.status in ('cancelled', 'rescheduled') then return new; end if;

  select * into co from cohorts where id = new.cohort_id;
  select * into cs from curriculum_sessions where id = new.curriculum_session_id;
  if co.archived then raise exception 'This cohort is archived'; end if;
  if cs.programme_id <> co.programme_id then raise exception 'Session belongs to a different programme'; end if;

  select coalesce(trim(both '"' from value::text), 'Africa/Nairobi') into tz from system_settings where key = 'programme_timezone';
  day := (new.starts_at at time zone coalesce(tz, 'Africa/Nairobi'))::date;
  if day < co.start_date or day > co.end_date then
    raise exception 'Session date % is outside the cohort dates (% to %)', day, co.start_date, co.end_date;
  end if;
  if new.trainer_id is not null then
    if not exists (select 1 from trainer_assignments ta where ta.cohort_id = new.cohort_id and ta.trainer_id = new.trainer_id
                   and (ta.track_id is null or ta.track_id = cs.track_id)) then
      raise exception 'This trainer is not assigned to the cohort%', case when cs.track_id is not null then ' for this track' else '' end;
    end if;
    select s.id into clash from session_schedules s
      where s.trainer_id = new.trainer_id and s.status in ('scheduled', 'completed') and s.id is distinct from new.id
        and tstzrange(s.starts_at, s.ends_at) && tstzrange(new.starts_at, new.ends_at) limit 1;
    if found then raise exception 'The trainer already has a session at that time'; end if;
  end if;

  -- Within one cohort, sessions for DIFFERENT tracks may run in parallel; core sessions need the whole cohort.
  select s.id into clash from session_schedules s join curriculum_sessions o on o.id = s.curriculum_session_id
    where s.cohort_id = new.cohort_id and s.status in ('scheduled', 'completed') and s.id is distinct from new.id
      and tstzrange(s.starts_at, s.ends_at) && tstzrange(new.starts_at, new.ends_at)
      and not (cs.track_id is not null and o.track_id is not null and o.track_id <> cs.track_id) limit 1;
  if found then raise exception 'This cohort already has a session at that time'; end if;
  return new;
end $$;
create trigger trg_guard_session_schedule before insert or update on session_schedules for each row execute function guard_session_schedule();

-- ---------- 5. Audit ----------
create trigger aud_applications after insert or update or delete on applications for each row execute function audit_row();
create trigger aud_cohorts after insert or update or delete on cohorts for each row execute function audit_row();
create trigger aud_enrolments after insert or update or delete on cohort_enrolments for each row execute function audit_row();
create trigger aud_trainer_assign after insert or update or delete on trainer_assignments for each row execute function audit_row();
create trigger aud_schedules after insert or update or delete on session_schedules for each row execute function audit_row();
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000004', 'applications_cohorts');
commit;

\echo '== migration 20260101000005 sessions_curriculum_admin'
begin;
-- DIRA LEARN: trainer session flow (delivery reports, completion) + curriculum administration rules
-- STATUS: written, NOT yet executed. Run `supabase db reset` and `supabase test db` and fix any errors.

-- ---------- 1. Session delivery reports ----------
create table session_reports (
  schedule_id uuid primary key references session_schedules(id) on delete cascade,
  summary text,            -- what was actually covered
  challenges text,         -- what got in the way
  follow_ups text,         -- what the next session or coordinator should pick up
  updated_by uuid references profiles(id),
  updated_at timestamptz not null default now()
);
create or replace function set_report_meta() returns trigger language plpgsql security definer set search_path = public as $$
begin new.updated_by := coalesce(auth.uid(), new.updated_by); new.updated_at := now(); return new; end $$;
create trigger trg_report_meta before insert or update on session_reports for each row execute function set_report_meta();
create trigger aud_reports after insert or update or delete on session_reports for each row execute function audit_row();

alter table session_reports enable row level security;
create or replace function can_manage_schedule(p_schedule uuid) returns boolean language sql stable security definer set search_path = public as $$
  select is_staff() or exists (select 1 from session_schedules s where s.id = p_schedule and app_role() = 'trainer'
    and s.cohort_id in (select my_trainer_cohorts())) $$;
create policy sreport_read on session_reports for select to authenticated using (can_manage_schedule(schedule_id) or app_role() = 'me_officer');
create policy sreport_write on session_reports for all to authenticated using (can_manage_schedule(schedule_id)) with check (can_manage_schedule(schedule_id));

-- ---------- 2. Completing a session ----------
-- A session can be marked completed once it has started and attendance is recorded for everyone expected.
-- Expected = all enrolled participants for a core session, or those on that track for a track session.
create or replace function complete_session(p_schedule uuid) returns void language plpgsql security definer set search_path = public as $$
declare s record; tid uuid; missing int;
begin
  if not can_manage_schedule(p_schedule) then raise exception 'You cannot manage this session'; end if;
  select ss.*, cs.track_id as session_track into s from session_schedules ss join curriculum_sessions cs on cs.id = ss.curriculum_session_id
    where ss.id = p_schedule for update of ss;
  if s.id is null then raise exception 'Session not found'; end if;
  if s.status <> 'scheduled' then raise exception 'Only a scheduled session can be completed (this one is %)', s.status; end if;
  if s.starts_at > now() then raise exception 'This session has not started yet'; end if;
  select count(*) into missing from cohort_enrolments e
    where e.cohort_id = s.cohort_id and (s.session_track is null or e.track_id = s.session_track)
      and not exists (select 1 from attendance a where a.schedule_id = p_schedule and a.participant_id = e.participant_id);
  if missing > 0 then raise exception 'Attendance is missing for % participant(s)', missing; end if;
  update session_schedules set status = 'completed' where id = p_schedule;
end $$;
revoke all on function complete_session(uuid) from public;
grant execute on function complete_session(uuid) to authenticated;

-- ---------- 3. Curriculum administration ----------
-- Coordinators and super admins may edit content (existing RLS). Only super admin and programme director may approve.
-- Editing approved content sends it back to draft so it must be approved again.
create or replace function guard_curriculum_session() returns trigger language plpgsql security definer set search_path = public as $$
declare content_changed boolean;
begin
  if auth.uid() is null then return new; end if;                       -- service role / migrations
  if tg_op = 'INSERT' then
    if new.is_approved and app_role() not in ('super_admin', 'programme_director') then
      raise exception 'Only a super administrator or programme director can approve curriculum content';
    end if;
    return new;
  end if;
  if new.is_approved is distinct from old.is_approved then
    if app_role() not in ('super_admin', 'programme_director') then
      raise exception 'Only a super administrator or programme director can approve curriculum content';
    end if;
  end if;
  content_changed := (new.title, new.description, new.duration_minutes, new.objectives, new.topics, new.activities, new.expected_output, new.assessment_notes, new.week_no, new.session_no, new.track_id)
                     is distinct from
                     (old.title, old.description, old.duration_minutes, old.objectives, old.topics, old.activities, old.expected_output, old.assessment_notes, old.week_no, old.session_no, old.track_id);
  if content_changed and old.is_approved and new.is_approved is not distinct from old.is_approved then
    new.is_approved := false;                                          -- needs re-approval
  end if;
  return new;
end $$;
create trigger trg_guard_curriculum before insert or update on curriculum_sessions for each row execute function guard_curriculum_session();
create trigger aud_curriculum after insert or update or delete on curriculum_sessions for each row execute function audit_row();

-- Director may approve but not edit content under the existing write policy, so approval goes through a function.
create or replace function set_curriculum_approval(p_session uuid, p_approved boolean) returns void language plpgsql security definer set search_path = public as $$
begin
  if app_role() not in ('super_admin', 'programme_director') then
    raise exception 'Only a super administrator or programme director can approve curriculum content';
  end if;
  update curriculum_sessions set is_approved = p_approved where id = p_session;
end $$;
revoke all on function set_curriculum_approval(uuid, boolean) from public;
grant execute on function set_curriculum_approval(uuid, boolean) to authenticated;

-- A session that has ever been scheduled keeps its identity: week, number and track cannot change under a live timetable.
create or replace function guard_scheduled_curriculum() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (new.week_no, new.session_no, new.track_id) is distinct from (old.week_no, old.session_no, old.track_id)
     and exists (select 1 from session_schedules where curriculum_session_id = old.id) then
    raise exception 'This session is already scheduled, so its week, number and track cannot change';
  end if;
  return new;
end $$;
create trigger trg_guard_scheduled_curriculum before update on curriculum_sessions for each row execute function guard_scheduled_curriculum();
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000005', 'sessions_curriculum_admin');
commit;

\echo '== migration 20260101000006 assignments_grading'
begin;
-- DIRA LEARN: assignments, submissions and grading rules
-- STATUS: written, NOT yet executed. Run `supabase db reset` and `supabase test db` and fix any errors.

-- ---------- 1. Assignments ----------
-- max_score is optional: null means "feedback only, no mark".
alter table assignments add column if not exists max_score numeric(6,2) check (max_score is null or max_score > 0);

create or replace function guard_assignment() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(auth.uid(), new.created_by);
    return new;
  end if;
  if tg_op = 'DELETE' then
    if exists (select 1 from submissions s where s.assignment_id = old.id) then
      raise exception 'This assignment already has submissions and cannot be deleted';
    end if;
    return old;
  end if;
  -- UPDATE: cohort and marking scale are locked once work has been handed in
  if exists (select 1 from submissions s where s.assignment_id = old.id)
     and (new.cohort_id <> old.cohort_id or new.max_score is distinct from old.max_score or new.track_id is distinct from old.track_id) then
    raise exception 'Cohort, track and maximum score cannot change once submissions exist';
  end if;
  new.created_by := old.created_by;
  return new;
end $$;
create trigger trg_guard_assignment before insert or update or delete on assignments for each row execute function guard_assignment();
create trigger aud_assignments after insert or update or delete on assignments for each row execute function audit_row();

-- ---------- 2. Submissions ----------
-- Participants insert their own work. The database decides the attempt number, the on-time/late status
-- and clears any grading fields, so none of it can be set from the browser.
create or replace function guard_submission() returns trigger language plpgsql security definer set search_path = public as $$
declare
  a record; owner uuid; last_attempt int; last_status submission_status; newer boolean;
begin
  select * into a from assignments where id = new.assignment_id;
  if not found then raise exception 'Assignment not found'; end if;

  if tg_op = 'INSERT' then
    if not exists (select 1 from cohort_enrolments e where e.participant_id = new.participant_id and e.cohort_id = a.cohort_id
                   and (a.track_id is null or e.track_id = a.track_id)) then
      raise exception 'You are not enrolled for this assignment';
    end if;
    if coalesce(btrim(new.body), '') = '' and new.storage_path is null then
      raise exception 'Add your answer or attach a file';
    end if;
    if new.storage_path is not null then
      select profile_id into owner from participants where id = new.participant_id;
      if left(new.storage_path, 37) <> owner::text || '/' then raise exception 'Invalid file location'; end if;
    end if;

    select attempt, status into last_attempt, last_status from submissions
      where assignment_id = new.assignment_id and participant_id = new.participant_id order by attempt desc limit 1;
    if found then
      if not a.allow_resubmission then raise exception 'Resubmission is not allowed for this assignment'; end if;
      if last_status <> 'returned' then raise exception 'You can submit again only after your trainer returns your work'; end if;
      new.attempt := last_attempt + 1;
    else
      new.attempt := 1;
    end if;

    new.status := case when a.due_at is not null and now() > a.due_at then 'late' else 'submitted' end;
    new.submitted_at := now();
    new.feedback := null; new.score := null; new.graded_by := null;
    return new;
  end if;

  -- UPDATE (grading by a trainer or staff)
  if new.assignment_id <> old.assignment_id or new.participant_id <> old.participant_id or new.attempt <> old.attempt
     or new.body is distinct from old.body or new.storage_path is distinct from old.storage_path or new.submitted_at <> old.submitted_at then
    raise exception 'Submitted work cannot be changed';
  end if;
  if new.status is not distinct from old.status and new.score is not distinct from old.score and new.feedback is not distinct from old.feedback then
    return new;   -- nothing graded
  end if;

  select exists (select 1 from submissions s where s.assignment_id = new.assignment_id and s.participant_id = new.participant_id and s.attempt > new.attempt) into newer;
  if newer then raise exception 'Only the latest attempt can be graded'; end if;

  if new.status not in ('graded', 'returned') then raise exception 'Grade the work or return it for revision'; end if;
  if new.status = 'graded' then
    if a.max_score is null then
      if new.score is not null then raise exception 'This assignment has no marks; give feedback only'; end if;
    else
      if new.score is null then raise exception 'Enter a score'; end if;
      if new.score < 0 or new.score > a.max_score then raise exception 'Score must be between 0 and %', a.max_score; end if;
    end if;
  else  -- returned for revision
    if not a.allow_resubmission then raise exception 'This assignment does not allow resubmission'; end if;
    if coalesce(btrim(new.feedback), '') = '' then raise exception 'Say what needs to change before returning the work'; end if;
    if new.score is not null then raise exception 'A returned submission has no score yet'; end if;
  end if;
  new.graded_by := coalesce(auth.uid(), old.graded_by);
  return new;
end $$;
create trigger trg_guard_submission before insert or update on submissions for each row execute function guard_submission();
create trigger aud_submissions after insert or update or delete on submissions for each row execute function audit_row();

-- Trainers: read and grade only (the old policy allowed insert and delete as well). Staff may grade too.
drop policy if exists sub_trainer on submissions;
create policy sub_trainer_read on submissions for select to authenticated using (trainer_can_see_participant(participant_id));
create policy sub_grade on submissions for update to authenticated
  using (is_staff() or (app_role() = 'trainer' and trainer_can_see_participant(participant_id)))
  with check (is_staff() or (app_role() = 'trainer' and trainer_can_see_participant(participant_id)));
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000006', 'assignments_grading');
commit;

\echo '== migration 20260101000007 resources_visibility'
begin;
-- DIRA LEARN: participant-facing learning resources
-- STATUS: written, NOT yet executed. Run `supabase db reset` and `supabase test db` and fix any errors.
--
-- Problems in the earlier policies, fixed here:
--  * participants could read EVERY resource, including trainer-only prep material;
--  * applicants could read core resources (the policy never checked the reader was a participant);
--  * any signed-in user could read any file in the learning-resources bucket;
--  * external_url accepted any text (for example a javascript: link).

-- 1. Trainers choose what participants see. Default is trainers-only so nothing is shared by accident.
alter table learning_resources add column if not exists visible_to_participants boolean not null default false;

-- NOT VALID: enforced for every new or changed row; existing rows (if any) are not re-checked.
alter table learning_resources add constraint chk_resource_url
  check (external_url is null or external_url ~* '^https?://[^[:space:]]+$') not valid;

create or replace function set_resource_uploader() returns trigger language plpgsql security definer set search_path = public as $$
begin new.uploaded_by := coalesce(auth.uid(), new.uploaded_by); return new; end $$;
create trigger trg_resource_uploader before insert on learning_resources for each row execute function set_resource_uploader();
create trigger aud_resources after insert or update or delete on learning_resources for each row execute function audit_row();

-- 2. Row access. Participants: shared items only, core or their own track, and not once withdrawn.
drop policy if exists res_read on learning_resources;
create policy res_read on learning_resources for select to authenticated using (
  is_staff() or app_role() in ('trainer', 'me_officer')
  or (app_role() = 'participant' and visible_to_participants
      and exists (select 1 from participants p where p.id = my_participant_id() and p.status <> 'withdrawn')
      and (track_id is null or track_id in (select e.track_id from cohort_enrolments e where e.participant_id = my_participant_id())))
);

-- 3. File access follows the row: a file can be read only if the caller can read its learning_resources row
-- (the subquery runs under the caller's own row-level security).
drop policy if exists storage_resources_read on storage.objects;
create policy storage_resources_read on storage.objects for select to authenticated using (
  bucket_id = 'learning-resources'
  and (is_staff() or app_role() in ('trainer', 'me_officer')
       or exists (select 1 from learning_resources r where r.storage_path = storage.objects.name))
);
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000007', 'resources_visibility');
commit;

\echo '== migration 20260101000008 assignment_components'
begin;
-- DIRA LEARN: tag each assignment with the assessment component it feeds.
-- STATUS: written, NOT yet executed. Run `supabase db reset` and `supabase test db` and fix any errors.
-- The component decides where a graded score counts in the (unapproved, draft) weighted result:
--   task          -> "Session tasks and portfolio" (30% draft)
--   final_project -> "Final track project/demonstration" (40% draft)
--   reflection    -> "Reflection and next-step plan" (10% draft)
-- Engagement (20% draft) comes from attendance, not from an assignment.
alter table assignments add column if not exists component text not null default 'task'
  check (component in ('task', 'final_project', 'reflection'));

-- Once work has been handed in, changing the component would silently change people's results.
create or replace function guard_assignment_component() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.component is distinct from old.component
     and exists (select 1 from submissions s where s.assignment_id = old.id) then
    raise exception 'The assessment component cannot change once submissions exist';
  end if;
  return new;
end $$;
drop trigger if exists trg_guard_assignment_component on assignments;
create trigger trg_guard_assignment_component before update on assignments for each row execute function guard_assignment_component();
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000008', 'assignment_components');
commit;

\echo '== migration 20260101000009 remaining_modules'
begin;
-- DIRA LEARN: mentorship, M&E, certificates and alumni, notifications, projects, settings, safeguarding, user management
-- STATUS: written, NOT yet executed. Run `supabase db reset` and `supabase test db` and fix any errors.

-- ============ 0. Profile guards ============
-- A trusted session is the service role (Edge Functions) or a direct database connection (SQL editor, migrations, tests).
-- Requests through the API always carry a JWT, so they are never trusted this way.
-- Bug fix: the old guard blocked the service role (auth.uid() is null there), so convert-application could not set a role.
create or replace function is_trusted_session() returns boolean language sql stable as $$
  select coalesce(auth.role(), '') = 'service_role' or coalesce(current_setting('request.jwt.claims', true), '') = '' $$;

create or replace function guard_profile_privileged() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if is_trusted_session() then return new; end if;
  if (new.role is distinct from old.role or new.status is distinct from old.status or new.organization_id is distinct from old.organization_id)
     and not is_admin() then
    raise exception 'Only a super administrator can change role, status or organisation';
  end if;
  return new;
end $$;

-- Role changes must keep the data consistent, and the system must never lose its last administrator.
create or replace function guard_profile_integrity() returns trigger language plpgsql security definer set search_path = public as $$
declare has_participant boolean; remaining int;
begin
  if is_trusted_session() then return new; end if;
  if new.role is distinct from old.role or new.status is distinct from old.status then
    if auth.uid() = old.id then
      raise exception 'You cannot change your own role or status';
    end if;
  end if;
  if new.role is distinct from old.role then
    select exists (select 1 from participants where profile_id = new.id) into has_participant;
    if new.role = 'participant' and not has_participant then
      raise exception 'A participant account is created by converting an accepted application';
    end if;
    if old.role = 'participant' and has_participant then
      raise exception 'A participant cannot be given another role. Mark the participant as withdrawn instead';
    end if;
  end if;
  if old.role = 'super_admin' and old.status = 'active' and (new.role <> 'super_admin' or new.status <> 'active') then
    select count(*) into remaining from profiles where role = 'super_admin' and status = 'active' and id <> old.id;
    if remaining = 0 then raise exception 'There must always be at least one active super administrator'; end if;
  end if;
  return new;
end $$;
create trigger trg_guard_profile_integrity before update on profiles for each row execute function guard_profile_integrity();

-- Mentees can see the name of their own mentor.
create policy profiles_mentee on profiles for select to authenticated
  using (id in (select mentor_id from mentorship_assignments where participant_id = my_participant_id()));

-- Super administrators see account emails and last sign-in (auth.users is otherwise unreadable).
create or replace function admin_list_users()
returns table(id uuid, email text, role role_code, status account_status, first_name text, last_name text, created_at timestamptz, last_sign_in_at timestamptz)
language sql stable security definer set search_path = public, auth as $$
  select p.id, u.email::text, p.role, p.status, p.first_name, p.last_name, p.created_at, u.last_sign_in_at
  from profiles p join auth.users u on u.id = p.id
  where is_admin() order by p.created_at desc $$;
revoke all on function admin_list_users() from public, anon;
grant execute on function admin_list_users() to authenticated;

-- ============ 1. Mentorship ============
alter table mentorship_sessions add column if not exists shared_with_mentee boolean not null default false;
alter table mentorship_sessions add column if not exists created_at timestamptz not null default now();
-- One mentor per participant (proposal: keeps the participant view simple).
create unique index if not exists uq_one_mentor_per_participant on mentorship_assignments(participant_id);

create or replace function guard_mentorship_assignment() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from profiles where id = new.mentor_id and role = 'mentor' and status = 'active') then
    raise exception 'The mentor must be an active account with the mentor role';
  end if;
  if exists (select 1 from participants where id = new.participant_id and status = 'withdrawn') then
    raise exception 'A withdrawn participant cannot be given a mentor';
  end if;
  return new;
end $$;
create trigger trg_guard_mentorship_assignment before insert or update on mentorship_assignments for each row execute function guard_mentorship_assignment();
create trigger aud_mentorship after insert or update or delete on mentorship_assignments for each row execute function audit_row();

create or replace function guard_mentorship_session() returns trigger language plpgsql as $$
begin
  if new.held_on > current_date then raise exception 'A mentoring session cannot be dated in the future'; end if;
  if jsonb_typeof(new.action_points) is distinct from 'array' then raise exception 'Action points must be a list'; end if;
  if jsonb_array_length(new.action_points) > 20 then raise exception 'At most 20 action points per session'; end if;
  return new;
end $$;
create trigger trg_guard_mentorship_session before insert or update on mentorship_sessions for each row execute function guard_mentorship_session();

-- The mentor chooses per session whether the mentee can read it (default: private to the mentor and staff).
create policy ms_mentee_read on mentorship_sessions for select to authenticated using (
  shared_with_mentee and exists (select 1 from mentorship_assignments a where a.id = assignment_id and a.participant_id = my_participant_id()));

-- ============ 2. Monitoring and evaluation ============
alter table me_indicators add column if not exists created_by uuid references profiles(id);
alter table me_indicators add column if not exists is_active boolean not null default true;
alter table me_records add column if not exists note text;
alter table me_records add column if not exists recorded_by uuid references profiles(id);
alter table me_records add constraint chk_me_value check (
  (data_quality = 'missing' and value is null) or (data_quality <> 'missing' and value is not null));

create policy me_indicators_me on me_indicators for all to authenticated
  using (app_role() = 'me_officer') with check (app_role() = 'me_officer');

create or replace function guard_me_record() returns trigger language plpgsql security definer set search_path = public as $$
declare ind_prog uuid; coh_prog uuid;
begin
  new.recorded_by := coalesce(auth.uid(), new.recorded_by);
  if new.cohort_id is not null then
    select programme_id into ind_prog from me_indicators where id = new.indicator_id;
    select programme_id into coh_prog from cohorts where id = new.cohort_id;
    if ind_prog is not null and coh_prog is distinct from ind_prog then
      raise exception 'The cohort does not belong to the indicator''s programme';
    end if;
  end if;
  return new;
end $$;
create trigger trg_guard_me_record before insert or update on me_records for each row execute function guard_me_record();
create trigger aud_me_indicators after insert or update or delete on me_indicators for each row execute function audit_row();
create trigger aud_me_records after insert or update or delete on me_records for each row execute function audit_row();

-- ============ 3. Graduation rules, certificates, alumni ============
alter table graduation_rules add column if not exists require_final_project boolean not null default true;
alter table graduation_rules add column if not exists require_reflection boolean not null default true;
alter table graduation_rules add column if not exists updated_at timestamptz not null default now();
create unique index if not exists uq_graduation_rule_programme on graduation_rules(programme_id);

-- Editing an approved rule sends it back to draft. Approval records who and when. No overall-percent rule yet:
-- the weights are unapproved, so a threshold on them would be a guess.
create or replace function guard_graduation_rule() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.min_overall_percent is not null then raise exception 'An overall-percent rule is not supported until assessment weights are approved'; end if;
  if new.min_sessions_attended is not null and new.min_sessions_attended < 1 then raise exception 'Minimum sessions must be at least 1'; end if;
  if tg_op = 'UPDATE' and old.is_approved and (
       new.min_sessions_attended is distinct from old.min_sessions_attended or new.require_core_sessions is distinct from old.require_core_sessions
       or new.require_final_project is distinct from old.require_final_project or new.require_reflection is distinct from old.require_reflection) then
    new.is_approved := false;
  end if;
  if new.is_approved and (tg_op = 'INSERT' or not old.is_approved) then new.approved_by := auth.uid(); new.approved_at := now(); end if;
  if not new.is_approved then new.approved_by := null; new.approved_at := null; end if;
  new.updated_at := now();
  return new;
end $$;
create trigger trg_guard_graduation_rule before insert or update on graduation_rules for each row execute function guard_graduation_rule();
create trigger aud_graduation_rules after insert or update or delete on graduation_rules for each row execute function audit_row();

alter table certificates add column if not exists rules_id uuid references graduation_rules(id);
alter table certificates add column if not exists revoked_at timestamptz;
alter table certificates add column if not exists revoked_by uuid references profiles(id);
alter table certificates add column if not exists revoked_reason text;

-- Certificates change only through issue_certificate() and revoke_certificate(); direct writes are refused.
create or replace function guard_certificate_write() returns trigger language plpgsql as $$
begin
  if coalesce(current_setting('app.certificate_fn', true), '') <> '1' then
    raise exception 'Certificates are issued and revoked only through issue_certificate and revoke_certificate';
  end if;
  return coalesce(new, old);
end $$;
create trigger trg_guard_certificate_write before insert or update or delete on certificates for each row execute function guard_certificate_write();

-- What a participant has done in one cohort, using the same counting as the results page.
-- security invoker: the caller's own row-level security applies.
create or replace function participant_completion(p_participant uuid, p_cohort uuid)
returns table(sessions_attended int, core_attended int, core_total int, final_submitted boolean, reflection_submitted boolean)
language sql stable set search_path = public as $$
  with enrol as (select track_id from cohort_enrolments where participant_id = p_participant and cohort_id = p_cohort),
  sched as (
    select s.id, s.curriculum_session_id, cs.track_id from session_schedules s join curriculum_sessions cs on cs.id = s.curriculum_session_id
    where s.cohort_id = p_cohort and s.status <> 'cancelled'),
  att as (
    select distinct sc.curriculum_session_id, (sc.track_id is null) as is_core
    from sched sc join attendance a on a.schedule_id = sc.id
    where a.participant_id = p_participant and a.status in ('present', 'late')
      and (sc.track_id is null or sc.track_id = (select track_id from enrol)))
  select (select count(*)::int from att),
         (select count(*) filter (where is_core)::int from att),
         (select count(distinct curriculum_session_id)::int from sched where track_id is null),
         exists (select 1 from submissions sub join assignments asg on asg.id = sub.assignment_id
                 where sub.participant_id = p_participant and asg.cohort_id = p_cohort and asg.component = 'final_project'),
         exists (select 1 from submissions sub join assignments asg on asg.id = sub.assignment_id
                 where sub.participant_id = p_participant and asg.cohort_id = p_cohort and asg.component = 'reflection') $$;

create or replace function issue_certificate(p_participant uuid, p_cohort uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare prog uuid; r graduation_rules; c record; cid uuid; pstatus participant_status; pprofile uuid;
begin
  if app_role() not in ('super_admin', 'programme_director') then raise exception 'Only a super administrator or programme director can issue certificates'; end if;
  select programme_id into prog from cohorts where id = p_cohort;
  if prog is null then raise exception 'Cohort not found'; end if;
  if not exists (select 1 from cohort_enrolments where cohort_id = p_cohort and participant_id = p_participant) then raise exception 'The participant is not enrolled in this cohort'; end if;
  select status, profile_id into pstatus, pprofile from participants where id = p_participant;
  if pstatus = 'withdrawn' then raise exception 'A withdrawn participant cannot receive a certificate'; end if;
  select * into r from graduation_rules where programme_id = prog and is_approved;
  if not found then raise exception 'Graduation rules have not been approved by management'; end if;
  if exists (select 1 from certificates where participant_id = p_participant and cohort_id = p_cohort and not revoked) then raise exception 'This participant already has an active certificate for this cohort'; end if;

  select * into c from participant_completion(p_participant, p_cohort);
  if r.min_sessions_attended is not null and c.sessions_attended < r.min_sessions_attended then
    raise exception 'Attendance requirement not met (% of % sessions)', c.sessions_attended, r.min_sessions_attended; end if;
  if r.require_core_sessions and (c.core_total = 0 or c.core_attended < c.core_total) then raise exception 'Core sessions requirement not met'; end if;
  if r.require_final_project and not c.final_submitted then raise exception 'The final project has not been submitted'; end if;
  if r.require_reflection and not c.reflection_submitted then raise exception 'The reflection has not been submitted'; end if;

  perform set_config('app.certificate_fn', '1', true);
  insert into certificates(participant_id, cohort_id, issued_by, rules_id) values (p_participant, p_cohort, auth.uid(), r.id) returning id into cid;
  perform set_config('app.certificate_fn', '', true);
  update participants set status = 'graduated' where id = p_participant and status in ('enrolled', 'active', 'completed');
  insert into notifications(user_id, kind, title, body) values (pprofile, 'certificate', 'Your certificate is ready', 'Open Certificates to view or print it.');
  return cid;
end $$;
grant execute on function issue_certificate(uuid, uuid) to authenticated;

create or replace function revoke_certificate(p_certificate uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare pprofile uuid; n int;
begin
  if app_role() not in ('super_admin', 'programme_director') then raise exception 'Only a super administrator or programme director can revoke certificates'; end if;
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'A written reason is required'; end if;
  perform set_config('app.certificate_fn', '1', true);
  update certificates set revoked = true, revoked_at = now(), revoked_by = auth.uid(), revoked_reason = trim(p_reason)
    where id = p_certificate and not revoked;
  get diagnostics n = row_count;  -- PERFORM would overwrite FOUND, so count rows explicitly
  perform set_config('app.certificate_fn', '', true);
  if n = 0 then raise exception 'Certificate not found or already revoked'; end if;
  select p.profile_id into pprofile from certificates c join participants p on p.id = c.participant_id where c.id = p_certificate;
  insert into notifications(user_id, kind, title, body) values (pprofile, 'certificate', 'A certificate was withdrawn', 'Please contact the programme team if you have questions.');
end $$;
grant execute on function revoke_certificate(uuid, text) to authenticated;

-- Alumni: staff move a graduate into the alumni list; alumni keep their own follow-up record up to date.
create or replace function mark_alumni(p_participant uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if not is_staff() then raise exception 'Only programme staff can do this'; end if;
  if not exists (select 1 from participants where id = p_participant and status = 'graduated') then raise exception 'Only a graduated participant can become an alumnus'; end if;
  update participants set status = 'alumni' where id = p_participant;
  insert into alumni(participant_id) values (p_participant) on conflict (participant_id) do nothing;
end $$;
grant execute on function mark_alumni(uuid) to authenticated;
create trigger trg_alumni_upd before update on alumni for each row execute function set_updated_at();

-- ============ 4. Notifications and announcements ============
create or replace function set_announcement_author() returns trigger language plpgsql as $$
begin new.created_by := coalesce(auth.uid(), new.created_by); return new; end $$;
create trigger trg_announcement_author before insert on announcements for each row execute function set_announcement_author();

-- Every announcement becomes an in-app notification for the people it is addressed to.
create or replace function announcement_notify() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into notifications(user_id, kind, title, body)
  select distinct s.u, 'announcement', new.title, left(new.body, 200) from (
    select p.profile_id as u from participants p join cohort_enrolments e on e.participant_id = p.id
      where new.cohort_id is not null and e.cohort_id = new.cohort_id and p.status <> 'withdrawn'
    union select ta.trainer_id from trainer_assignments ta where new.cohort_id is not null and ta.cohort_id = new.cohort_id
    union select pr.id from profiles pr where new.cohort_id is null and pr.status = 'active' and pr.role in ('participant', 'trainer', 'mentor', 'me_officer')
      and not exists (select 1 from participants p where p.profile_id = pr.id and p.status = 'withdrawn')
  ) s where s.u is not null and s.u is distinct from new.created_by;
  return new;
end $$;
create trigger trg_announcement_notify after insert on announcements for each row execute function announcement_notify();
-- Announcements are a record of what people were told: staff can post but not edit or delete.
drop policy if exists ann_write on announcements;
create policy ann_insert on announcements for insert to authenticated with check (is_staff());
create trigger aud_announcements after insert or update or delete on announcements for each row execute function audit_row();

create or replace function notify_submission_update() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into notifications(user_id, kind, title, body)
  select p.profile_id, 'assignment', case when new.status = 'graded' then 'Your work was graded' else 'Your work was returned for revision' end,
         (select a.title from assignments a where a.id = new.assignment_id)
  from participants p where p.id = new.participant_id;
  return new;
end $$;
create trigger trg_notify_submission after update of status on submissions for each row
  when (old.status is distinct from new.status and new.status in ('graded', 'returned')) execute function notify_submission_update();

-- Neutral wording on purpose: the decision itself is read in the application, not in a notification.
-- Acceptance is announced when the application is converted (Edge Function), so it is not repeated here.
create or replace function notify_application_update() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into notifications(user_id, kind, title, body) values (new.applicant_id, 'application', 'There is an update on your application', 'Open My application to read it.');
  return new;
end $$;
create trigger trg_notify_application after update of status on applications for each row
  when (old.status is distinct from new.status and new.status in ('shortlisted', 'waitlisted', 'rejected')) execute function notify_application_update();

-- People may mark their notifications read, but not rewrite them.
create or replace function guard_notification_update() returns trigger language plpgsql as $$
begin
  if new.user_id is distinct from old.user_id or new.kind is distinct from old.kind or new.title is distinct from old.title
     or new.body is distinct from old.body or new.created_at is distinct from old.created_at then
    raise exception 'Only the read time of a notification can be changed';
  end if;
  return new;
end $$;
create trigger trg_guard_notification before update on notifications for each row execute function guard_notification_update();

-- ============ 5. Projects and portfolio ============
alter table participant_projects add constraint chk_project_status check (status in ('in_progress', 'submitted', 'needs_revision', 'reviewed'));
alter table participant_projects add constraint chk_project_milestones check (jsonb_typeof(milestones) = 'array');

create or replace function guard_project() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if app_role() = 'participant' then
    if exists (select 1 from participants where id = my_participant_id() and status = 'withdrawn') then raise exception 'Withdrawn participants cannot change projects'; end if;
    if tg_op = 'INSERT' then
      new.feedback := null; new.status := 'in_progress';
    else
      if new.participant_id is distinct from old.participant_id or new.feedback is distinct from old.feedback then raise exception 'You cannot change feedback or ownership'; end if;
      if old.status in ('submitted', 'reviewed') then raise exception 'This project is locked until a trainer returns it'; end if;
      if new.status = 'needs_revision' then new.status := 'in_progress'; end if;  -- editing a returned project means working on it again
      if new.status not in ('in_progress', 'submitted') then raise exception 'You can only keep working or submit'; end if;
    end if;
  end if;
  return new;
end $$;
create trigger trg_guard_project before insert or update on participant_projects for each row execute function guard_project();
create trigger aud_projects after insert or update or delete on participant_projects for each row execute function audit_row();

create or replace function guard_project_evidence() returns trigger language plpgsql security definer set search_path = public as $$
declare pstatus text; powner uuid;
begin
  if app_role() = 'participant' then
    select status, participant_id into pstatus, powner from participant_projects where id = new.project_id;
    if powner is distinct from my_participant_id() then raise exception 'Not your project'; end if;
    if pstatus not in ('in_progress', 'needs_revision') then raise exception 'Evidence cannot be added while the project is submitted or reviewed'; end if;
    if new.storage_path not like auth.uid()::text || '/%' then raise exception 'Evidence files must be stored in your own folder'; end if;
  end if;
  return new;
end $$;
create trigger trg_guard_project_evidence before insert on project_evidence for each row execute function guard_project_evidence();

-- ============ 6. Settings (approval workflow) ============
alter table system_settings add column if not exists approved_by uuid references profiles(id);
alter table system_settings add column if not exists approved_at timestamptz;
create or replace function guard_setting() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and old.is_approved and new.value is distinct from old.value then new.is_approved := false; end if;
  if new.is_approved and (tg_op = 'INSERT' or not old.is_approved) then new.approved_by := auth.uid(); new.approved_at := now(); end if;
  if not new.is_approved then new.approved_by := null; new.approved_at := null; end if;
  new.updated_at := now();
  return new;
end $$;
create trigger trg_guard_setting before insert or update on system_settings for each row execute function guard_setting();

-- ============ 7. Safeguarding (super administrator only; no delete) ============
alter table safeguarding_records add column if not exists status text not null default 'open';
alter table safeguarding_records add column if not exists updated_at timestamptz not null default now();
alter table safeguarding_records add constraint chk_safeguarding_status check (status in ('open', 'under_review', 'closed'));
alter table safeguarding_records add constraint chk_safeguarding_severity check (severity is null or severity in ('low', 'medium', 'high'));
drop policy if exists safe_admin on safeguarding_records;
create policy safe_admin_read on safeguarding_records for select to authenticated using (is_admin());
create policy safe_admin_insert on safeguarding_records for insert to authenticated with check (is_admin());
create policy safe_admin_update on safeguarding_records for update to authenticated using (is_admin()) with check (is_admin());
create or replace function guard_safeguarding() returns trigger language plpgsql as $$
begin
  if tg_op = 'INSERT' then new.reported_by := coalesce(auth.uid(), new.reported_by);
  else new.reported_by := old.reported_by; new.created_at := old.created_at; end if;
  new.updated_at := now();
  return new;
end $$;
create trigger trg_guard_safeguarding before insert or update on safeguarding_records for each row execute function guard_safeguarding();
-- No audit trigger on purpose: it would copy case details into a second table.

