\echo '== migration 20260101000010 email_system'
begin;
-- DIRA LEARN: email system (templates, outbox, bulk sends, reminders, event emails).
-- STATUS: written, NOT yet executed. Sending itself happens in the `send-emails` Edge Function using RESEND_API_KEY,
-- which lives only in the function environment. Without that key nothing is sent and the outbox simply stays queued.
-- Supabase Auth's own emails (sign-up confirmation, password reset) are NOT sent from here: point Supabase Auth SMTP at the
-- same provider (see docs/EMAIL_SETUP.md).

alter table profiles add column if not exists email_opt_out boolean not null default false;  -- skipped by bulk and announcement email

-- ============ templates ============
create table email_templates (
  id uuid primary key default gen_random_uuid(),
  key text not null unique check (key ~ '^[a-z][a-z0-9_]{2,40}$'),
  name text not null,
  subject text not null check (length(subject) between 3 and 200),
  body text not null check (length(body) between 3 and 10000),   -- plain text with {{placeholders}}; the sender wraps it in the DIRA layout
  is_system boolean not null default false,                      -- system templates are used by automation; they can be edited, not deleted
  is_active boolean not null default true,
  updated_by uuid references profiles(id),
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);
alter table email_templates enable row level security;
create policy emailtpl_read on email_templates for select to authenticated using (is_staff());
create policy emailtpl_insert on email_templates for insert to authenticated with check (is_staff() and not is_system);
create policy emailtpl_update on email_templates for update to authenticated using (is_staff()) with check (is_staff());
create policy emailtpl_delete on email_templates for delete to authenticated using (is_staff() and not is_system);
create or replace function guard_email_template() returns trigger language plpgsql as $$
begin
  new.updated_by := coalesce(auth.uid(), new.updated_by); new.updated_at := now();
  if tg_op = 'UPDATE' and (new.key is distinct from old.key or new.is_system is distinct from old.is_system) then raise exception 'A template key cannot be changed'; end if;
  return new;
end $$;
create trigger trg_email_template before insert or update on email_templates for each row execute function guard_email_template();
create trigger aud_email_templates after insert or update or delete on email_templates for each row execute function audit_row();

-- Draft wording for the templates automation uses. Management should review and edit it before switching automation on.
insert into email_templates(key, name, subject, body, is_system) values
 ('notification', 'In-app notification copy', '{{title}}', E'Hello {{first_name}},\n\n{{body}}\n\nSign in to DIRA Learn for details.', true),
 ('session_reminder', 'Session reminder', 'Reminder: {{session_title}} on {{session_date}}', E'Hello {{first_name}},\n\nThis is a reminder that "{{session_title}}" for {{cohort_name}} starts on {{session_date}} at {{session_time}} ({{session_mode}}).\n{{session_place}}\n\nSee you there.', true),
 ('assignment_reminder', 'Assignment due reminder', 'Reminder: {{assignment_title}} is due {{due_date}}', E'Hello {{first_name}},\n\nYour assignment "{{assignment_title}}" for {{cohort_name}} is due on {{due_date}}. Sign in to DIRA Learn to submit it.', true),
 ('cohort_welcome', 'Cohort welcome', 'Welcome to {{cohort_name}}', E'Hello {{first_name}},\n\nYou are enrolled in {{cohort_name}} ({{programme_name}}). Sign in to DIRA Learn to see your schedule.', false)
on conflict (key) do nothing;

-- ============ outbox ============
create type email_status as enum ('queued', 'sending', 'sent', 'delivered', 'bounced', 'complained', 'failed', 'cancelled');
create table email_outbox (
  id uuid primary key default gen_random_uuid(),
  to_user_id uuid references profiles(id) on delete set null,
  to_email text not null,
  template_key text,
  campaign text,                                     -- label for bulk sends and automation, for reporting
  subject text not null,
  body text not null,                                -- fully rendered plain text
  status email_status not null default 'queued',
  scheduled_for timestamptz not null default now(),
  attempts int not null default 0,
  provider_id text,                                  -- id returned by the email provider; the webhook matches on it
  error text,
  sent_at timestamptz,
  claimed_at timestamptz,
  created_by uuid references profiles(id),
  created_at timestamptz not null default now()
);
create index on email_outbox(status, scheduled_for);
create index on email_outbox(provider_id);
alter table email_outbox enable row level security;
-- Addresses and message bodies are personal data: only the programme management roles can read them. All writes go through functions.
create policy emailout_read on email_outbox for select to authenticated using (is_staff());
revoke insert, update, delete on email_outbox from authenticated, anon;

create table email_reminder_log (        -- prevents sending the same reminder twice
  kind text not null, ref_id uuid not null, user_id uuid not null references profiles(id) on delete cascade, created_at timestamptz not null default now(),
  primary key (kind, ref_id, user_id)
);
alter table email_reminder_log enable row level security;   -- no policies: functions only

-- ============ rendering ============
create or replace function render_text(t text, v jsonb) returns text language plpgsql immutable as $$
declare k text; val text; out text := t;
begin
  for k, val in select * from jsonb_each_text(v) loop out := replace(out, '{{' || k || '}}', coalesce(val, '')); end loop;
  if out ~ '\{\{[a-z_]+\}\}' then raise exception 'Unresolved placeholder in template: %', (regexp_match(out, '\{\{[a-z_]+\}\}'))[1]; end if;
  return out;
end $$;

create or replace function email_automation_enabled() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select (value->>'enabled')::boolean and is_approved from system_settings where key = 'email_automation'), false) $$;
insert into system_settings(key, value, note) values ('email_automation', '{"enabled": false}', 'Automatic emails (reminders and event emails). Off until management approves it.') on conflict (key) do nothing;

-- Core enqueue: one rendered email for one user. Internal; callers check permission.
create or replace function _enqueue_email(p_user uuid, p_template text, p_vars jsonb, p_when timestamptz, p_campaign text, p_by uuid) returns uuid
language plpgsql security definer set search_path = public, auth as $$
declare t email_templates; u record; v jsonb; new_id uuid;
begin
  select * into t from email_templates where key = p_template and is_active;
  if not found then return null; end if;
  select p.id, p.first_name, p.last_name, p.status, au.email::text as email into u from profiles p join auth.users au on au.id = p.id where p.id = p_user;
  if not found or u.email is null or u.status = 'deactivated' then return null; end if;
  v := jsonb_build_object('first_name', coalesce(nullif(u.first_name, ''), 'there'), 'last_name', coalesce(u.last_name, '')) || coalesce(p_vars, '{}'::jsonb);
  insert into email_outbox(to_user_id, to_email, template_key, campaign, subject, body, scheduled_for, created_by)
  values (u.id, u.email, p_template, p_campaign, render_text(t.subject, v), render_text(t.body, v), coalesce(p_when, now()), p_by) returning email_outbox.id into new_id;
  return new_id;
end $$;
revoke all on function _enqueue_email(uuid, text, jsonb, timestamptz, text, uuid) from public, anon, authenticated;

-- Bulk send for management: audience is a cohort's participants, all participants, or all staff. Opted-out people are skipped.
create or replace function enqueue_bulk_email(p_template text, p_audience text, p_cohort uuid, p_when timestamptz) returns int
language plpgsql security definer set search_path = public as $$
declare r record; n int := 0; vars jsonb; label text;
begin
  if not is_staff() then raise exception 'Only programme management can send email'; end if;
  if p_when is not null and p_when < now() - interval '5 minutes' then raise exception 'The scheduled time is in the past'; end if;
  if p_audience not in ('cohort', 'all_participants', 'all_staff') then raise exception 'Unknown audience'; end if;
  if p_audience = 'cohort' and p_cohort is null then raise exception 'Choose a cohort'; end if;
  if not exists (select 1 from email_templates where key = p_template and is_active) then raise exception 'Template not found or switched off'; end if;
  label := 'bulk:' || p_template || ':' || to_char(now(), 'YYYY-MM-DD HH24:MI');
  for r in
    select distinct pr.id as uid, c.name as cohort_name, g.name as programme_name
    from profiles pr
    left join participants pa on pa.profile_id = pr.id
    left join cohort_enrolments e on e.participant_id = pa.id and (p_audience <> 'cohort' or e.cohort_id = p_cohort)
    left join cohorts c on c.id = e.cohort_id
    left join programmes g on g.id = c.programme_id
    where pr.status = 'active' and not pr.email_opt_out
      and ((p_audience = 'cohort' and e.cohort_id = p_cohort and pa.status <> 'withdrawn')
        or (p_audience = 'all_participants' and pr.role = 'participant' and pa.status <> 'withdrawn')
        or (p_audience = 'all_staff' and pr.role in ('super_admin', 'programme_director', 'programme_coordinator', 'trainer', 'me_officer', 'mentor')))
  loop
    n := n + 1;
    if n > 500 then raise exception 'An audience is limited to 500 people per send'; end if;
    vars := jsonb_build_object('cohort_name', coalesce(r.cohort_name, ''), 'programme_name', coalesce(r.programme_name, ''));
    perform _enqueue_email(r.uid, p_template, vars, p_when, label, auth.uid());
  end loop;
  return n;
end $$;
grant execute on function enqueue_bulk_email(text, text, uuid, timestamptz) to authenticated;

create or replace function cancel_email(p_id uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if not is_staff() then raise exception 'Only programme management can cancel email'; end if;
  update email_outbox set status = 'cancelled' where id = p_id and status = 'queued';
  if not found then raise exception 'Only a queued email can be cancelled'; end if;
end $$;
grant execute on function cancel_email(uuid) to authenticated;

-- ============ event emails: every in-app notification can also become an email (opt-out respected) ============
create or replace function notification_to_email() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not email_automation_enabled() then return new; end if;
  if new.kind not in ('announcement', 'assignment', 'certificate', 'application') then return new; end if;
  if exists (select 1 from profiles where id = new.user_id and email_opt_out) then return new; end if;
  perform _enqueue_email(new.user_id, 'notification', jsonb_build_object('title', new.title, 'body', coalesce(new.body, '')), now(), 'event:' || new.kind, null);
  return new;
end $$;
create trigger trg_notification_to_email after insert on notifications for each row execute function notification_to_email();

-- ============ reminders: called by the send-emails function on its schedule (service role only) ============
create or replace function queue_reminders() returns int language plpgsql security definer set search_path = public as $$
declare r record; n int := 0; new_id uuid;
begin
  if not email_automation_enabled() then return 0; end if;
  -- Sessions starting in the next 24 hours (not cancelled), for enrolled participants who have not opted out.
  for r in
    select s.id as ref, pa.profile_id as uid, cs.title, s.starts_at, s.mode, s.venue, s.meeting_url, c.name as cohort_name
    from session_schedules s join curriculum_sessions cs on cs.id = s.curriculum_session_id join cohorts c on c.id = s.cohort_id
    join cohort_enrolments e on e.cohort_id = s.cohort_id join participants pa on pa.id = e.participant_id
    join profiles pr on pr.id = pa.profile_id
    where s.status in ('scheduled', 'rescheduled') and s.starts_at > now() and s.starts_at <= now() + interval '24 hours'
      and pa.status <> 'withdrawn' and not pr.email_opt_out
      and (cs.track_id is null or cs.track_id = e.track_id)
      and not exists (select 1 from email_reminder_log l where l.kind = 'session' and l.ref_id = s.id and l.user_id = pa.profile_id)
  loop
    new_id := _enqueue_email(r.uid, 'session_reminder', jsonb_build_object('session_title', r.title,
      'session_date', to_char(r.starts_at at time zone 'Africa/Nairobi', 'FMDay DD Mon YYYY'), 'session_time', to_char(r.starts_at at time zone 'Africa/Nairobi', 'HH24:MI') || ' EAT',
      'session_mode', r.mode::text, 'session_place', coalesce(case when r.mode = 'physical' then 'Venue: ' || r.venue else 'Meeting link: ' || coalesce(r.meeting_url, 'will be shared by your trainer') end, ''), 'cohort_name', r.cohort_name), now(), 'reminder:session', null);
    insert into email_reminder_log(kind, ref_id, user_id) values ('session', r.ref, r.uid) on conflict do nothing;
    if new_id is not null then n := n + 1; end if;
  end loop;
  -- Assignments due in the next 48 hours that the participant has not submitted.
  for r in
    select a.id as ref, pa.profile_id as uid, a.title, a.due_at, c.name as cohort_name
    from assignments a join cohorts c on c.id = a.cohort_id join cohort_enrolments e on e.cohort_id = a.cohort_id
    join participants pa on pa.id = e.participant_id join profiles pr on pr.id = pa.profile_id
    where a.due_at > now() and a.due_at <= now() + interval '48 hours' and pa.status <> 'withdrawn' and not pr.email_opt_out
      and (a.track_id is null or a.track_id = e.track_id)
      and not exists (select 1 from submissions sb where sb.assignment_id = a.id and sb.participant_id = pa.id)
      and not exists (select 1 from email_reminder_log l where l.kind = 'assignment' and l.ref_id = a.id and l.user_id = pa.profile_id)
  loop
    new_id := _enqueue_email(r.uid, 'assignment_reminder', jsonb_build_object('assignment_title', r.title,
      'due_date', to_char(r.due_at at time zone 'Africa/Nairobi', 'FMDay DD Mon YYYY HH24:MI') || ' EAT', 'cohort_name', r.cohort_name), now(), 'reminder:assignment', null);
    insert into email_reminder_log(kind, ref_id, user_id) values ('assignment', r.ref, r.uid) on conflict do nothing;
    if new_id is not null then n := n + 1; end if;
  end loop;
  return n;
end $$;
revoke all on function queue_reminders() from public, anon, authenticated;
grant execute on function queue_reminders() to service_role;

-- ============ sender support (service role only) ============
create or replace function claim_emails(p_limit int default 25) returns setof email_outbox language plpgsql security definer set search_path = public as $$
begin
  return query
  update email_outbox set status = 'sending', attempts = attempts + 1, claimed_at = now()
  where id in (select id from email_outbox where status = 'queued' and scheduled_for <= now() and attempts < 3 order by scheduled_for limit greatest(1, least(p_limit, 100)) for update skip locked)
  returning *;
end $$;
revoke all on function claim_emails(int) from public, anon, authenticated;
grant execute on function claim_emails(int) to service_role;

-- A sender that crashed leaves rows in 'sending'; put them back after 15 minutes (the attempt counter still limits retries).
create or replace function requeue_stuck_emails() returns int language sql security definer set search_path = public as $$
  with u as (update email_outbox set status = 'queued' where status = 'sending' and claimed_at < now() - interval '15 minutes' and attempts < 3 returning 1) select count(*)::int from u $$;
revoke all on function requeue_stuck_emails() from public, anon, authenticated;
grant execute on function requeue_stuck_emails() to service_role;

create or replace function email_report(p_from date, p_to date) returns table(status email_status, total bigint)
language sql stable security definer set search_path = public as $$
  select o.status, count(*) from email_outbox o where is_staff() and o.created_at >= p_from and o.created_at < p_to + 1 group by o.status $$;
grant execute on function email_report(date, date) to authenticated;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000010', 'email_system');
commit;

\echo '== migration 20260101000011 courses'
begin;
-- DIRA LEARN: courses as a layer ON TOP of programmes, tracks, cohorts and curriculum sessions.
-- A course belongs to a programme and may optionally be tied to one track and/or one cohort. It does not replace or change
-- the curriculum, sessions, attendance or results; it adds modules, lessons, learning materials, enrolment and progress.
-- STATUS: written, NOT yet executed.

create type course_format as enum ('online', 'physical', 'hybrid', 'self_paced');
create type course_status as enum ('draft', 'published', 'archived');
create type lesson_kind as enum ('reading', 'pdf', 'presentation', 'video', 'link');

create table courses (
  id uuid primary key default gen_random_uuid(),
  programme_id uuid not null references programmes(id),
  track_id uuid references tracks(id),
  cohort_id uuid references cohorts(id),
  title text not null check (length(trim(title)) between 3 and 160),
  summary text check (summary is null or length(summary) <= 2000),
  format course_format not null default 'online',
  status course_status not null default 'draft',
  starts_on date, ends_on date,
  created_by uuid references profiles(id),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  check (ends_on is null or starts_on is null or ends_on >= starts_on)
);
create table course_trainers (
  course_id uuid not null references courses(id) on delete cascade,
  trainer_id uuid not null references profiles(id),
  primary key (course_id, trainer_id)
);
create table course_modules (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references courses(id) on delete cascade,
  position int not null default 0,
  title text not null check (length(trim(title)) between 2 and 160),
  description text check (description is null or length(description) <= 2000),
  created_at timestamptz not null default now()
);
create table course_lessons (
  id uuid primary key default gen_random_uuid(),
  module_id uuid not null references course_modules(id) on delete cascade,
  position int not null default 0,
  title text not null check (length(trim(title)) between 2 and 160),
  kind lesson_kind not null,
  body text check (body is null or length(body) <= 20000),
  storage_path text, external_url text, mime_type text,
  duration_minutes int check (duration_minutes is null or duration_minutes between 1 and 600),
  created_at timestamptz not null default now(),
  check (
    (kind = 'reading' and body is not null and length(trim(body)) > 0)
    or (kind = 'link' and external_url ~ '^https?://')
    or (kind in ('pdf', 'presentation', 'video') and (storage_path is not null or external_url ~ '^https?://'))
  ),
  check (external_url is null or external_url ~ '^https?://')
);
create table course_enrolments (
  course_id uuid not null references courses(id) on delete cascade,
  participant_id uuid not null references participants(id),
  enrolled_at timestamptz not null default now(),
  enrolled_by uuid references profiles(id),
  primary key (course_id, participant_id)
);
create table lesson_progress (
  lesson_id uuid not null references course_lessons(id) on delete cascade,
  participant_id uuid not null references participants(id),
  completed_at timestamptz not null default now(),
  primary key (lesson_id, participant_id)
);
create index on course_modules(course_id, position);
create index on course_lessons(module_id, position);
create index on course_enrolments(participant_id);

-- ============ helper functions (security definer, so policies do not recurse) ============
create or replace function is_course_trainer(cid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from course_trainers where course_id = cid and trainer_id = auth.uid()) $$;
create or replace function course_of_module(mid uuid) returns uuid language sql stable security definer set search_path = public as $$
  select course_id from course_modules where id = mid $$;
create or replace function course_of_lesson(lid uuid) returns uuid language sql stable security definer set search_path = public as $$
  select m.course_id from course_lessons l join course_modules m on m.id = l.module_id where l.id = lid $$;
-- Participants see a course only while it is published and they are enrolled in it.
create or replace function participant_can_view_course(cid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from course_enrolments e join courses c on c.id = e.course_id
                 where e.course_id = cid and c.status = 'published' and e.participant_id = my_participant_id()) $$;
create or replace function can_view_course(cid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select is_staff() or app_role() = 'me_officer' or is_course_trainer(cid) or participant_can_view_course(cid) $$;
create or replace function can_edit_course(cid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select is_staff() or is_course_trainer(cid) $$;

-- ============ row-level security ============
alter table courses enable row level security;
alter table course_trainers enable row level security;
alter table course_modules enable row level security;
alter table course_lessons enable row level security;
alter table course_enrolments enable row level security;
alter table lesson_progress enable row level security;

create policy courses_read on courses for select to authenticated using (can_view_course(id) or created_by = auth.uid());
create policy courses_staff_write on courses for all to authenticated using (is_staff()) with check (is_staff());
-- Trainers may create courses (always as drafts, see guard) and edit the ones they are assigned to.
create policy courses_trainer_insert on courses for insert to authenticated with check (app_role() = 'trainer' and created_by = auth.uid());
create policy courses_trainer_update on courses for update to authenticated using (app_role() = 'trainer' and is_course_trainer(id)) with check (app_role() = 'trainer' and is_course_trainer(id));

create policy ctrainers_read on course_trainers for select to authenticated using (is_staff() or trainer_id = auth.uid() or app_role() = 'me_officer');
create policy ctrainers_write on course_trainers for all to authenticated using (is_staff()) with check (is_staff());

create policy cmodules_read on course_modules for select to authenticated using (can_view_course(course_id));
create policy cmodules_write on course_modules for all to authenticated using (can_edit_course(course_id)) with check (can_edit_course(course_id));
create policy clessons_read on course_lessons for select to authenticated using (can_view_course(course_of_module(module_id)));
create policy clessons_write on course_lessons for all to authenticated using (can_edit_course(course_of_module(module_id))) with check (can_edit_course(course_of_module(module_id)));

create policy cenrol_read on course_enrolments for select to authenticated using (is_staff() or app_role() = 'me_officer' or is_course_trainer(course_id) or participant_id = my_participant_id());
create policy cenrol_write on course_enrolments for all to authenticated using (is_staff()) with check (is_staff());

create policy lprog_read on lesson_progress for select to authenticated using (is_staff() or app_role() = 'me_officer' or is_course_trainer(course_of_lesson(lesson_id)) or participant_id = my_participant_id());
create policy lprog_self_insert on lesson_progress for insert to authenticated with check (participant_id = my_participant_id() and participant_can_view_course(course_of_lesson(lesson_id)));
create policy lprog_self_delete on lesson_progress for delete to authenticated using (participant_id = my_participant_id() and participant_can_view_course(course_of_lesson(lesson_id)));

-- ============ guards ============
create or replace function guard_course() returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if tg_op = 'INSERT' then
    new.created_by := coalesce(auth.uid(), new.created_by);
    new.status := 'draft';   -- every course starts as a draft; publishing is a separate step once it has lessons
  elsif app_role() = 'trainer' then
    if new.status is distinct from old.status then raise exception 'Only programme management can publish or archive a course'; end if;
    if new.programme_id is distinct from old.programme_id or new.cohort_id is distinct from old.cohort_id or new.track_id is distinct from old.track_id then
      raise exception 'Only programme management can move a course to another programme, track or cohort';
    end if;
  end if;
  if new.track_id is not null and not exists (select 1 from tracks where id = new.track_id and programme_id = new.programme_id) then raise exception 'The track belongs to a different programme'; end if;
  if new.cohort_id is not null and not exists (select 1 from cohorts where id = new.cohort_id and programme_id = new.programme_id) then raise exception 'The cohort belongs to a different programme'; end if;
  if new.status = 'published' and (tg_op = 'INSERT' or old.status <> 'published') and not exists (select 1 from course_modules m join course_lessons l on l.module_id = m.id where m.course_id = new.id) and tg_op = 'UPDATE' then
    raise exception 'Add at least one lesson before publishing';
  end if;
  return new;
end $$;
create trigger trg_guard_course before insert or update on courses for each row execute function guard_course();

-- A trainer who creates a course is assigned to it automatically.
create or replace function course_creator_assigned() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.created_by is not null and exists (select 1 from profiles where id = new.created_by and role = 'trainer' and status = 'active') then
    insert into course_trainers(course_id, trainer_id) values (new.id, new.created_by) on conflict do nothing;
  end if;
  return new;
end $$;
create trigger trg_course_creator_assigned after insert on courses for each row execute function course_creator_assigned();

create or replace function guard_course_trainer() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from profiles where id = new.trainer_id and role = 'trainer' and status = 'active') then raise exception 'Only an active trainer account can be assigned to a course'; end if;
  return new;
end $$;
create trigger trg_guard_course_trainer before insert on course_trainers for each row execute function guard_course_trainer();

create or replace function guard_course_enrolment() returns trigger language plpgsql security definer set search_path = public as $$
declare c courses; p participants; pu uuid;
begin
  select * into c from courses where id = new.course_id;
  if c.status = 'archived' then raise exception 'An archived course cannot take new enrolments'; end if;
  select * into p from participants where id = new.participant_id;
  if p.status = 'withdrawn' then raise exception 'A withdrawn participant cannot be enrolled'; end if;
  if c.cohort_id is not null and not exists (select 1 from cohort_enrolments where cohort_id = c.cohort_id and participant_id = new.participant_id) then
    raise exception 'This course is for one cohort and the participant is not enrolled in it';
  end if;
  if c.track_id is not null and not exists (select 1 from cohort_enrolments e join cohorts k on k.id = e.cohort_id where e.participant_id = new.participant_id and e.track_id = c.track_id and k.programme_id = c.programme_id) then
    raise exception 'This course is for one track and the participant has not chosen it';
  end if;
  new.enrolled_by := coalesce(auth.uid(), new.enrolled_by);
  select profile_id into pu from participants where id = new.participant_id;
  insert into notifications(user_id, kind, title, body) values (pu, 'course', 'You were enrolled in a course', c.title);
  return new;
end $$;
create trigger trg_guard_course_enrolment before insert on course_enrolments for each row execute function guard_course_enrolment();

-- Lesson files must live under the course's own folder, so storage rules can tell which course a file belongs to.
create or replace function guard_course_lesson() returns trigger language plpgsql security definer set search_path = public as $$
declare cid uuid;
begin
  cid := course_of_module(new.module_id);
  if new.storage_path is not null and new.storage_path not like cid::text || '/%' then raise exception 'Lesson files must be stored in the course folder'; end if;
  return new;
end $$;
create trigger trg_guard_course_lesson before insert or update on course_lessons for each row execute function guard_course_lesson();

-- Completed lessons count only for lessons in a course the participant is enrolled in (policy already checks); no double counting by design (primary key).
create trigger aud_courses after insert or update or delete on courses for each row execute function audit_row();
create trigger aud_course_trainers after insert or delete on course_trainers for each row execute function audit_row();
create trigger aud_course_enrolments after insert or delete on course_enrolments for each row execute function audit_row();

-- ============ progress ============
create view v_course_progress with (security_invoker = true) as
select e.course_id, e.participant_id,
  (select count(*) from course_lessons l join course_modules m on m.id = l.module_id where m.course_id = e.course_id)::int as lessons_total,
  (select count(*) from lesson_progress lp join course_lessons l on l.id = lp.lesson_id join course_modules m on m.id = l.module_id
     where m.course_id = e.course_id and lp.participant_id = e.participant_id)::int as lessons_done
from course_enrolments e;

-- ============ storage: private bucket, 50 MB, type allow-list ============
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('course-materials', 'course-materials', false, 52428800, array['application/pdf','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.ms-powerpoint','video/mp4','image/jpeg','image/png'])
on conflict (id) do nothing;

-- The first folder of every path is the course id: '<course_id>/<lesson file>'. Unreadable ids give no access.
create or replace function course_of_path(name text) returns uuid language plpgsql immutable as $$
begin return (storage.foldername(name))[1]::uuid; exception when others then return null; end $$;

create policy storage_course_read on storage.objects for select to authenticated
  using (bucket_id = 'course-materials' and course_of_path(name) is not null and can_view_course(course_of_path(name)));
create policy storage_course_write on storage.objects for insert to authenticated
  with check (bucket_id = 'course-materials' and course_of_path(name) is not null and can_edit_course(course_of_path(name)));
create policy storage_course_update on storage.objects for update to authenticated
  using (bucket_id = 'course-materials' and course_of_path(name) is not null and can_edit_course(course_of_path(name)));
create policy storage_course_delete on storage.objects for delete to authenticated
  using (bucket_id = 'course-materials' and course_of_path(name) is not null and can_edit_course(course_of_path(name)));

-- Email copies of notifications now include course enrolments.
create or replace function notification_to_email() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not email_automation_enabled() then return new; end if;
  if new.kind not in ('announcement', 'assignment', 'certificate', 'application', 'course') then return new; end if;
  if exists (select 1 from profiles where id = new.user_id and email_opt_out) then return new; end if;
  perform _enqueue_email(new.user_id, 'notification', jsonb_build_object('title', new.title, 'body', coalesce(new.body, '')), now(), 'event:' || new.kind, null);
  return new;
end $$;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000011', 'courses');
commit;

\echo '== migration 20260101000012 learner_import'
begin;
-- DIRA LEARN: record of bulk learner invitations. STATUS: written, NOT yet executed.
-- Imported learners are invited as APPLICANTS. They set a password, complete the application form and go through the normal
-- review; nobody becomes a participant by being imported. Only the import-learners Edge Function (service role) writes here.

create table import_batches (
  id uuid primary key default gen_random_uuid(),
  created_by uuid references profiles(id),
  file_name text,
  total int not null default 0,
  invited int not null default 0,
  already_registered int not null default 0,
  failed int not null default 0,
  created_at timestamptz not null default now()
);
create table import_rows (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references import_batches(id) on delete cascade,
  row_no int not null,
  email text not null,
  first_name text, last_name text,
  outcome text not null check (outcome in ('invited', 'already_registered', 'failed')),
  message text
);
create index on import_rows(batch_id);
alter table import_batches enable row level security;
alter table import_rows enable row level security;
-- The rows hold personal data (names and emails), so only programme management reads them.
create policy impbatch_read on import_batches for select to authenticated using (is_staff());
create policy improws_read on import_rows for select to authenticated using (is_staff());
revoke insert, update, delete on import_batches, import_rows from authenticated, anon;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000012', 'learner_import');
commit;

\echo '== migration 20260101000013 first_admin_setup'
begin;
-- First-time setup inside the app: the first super administrator is claimed on the /setup page, not with SQL.
-- The Edge Function `claim-first-admin` checks a secret setup code (SETUP_CODE) and then calls claim_first_admin().
-- NOT yet executed or tested.

-- Is there still no active super administrator? Signed-in users only (anonymous visitors cannot ask).
create or replace function first_admin_needed() returns boolean language sql stable security definer set search_path = public as $$
  select not exists (select 1 from profiles where role = 'super_admin' and status = 'active') $$;
revoke all on function first_admin_needed() from public, anon;
grant execute on function first_admin_needed() to authenticated, service_role;

-- Promote one applicant account to super administrator, only while there is no active super administrator.
-- An advisory lock makes two simultaneous claims safe: the second sees the first and gets false.
-- Only the service role (the Edge Function) can run this; browsers cannot.
create or replace function claim_first_admin(p_user uuid) returns boolean language plpgsql security definer set search_path = public as $$
declare changed int;
begin
  perform pg_advisory_xact_lock(hashtext('dira_claim_first_admin'));
  if exists (select 1 from profiles where role = 'super_admin' and status = 'active') then return false; end if;
  update profiles set role = 'super_admin', status = 'active' where id = p_user and role = 'applicant';
  get diagnostics changed = row_count;
  return changed = 1;
end $$;
revoke all on function claim_first_admin(uuid) from public, anon, authenticated;
grant execute on function claim_first_admin(uuid) to service_role;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000013', 'first_admin_setup');
commit;

\echo '== migration 20260101000014 applicant_approval'
begin;
-- DIRA LEARN: in-system applicant approval (Approve / Reject inside the administrator dashboard)
-- STATUS: written, NOT yet executed. Run `supabase db reset` then `supabase test db` on a LOCAL database first.
-- SAFE TO APPLY TO A LIVE DATABASE: additive only. It adds functions and two email templates and replaces three
-- existing functions. It does not change, delete or backfill any rows, and it never touches existing profiles
-- (including the Super Administrator account).
--
-- Design (reuses the existing tables: profiles, applications, application_events, participants, audit_logs,
-- notifications, email_templates, email_outbox):
--   * Pending  = submitted | under_review | shortlisted | waitlisted
--   * Approved = accepted      (applicant becomes a participant)
--   * Rejected = rejected      (applicant stays an applicant; no participant access)
--   * ONLY decide_application() can approve or reject. It runs on the server (security definer), checks the caller,
--     and does every step in ONE transaction: status, profile, participant record, history, audit log, notification, email.
--   * Who may decide: active super_admin or programme_director. Nobody can decide their own application.

-- ============ 1. who may decide ============
create or replace function can_decide_applications() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(app_role() in ('super_admin', 'programme_director'), false) $$;
revoke all on function can_decide_applications() from public, anon;
grant execute on function can_decide_applications() to authenticated;

-- ============ 2. profile guard: one narrow exception for the approval function ============
-- Unchanged rule: only a super administrator (or a trusted server session) may change role, status or organisation.
-- New, narrow exception: while decide_application() is running it may turn an ACTIVE APPLICANT into a participant
-- (and nothing else). The flag is transaction-local and cannot be set through the API.
create or replace function guard_profile_privileged() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if is_trusted_session() then return new; end if;
  if current_setting('dira.application_decision', true) = 'on'
     and old.role = 'applicant' and new.role = 'participant'
     and new.status is not distinct from old.status
     and new.organization_id is not distinct from old.organization_id then
    return new;
  end if;
  if (new.role is distinct from old.role or new.status is distinct from old.status or new.organization_id is distinct from old.organization_id)
     and not is_admin() then
    raise exception 'Only a super administrator can change role, status or organisation';
  end if;
  return new;
end $$;

-- ============ 3. email templates (editable by staff in the Emails page) ============
insert into email_templates(key, name, subject, body, is_system) values
 ('application_approved', 'Application approved', 'Your DIRA LEARN application was approved',
  E'Hello {{first_name}},\n\nGood news: your application to the DIRA Foundation programme has been approved. You now have participant access to DIRA LEARN.\n\nSign in to see your dashboard. Details of your cohort and schedule will follow.\n\nWelcome aboard,\nDIRA Foundation', true),
 ('application_rejected', 'Application not successful', 'An update on your DIRA LEARN application',
  E'Hello {{first_name}},\n\nThank you for applying to the DIRA Foundation programme and for the time you put into your application. After careful review, we are not able to offer you a place in this cohort.\n\nThis is not a judgement of your potential. You are welcome to apply again for a future cohort. If you have questions, contact us through our website.\n\nWith best wishes,\nDIRA Foundation', true)
on conflict (key) do nothing;

-- ============ 4. the decision function ============
create or replace function decide_application(p_app uuid, p_decision text, p_reason text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  actor uuid := auth.uid();
  a applications;
  approve boolean;
  reason text := nullif(btrim(p_reason), '');
  f jsonb;
  dob date;
  pid uuid;
  new_status application_status;
  vars jsonb;
begin
  if actor is null or not can_decide_applications() then
    raise exception 'Only a super administrator or programme director can approve or reject applications';
  end if;
  if p_decision is null or p_decision not in ('approve', 'reject') then raise exception 'The decision must be approve or reject'; end if;
  approve := p_decision = 'approve';
  if reason is not null and length(reason) > 1000 then raise exception 'The reason is too long (1000 characters at most)'; end if;

  select * into a from applications where id = p_app for update;          -- row lock: two admins cannot decide at once
  if not found then raise exception 'Application not found'; end if;
  if a.applicant_id = actor then raise exception 'You cannot decide your own application'; end if;
  if a.status not in ('submitted', 'under_review', 'shortlisted', 'waitlisted') then
    raise exception 'Only pending applications can be approved or rejected (this one is %)', a.status;
  end if;

  f := coalesce(a.form_data, '{}'::jsonb);
  new_status := case when approve then 'accepted'::application_status else 'rejected'::application_status end;
  perform set_config('dira.application_transition', 'on', true);          -- lets the status trigger accept this change
  perform set_config('dira.application_decision', 'on', true);            -- lets the profile guard accept applicant -> participant

  if approve then
    if not exists (select 1 from profiles where id = a.applicant_id and role = 'applicant' and status = 'active') then
      raise exception 'This account is not an active applicant account, so it cannot be approved as a participant';
    end if;
    select id into pid from participants where application_id = a.id or profile_id = a.applicant_id limit 1;
    if pid is null then
      begin dob := (f ->> 'dateOfBirth')::date; exception when others then dob := null; end;
      insert into participants(profile_id, application_id, participant_no, date_of_birth)
        values (a.applicant_id, a.id, next_participant_no(), dob) returning id into pid;
    end if;
    insert into portfolios(participant_id) values (pid) on conflict do nothing;
    update profiles set role = 'participant',
      first_name = coalesce(nullif(btrim(f ->> 'firstName'), ''), first_name),
      last_name  = coalesce(nullif(btrim(f ->> 'lastName'), ''), last_name),
      phone      = coalesce(nullif(btrim(f ->> 'phone'), ''), phone)
    where id = a.applicant_id;
  end if;

  update applications set status = new_status where id = a.id;
  insert into application_events(application_id, from_status, to_status, note, actor_id)
    values (a.id, a.status, new_status, reason, actor);
  insert into audit_logs(actor_id, table_name, row_id, action, old_data, new_data)
    values (actor, 'applications', a.id::text, case when approve then 'application_approved' else 'application_rejected' end,
            jsonb_build_object('status', a.status),
            jsonb_build_object('status', new_status, 'decision', p_decision, 'reason', reason, 'decided_by', actor,
                               'decided_at', now(), 'applicant_id', a.applicant_id, 'participant_id', pid));

  -- In-app notification. Kind 'application_decision' is deliberately NOT one of the kinds that the notification-to-email
  -- trigger copies, so the applicant gets exactly one email (queued below), not two.
  insert into notifications(user_id, kind, title, body)
    values (a.applicant_id, 'application_decision',
            case when approve then 'Your application was approved' else 'An update on your application' end,
            case when approve then 'Welcome to DIRA LEARN. Your cohort details will follow.' else 'Open My application to read the update.' end);

  -- Decision emails are transactional: sent even when marketing opt-out is on or event automation is off.
  -- The internal reason is never put in the email. Sending itself is done by the existing send-emails function.
  vars := jsonb_build_object('first_name', coalesce(nullif(btrim(f ->> 'firstName'), ''), 'there'));
  perform _enqueue_email(a.applicant_id, case when approve then 'application_approved' else 'application_rejected' end,
                         vars, now(), 'event:application_decision', actor);

  return jsonb_build_object('status', new_status, 'participant_id', pid);
end $$;
revoke all on function decide_application(uuid, text, text) from public, anon;
grant execute on function decide_application(uuid, text, text) to authenticated;

-- ============ 5. staff can see applicant emails (auth.users is otherwise unreadable) ============
create or replace function application_emails() returns table(application_id uuid, email text)
language plpgsql stable security definer set search_path = public, auth as $$
begin
  if not is_staff() then raise exception 'Only programme staff can view applicant emails'; end if;
  return query select a.id, au.email::text from applications a join auth.users au on au.id = a.applicant_id where a.status <> 'draft';
end $$;
revoke all on function application_emails() from public, anon;
grant execute on function application_emails() to authenticated;

-- ============ 6. the old status route can no longer approve or reject ============
-- Same function as before, plus one rule: approving goes through decide_application(); rejecting needs approval rights.
create or replace function transition_application(p_app uuid, p_to application_status, p_note text default null)
returns void language plpgsql security definer set search_path = public as $$
declare cur application_status;
begin
  if not is_staff() then raise exception 'Only programme staff can review applications'; end if;
  select status into cur from applications where id = p_app for update;
  if cur is null then raise exception 'Application not found'; end if;
  if not application_transition_allowed(cur, p_to) then
    raise exception 'An application cannot move from % to %', cur, p_to;
  end if;
  if (p_to = 'rejected' or cur = 'rejected') and coalesce(btrim(p_note), '') = '' then
    raise exception 'A note is required when rejecting or reconsidering an application';
  end if;
  if p_to in ('accepted', 'rejected') then
    raise exception 'Applications are approved or rejected with the Approve and Reject actions, by a super administrator or programme director';
  end if;
  perform set_config('dira.application_transition', 'on', true);
  update applications set status = p_to where id = p_app;
  insert into application_events(application_id, from_status, to_status, note, actor_id)
    values (p_app, cur, p_to, nullif(btrim(p_note), ''), auth.uid());
end $$;

-- ============ 7. avoid a second, neutral notification when the decision function already wrote one ============
create or replace function notify_application_update() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if current_setting('dira.application_decision', true) = 'on' then return new; end if;
  insert into notifications(user_id, kind, title, body) values (new.applicant_id, 'application', 'There is an update on your application', 'Open My application to read it.');
  return new;
end $$;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000014', 'applicant_approval');
commit;

\echo '== migration 20260101000015 founder_roles'
begin;
-- DIRA LEARN: add the Founder and Co-Founder roles.
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`.
-- This file is separate on purpose: a new enum value cannot be used in the same transaction that adds it, so the
-- approval-centre migration (20260101000016) that uses these roles must be a later file.
-- ADDITIVE ONLY: existing roles, accounts and passwords are untouched. Founder and Co-Founder are NOT added to is_staff() or
-- is_admin(): on their own they get no applications, users, settings or safeguarding access. They are given only what the
-- Curriculum Approval Centre needs. A super administrator assigns them in Users.
-- ROLLBACK NOTE: PostgreSQL cannot remove an enum value. Unused values are harmless; to "undo", simply do not assign the roles.
alter type role_code add value if not exists 'founder';
alter type role_code add value if not exists 'co_founder';
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000015', 'founder_roles');
commit;

\echo '== migration 20260101000016 curriculum_approval_centre'
begin;
-- DIRA LEARN: Curriculum Approval Centre (topic-level approval by Founder, Co-Founder and Super Administrator)
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`.
-- ADDITIVE ONLY: new tables, functions and a view. No existing curriculum row, policy or account is changed or deleted.
-- Rollback: supabase/rollback/20260101000016_curriculum_approval_centre_down.sql
--
-- How it fits the existing curriculum:
--   * curriculum_sessions.topics (text[]) already holds "proposed extra topics" that the app shows as "awaiting approval".
--     Those are NOT edited. Each proposed topic now also has a row in curriculum_topic_proposals with a status.
--   * Official teaching topics = APPROVED proposals. v_session_topics gives the app approved_topics (official) and
--     awaiting_topics (still pending; rejected ones are hidden). Pending and rejected topics never count as official content.
--   * The existing session-level approval (is_approved, set_curriculum_approval: super admin + programme director) is
--     unchanged. Approving a topic does not edit curriculum_sessions, so it cannot reset a session's approval.

-- ============ 1. reference rows and the approval permission ============
insert into roles(code, label) values ('founder', 'Founder'), ('co_founder', 'Co-Founder') on conflict do nothing;

create or replace function can_approve_curriculum() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(app_role() in ('founder', 'co_founder', 'super_admin'), false) $$;
revoke all on function can_approve_curriculum() from public, anon;
grant execute on function can_approve_curriculum() to authenticated;

-- ============ 2. tables ============
create type topic_status as enum ('pending', 'approved', 'rejected');

create table curriculum_topic_proposals (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references curriculum_sessions(id) on delete restrict,
  track_id uuid references tracks(id),                       -- always the session's track (set by trigger); null for shared core sessions
  title text not null check (length(btrim(title)) between 2 and 200),
  description text check (description is null or length(description) <= 2000),
  status topic_status not null default 'pending',
  submitted_by uuid references profiles(id),                 -- null = part of the initial proposal list
  submitted_at timestamptz not null default now(),
  reviewed_by uuid references profiles(id),
  reviewed_at timestamptz,
  reviewer_comment text check (reviewer_comment is null or length(reviewer_comment) <= 1000),
  created_at timestamptz not null default now(),
  constraint topic_review_fields check (
    (status = 'pending' and reviewed_by is null and reviewed_at is null)
    or (status in ('approved', 'rejected') and reviewed_by is not null and reviewed_at is not null)),
  constraint topic_reject_needs_reason check (status <> 'rejected' or length(btrim(coalesce(reviewer_comment, ''))) > 0)
);
-- one proposal per title per session (case-insensitive); the same title in a different session or track is a different proposal
create unique index uq_topic_per_session on curriculum_topic_proposals(session_id, lower(btrim(title)));
create index on curriculum_topic_proposals(status, submitted_at);
create index on curriculum_topic_proposals(track_id, session_id);

create table curriculum_topic_events (                       -- the approval history; never edited or deleted
  id bigint generated always as identity primary key,
  proposal_id uuid not null references curriculum_topic_proposals(id) on delete restrict,
  from_status topic_status,
  to_status topic_status not null,
  actor_id uuid references profiles(id),
  comment text,
  created_at timestamptz not null default now()
);
create index on curriculum_topic_events(proposal_id, created_at);

-- ============ 3. guards ============
create or replace function set_topic_track() returns trigger language plpgsql as $$
begin new.track_id := (select track_id from curriculum_sessions where id = new.session_id); return new; end $$;
create trigger trg_topic_track before insert or update of session_id on curriculum_topic_proposals for each row execute function set_topic_track();

-- Status, reviewer and comment can only change through review_curriculum_topic() (or a trusted maintenance session).
create or replace function guard_topic_update() returns trigger language plpgsql as $$
begin
  if (new.status is distinct from old.status or new.reviewed_by is distinct from old.reviewed_by
      or new.reviewed_at is distinct from old.reviewed_at or new.reviewer_comment is distinct from old.reviewer_comment)
     and not (current_setting('dira.topic_review', true) = 'on' or is_trusted_session()) then
    raise exception 'A topic can only be approved or rejected with the review action';
  end if;
  return new;
end $$;
create trigger trg_guard_topic_update before update on curriculum_topic_proposals for each row execute function guard_topic_update();

create or replace function forbid_topic_delete() returns trigger language plpgsql as $$
begin raise exception 'Topic proposals are never deleted. Reject a topic instead'; end $$;
create trigger trg_forbid_topic_delete before delete on curriculum_topic_proposals for each row execute function forbid_topic_delete();

create or replace function forbid_topic_event_change() returns trigger language plpgsql as $$
begin raise exception 'The approval history cannot be changed'; end $$;
create trigger trg_topic_event_immutable before update or delete on curriculum_topic_events for each row execute function forbid_topic_event_change();

-- ============ 4. row level security: read only; every change goes through a function ============
alter table curriculum_topic_proposals enable row level security;
alter table curriculum_topic_events enable row level security;
revoke all on table curriculum_topic_proposals, curriculum_topic_events from anon, authenticated;
grant select on table curriculum_topic_proposals, curriculum_topic_events to authenticated;
-- approvers see everything; everyone else sees only APPROVED topics. No insert, update or delete policy exists for anyone.
create policy topic_read on curriculum_topic_proposals for select to authenticated using (can_approve_curriculum() or status = 'approved');
create policy topic_events_read on curriculum_topic_events for select to authenticated using (can_approve_curriculum());

-- ============ 5. the decision function ============
create or replace function review_curriculum_topic(p_id uuid, p_decision text, p_comment text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  actor uuid := auth.uid();
  p curriculum_topic_proposals;
  c text := nullif(btrim(p_comment), '');
  new_state topic_status;
begin
  if actor is null or not can_approve_curriculum() then
    raise exception 'Only the Founder, Co-Founder or a Super Administrator can approve or reject curriculum topics';
  end if;
  if p_decision is null or p_decision not in ('approve', 'reject', 'reopen') then raise exception 'The decision must be approve, reject or reopen'; end if;
  if c is not null and length(c) > 1000 then raise exception 'The comment is too long (1000 characters at most)'; end if;

  select * into p from curriculum_topic_proposals where id = p_id for update;
  if not found then raise exception 'Topic not found'; end if;

  if p_decision = 'reopen' then
    if p.status <> 'rejected' then raise exception 'Only a rejected topic can be reconsidered (this one is %)', p.status; end if;
    new_state := 'pending';
  else
    if p.status <> 'pending' then raise exception 'Only a pending topic can be approved or rejected (this one is %)', p.status; end if;
    if p_decision = 'reject' and c is null then raise exception 'Give a reason when rejecting a topic'; end if;
    new_state := case when p_decision = 'approve' then 'approved'::topic_status else 'rejected'::topic_status end;
  end if;

  perform set_config('dira.topic_review', 'on', true);
  update curriculum_topic_proposals set status = new_state,
    reviewed_by = case when new_state = 'pending' then null else actor end,
    reviewed_at = case when new_state = 'pending' then null else now() end,
    reviewer_comment = case when new_state = 'pending' then null else c end
  where id = p.id;
  insert into curriculum_topic_events(proposal_id, from_status, to_status, actor_id, comment) values (p.id, p.status, new_state, actor, c);
  insert into audit_logs(actor_id, table_name, row_id, action, old_data, new_data)
    values (actor, 'curriculum_topic_proposals', p.id::text, 'curriculum_topic_' || case p_decision when 'approve' then 'approved' when 'reject' then 'rejected' else 'reopened' end,
            jsonb_build_object('status', p.status), jsonb_build_object('status', new_state, 'title', p.title, 'session_id', p.session_id, 'comment', c, 'decided_at', now()));
  return jsonb_build_object('status', new_state);
end $$;
revoke all on function review_curriculum_topic(uuid, text, text) from public, anon;
grant execute on function review_curriculum_topic(uuid, text, text) to authenticated;

-- ============ 6. read functions for the Approval Centre (approvers only; they include reviewer names, which a founder could not read from profiles) ============
create or replace function curriculum_proposals_list() returns table(
  id uuid, track_id uuid, track_name text, track_position int, session_id uuid, session_no int, week_no int, session_title text,
  session_description text, session_objectives text[], title text, description text, status topic_status, submitted_at timestamptz,
  submitted_by_name text, reviewed_at timestamptz, reviewed_by_name text, reviewer_comment text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not can_approve_curriculum() then raise exception 'Only the Founder, Co-Founder or a Super Administrator can open the Curriculum Approval Centre'; end if;
  return query
    select p.id, cs.track_id, t.name, t.position, cs.id, cs.session_no, cs.week_no, cs.title, cs.description, cs.objectives,
           p.title, p.description, p.status, p.submitted_at,
           nullif(btrim(coalesce(sb.first_name, '') || ' ' || coalesce(sb.last_name, '')), ''), p.reviewed_at,
           nullif(btrim(coalesce(rb.first_name, '') || ' ' || coalesce(rb.last_name, '')), ''), p.reviewer_comment
    from curriculum_topic_proposals p
    join curriculum_sessions cs on cs.id = p.session_id
    left join tracks t on t.id = cs.track_id
    left join profiles sb on sb.id = p.submitted_by
    left join profiles rb on rb.id = p.reviewed_by
    order by t.position nulls last, cs.session_no, p.title;
end $$;
revoke all on function curriculum_proposals_list() from public, anon;
grant execute on function curriculum_proposals_list() to authenticated;

create or replace function curriculum_topic_history(p_id uuid) returns table(
  id bigint, from_status topic_status, to_status topic_status, actor_name text, comment text, created_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  if not can_approve_curriculum() then raise exception 'Only the Founder, Co-Founder or a Super Administrator can view the approval history'; end if;
  return query
    select e.id, e.from_status, e.to_status, nullif(btrim(coalesce(a.first_name, '') || ' ' || coalesce(a.last_name, '')), ''), e.comment, e.created_at
    from curriculum_topic_events e left join profiles a on a.id = e.actor_id
    where e.proposal_id = p_id order by e.created_at desc, e.id desc;
end $$;
revoke all on function curriculum_topic_history(uuid) from public, anon;
grant execute on function curriculum_topic_history(uuid) to authenticated;

-- ============ 7. what the rest of the app shows ============
-- approved_topics = official teaching topics. awaiting_topics = the session's own proposed list minus anything already decided.
-- Rejected topics appear in neither. Runs with the owner's rights on purpose (it exposes only approved titles and the proposed
-- list that curriculum_sessions already shows every signed-in user).
create view v_session_topics as
  select cs.id as session_id,
    coalesce((select array_agg(p.title order by p.reviewed_at, p.title) from curriculum_topic_proposals p
              where p.session_id = cs.id and p.status = 'approved'), '{}'::text[]) as approved_topics,
    coalesce((select array_agg(u.topic order by u.n) from unnest(cs.topics) with ordinality as u(topic, n)
              where not exists (select 1 from curriculum_topic_proposals p
                                where p.session_id = cs.id and lower(btrim(p.title)) = lower(btrim(u.topic)) and p.status in ('approved', 'rejected'))), '{}'::text[]) as awaiting_topics
  from curriculum_sessions cs;
revoke all on v_session_topics from anon;
grant select on v_session_topics to authenticated;

-- ============ 8. the initial approval queue (idempotent; never approves anything, never duplicates) ============
-- Matches by track code + session number in the current programme. If a session is not found, nothing is invented for it.
create or replace function seed_initial_topic_proposals() returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
