\echo '== migration 20260101000017 executive_roles'
begin;
-- DIRA LEARN: Founder and Co-Founder receive administrative permissions equivalent to the Super Administrator.
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`. Never run first on production.
--
-- Board decision (master instruction, Phase 8): super_admin, founder and co_founder have equivalent ADMINISTRATIVE access.
-- This replaces the earlier rule (migration 15/16) that Founder and Co-Founder were not general staff.
--
-- DESIGN
--   * is_executive()  NEW. active super_admin, founder or co_founder. Used for administrative areas.
--   * is_staff()      now also includes founder and co_founder (they gain every area staff can reach).
--   * is_admin()      UNCHANGED (super_admin only). It still guards ROLE / STATUS / ORGANISATION changes, the profiles
--                     "for all" policy and the last-administrator protection, so a founder cannot promote anyone to
--                     super_admin or create another founder. WHO MAY ASSIGN ROLES is a management decision, see
--                     docs/EXECUTIVE_ROLES.md. The first-super-admin bootstrap (claim_first_admin) is NOT touched.
--   * Functions that hard-code ('super_admin','programme_director') are rewritten in place from their stored source, and the
--     migration aborts if a rewrite changes nothing, so a silent no-op cannot be mistaken for success.
-- ADDITIVE for existing users: no account, role or password changes.

-- ============ 1. helpers ============
create or replace function is_executive() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(app_role() in ('super_admin', 'founder', 'co_founder'), false) $$;
revoke all on function is_executive() from public, anon;
grant execute on function is_executive() to authenticated;

create or replace function is_staff() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(app_role() in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator'), false) $$;

-- ============ 2. functions with hard-coded role lists (rewritten from stored source, abort if nothing changed) ============
do $$
declare
  r record;
  def text;
  newdef text;
begin
  for r in
    select * from (values
      ('guard_curriculum_session()',                     'app_role() not in (''super_admin'', ''programme_director'')', 'app_role() not in (''super_admin'', ''founder'', ''co_founder'', ''programme_director'')'),
      ('set_curriculum_approval(uuid,boolean)',          'app_role() not in (''super_admin'', ''programme_director'')', 'app_role() not in (''super_admin'', ''founder'', ''co_founder'', ''programme_director'')'),
      ('issue_certificate(uuid,uuid)',                   'app_role() not in (''super_admin'', ''programme_director'')', 'app_role() not in (''super_admin'', ''founder'', ''co_founder'', ''programme_director'')'),
      ('revoke_certificate(uuid,text)',                  'app_role() not in (''super_admin'', ''programme_director'')', 'app_role() not in (''super_admin'', ''founder'', ''co_founder'', ''programme_director'')'),
      ('can_decide_applications()',                      'app_role() in (''super_admin'', ''programme_director'')',     'app_role() in (''super_admin'', ''founder'', ''co_founder'', ''programme_director'')'),
      ('admin_list_users()',                             'where is_admin()',                                           'where is_executive()'),
      ('enqueue_bulk_email(text,text,uuid,timestamptz)', 'pr.role in (''super_admin'', ''programme_director''',          'pr.role in (''super_admin'', ''founder'', ''co_founder'', ''programme_director''')
    ) as t(sig, old_txt, new_txt)
  loop
    def := pg_get_functiondef(('public.' || r.sig)::regprocedure);
    newdef := replace(def, r.old_txt, r.new_txt);
    if newdef = def then
      raise exception 'Migration 17: expected text not found in function %, nothing was changed', r.sig;
    end if;
    execute newdef;
  end loop;
end $$;

-- ============ 3. policies: administrative areas move from is_admin() to is_executive() ============
-- Reference and curriculum tables (editable by executives and the coordinator; readable by everyone signed in, unchanged).
do $$ declare t text; begin
  foreach t in array array['organizations','roles','permissions','role_permissions','programmes','tracks','curriculum_sessions','assessment_definitions','competencies','competency_links','me_indicators']
  loop
    execute format('drop policy if exists %I on %I', t || '_write', t);
    execute format('create policy %I on %I for all to authenticated using (is_executive() or app_role()=''programme_coordinator'') with check (is_executive() or app_role()=''programme_coordinator'')', t || '_write', t);
  end loop;
end $$;

drop policy if exists graduation_rules_write on graduation_rules;
create policy graduation_rules_write on graduation_rules for all to authenticated using (is_executive()) with check (is_executive());

drop policy if exists cert_write on certificates;
create policy cert_write on certificates for all to authenticated
  using (is_executive() or app_role()='programme_director') with check (is_executive() or app_role()='programme_director');

drop policy if exists mer_write on me_records;
create policy mer_write on me_records for all to authenticated
  using (app_role()='me_officer' or is_executive()) with check (app_role()='me_officer' or is_executive());

drop policy if exists set_write on system_settings;
create policy set_write on system_settings for all to authenticated using (is_executive()) with check (is_executive());

drop policy if exists audit_admin on audit_logs;
create policy audit_admin on audit_logs for select to authenticated using (is_executive());

drop policy if exists safe_admin_read on safeguarding_records;
drop policy if exists safe_admin_insert on safeguarding_records;
drop policy if exists safe_admin_update on safeguarding_records;
create policy safe_admin_read on safeguarding_records for select to authenticated using (is_executive());
create policy safe_admin_insert on safeguarding_records for insert to authenticated with check (is_executive());
create policy safe_admin_update on safeguarding_records for update to authenticated using (is_executive()) with check (is_executive());

-- Executives can READ every profile (needed for the Users page). Writing role, status or organisation still requires
-- is_admin() (super_admin only) through guard_profile_privileged and the profiles_admin_all policy, both unchanged.
drop policy if exists profiles_exec_read on profiles;
create policy profiles_exec_read on profiles for select to authenticated using (is_executive());
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000017', 'executive_roles');
commit;

\echo '== migration 20260101000018 cohort_access_windows'
begin;
-- DIRA LEARN: cohort intakes and learning-access windows (master instruction, Phase 5).
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`. Never run first on production.
--
-- WHAT IT ADDS
--   * cohorts: intake label, season, recruitment period, learning-portal access opening and closing times.
--     (Programme start and end dates already exist as cohorts.start_date / end_date and are unchanged.)
--   * learner_access: a per-learner, per-cohort override (own opening/closing time, or suspension). Extending one learner never
--     changes the cohort and never touches another learner.
--   * learner_access_events: append-only access history.
--   * learner_access_state(): ONE function that decides pending / scheduled / active / expired / suspended from the database clock.
--   * RESTRICTIVE row level security policies: a participant whose learning access is not 'active' cannot read or write learning
--     resources, assignments, submissions, assessment results, course content or lesson progress, nor the matching storage files.
--     Restrictive policies can only narrow what existing policies allow; they never grant anything, so no other cohort's data is exposed.
-- ACCOUNT STATUS vs LEARNING ACCESS: profiles.status (active / pending / deactivated) is unchanged and separate. A learner can have an
--   active account and 'scheduled' learning access. Staff, trainers, mentors and M&E are never affected by access windows.
-- SAFE FOR EXISTING DATA: existing cohorts are back-filled so that nobody loses access they have today (opens at the earlier of the
--   cohort start date and its creation time, no closing time). Cohorts created later start with NO opening time, which means
--   'pending' (no access) until an administrator sets one. Administrators should add closing times to existing cohorts.

-- ============ 1. cohort columns ============
alter table cohorts
  add column if not exists intake_label text check (intake_label is null or length(btrim(intake_label)) between 1 and 80),
  add column if not exists season text check (season is null or length(btrim(season)) between 1 and 80),
  add column if not exists recruitment_opens_on date,
  add column if not exists recruitment_closes_on date,
  add column if not exists access_opens_at timestamptz,
  add column if not exists access_closes_at timestamptz;

alter table cohorts add constraint cohorts_recruitment_order check (recruitment_closes_on is null or recruitment_opens_on is null or recruitment_closes_on >= recruitment_opens_on);
alter table cohorts add constraint cohorts_access_order check (access_closes_at is null or access_opens_at is null or access_closes_at > access_opens_at);

update cohorts set access_opens_at = least(start_date::timestamptz, created_at) where access_opens_at is null;

create index if not exists idx_cohorts_recruitment on cohorts (recruitment_opens_on);
create index if not exists idx_cohorts_access on cohorts (access_opens_at, access_closes_at);

-- ============ 2. per-learner overrides and history ============
create type learner_access_status as enum ('pending', 'scheduled', 'active', 'expired', 'suspended');

create table learner_access (
  participant_id uuid not null references participants(id) on delete cascade,
  cohort_id uuid not null references cohorts(id) on delete cascade,
  opens_at_override timestamptz,
  closes_at_override timestamptz,
  suspended boolean not null default false,
  updated_by uuid references profiles(id),
  updated_at timestamptz not null default now(),
  primary key (participant_id, cohort_id),
  constraint learner_access_order check (closes_at_override is null or opens_at_override is null or closes_at_override > opens_at_override)
);

create table learner_access_events (
  id uuid primary key default gen_random_uuid(),
  participant_id uuid not null references participants(id) on delete cascade,
  cohort_id uuid not null references cohorts(id) on delete cascade,
  action text not null check (action in ('override_set', 'override_cleared', 'suspended', 'reinstated')),
  opens_at timestamptz,
  closes_at timestamptz,
  reason text not null check (length(btrim(reason)) >= 5),
  actor uuid references profiles(id),
  created_at timestamptz not null default now()
);
create index idx_learner_access_events_p on learner_access_events (participant_id, created_at desc);
create index idx_learner_access_events_c on learner_access_events (cohort_id, created_at desc);

create or replace function block_access_event_change() returns trigger language plpgsql as $$
begin raise exception 'Access history cannot be edited or deleted'; end $$;
create trigger trg_access_events_append_only before update or delete on learner_access_events for each row execute function block_access_event_change();

create trigger aud_learner_access after insert or update or delete on learner_access for each row execute function audit_row();

alter table learner_access enable row level security;
alter table learner_access_events enable row level security;
-- Read: staff only. No insert/update/delete policy for anyone: all changes go through the functions below.
create policy learner_access_staff_read on learner_access for select to authenticated using (is_staff());
create policy learner_access_events_staff_read on learner_access_events for select to authenticated using (is_staff());

-- ============ 3. the access decision (database clock only) ============
-- Visible only for yourself, for staff, or for a trainer of that learner's cohort. Anyone else gets NULL.
create or replace function learner_access_state(p_participant uuid, p_cohort uuid) returns learner_access_status
language plpgsql stable security definer set search_path = public as $$
declare
  c cohorts; a learner_access; opens timestamptz; closes timestamptz;
begin
  if not (is_staff() or p_participant = my_participant_id() or trainer_can_see_participant(p_participant)) then return null; end if;
  select * into c from cohorts where id = p_cohort;
  if not found then return null; end if;
  if not exists (select 1 from cohort_enrolments where participant_id = p_participant and cohort_id = p_cohort) then return 'pending'; end if;
  select * into a from learner_access where participant_id = p_participant and cohort_id = p_cohort;
  if found and a.suspended then return 'suspended'; end if;
  opens := coalesce(a.opens_at_override, c.access_opens_at);
  closes := coalesce(a.closes_at_override, c.access_closes_at);
  if opens is null then return 'pending'; end if;
  if now() < opens then return 'scheduled'; end if;
  if closes is not null and now() >= closes then return 'expired'; end if;
  return 'active';
end $$;
revoke all on function learner_access_state(uuid, uuid) from public, anon;
grant execute on function learner_access_state(uuid, uuid) to authenticated;

-- True for every role except participant. A participant needs at least one enrolment whose access is 'active' right now.
create or replace function participant_access_active() returns boolean language sql stable security definer set search_path = public as $$
  select case when app_role() = 'participant' then exists (
    select 1 from cohort_enrolments e join participants p on p.id = e.participant_id
    where p.profile_id = auth.uid() and learner_access_state(e.participant_id, e.cohort_id) = 'active')
  else true end $$;
revoke all on function participant_access_active() from public, anon;
grant execute on function participant_access_active() to authenticated;

-- What the learner sees about their own access (no other learner, no other cohort).
create or replace function my_learning_access()
returns table(cohort_id uuid, cohort_name text, status learner_access_status, opens_at timestamptz, closes_at timestamptz)
language sql stable security definer set search_path = public as $$
  select e.cohort_id, c.name, learner_access_state(e.participant_id, e.cohort_id),
         coalesce(a.opens_at_override, c.access_opens_at), coalesce(a.closes_at_override, c.access_closes_at)
  from cohort_enrolments e
  join participants p on p.id = e.participant_id and p.profile_id = auth.uid()
  join cohorts c on c.id = e.cohort_id
  left join learner_access a on a.participant_id = e.participant_id and a.cohort_id = e.cohort_id $$;
revoke all on function my_learning_access() from public, anon;
grant execute on function my_learning_access() to authenticated;

-- ============ 4. staff actions (all recorded in the history) ============
create or replace function set_learner_access_override(p_participant uuid, p_cohort uuid, p_opens_at timestamptz, p_closes_at timestamptz, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not is_staff() then raise exception 'Only programme staff can change learner access'; end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then raise exception 'A written reason is required'; end if;
  if not exists (select 1 from cohort_enrolments where participant_id = p_participant and cohort_id = p_cohort) then
    raise exception 'The learner is not enrolled in this cohort';
  end if;
  insert into learner_access(participant_id, cohort_id, opens_at_override, closes_at_override, updated_by)
    values (p_participant, p_cohort, p_opens_at, p_closes_at, auth.uid())
  on conflict (participant_id, cohort_id) do update
    set opens_at_override = excluded.opens_at_override, closes_at_override = excluded.closes_at_override, updated_by = auth.uid(), updated_at = now();
  insert into learner_access_events(participant_id, cohort_id, action, opens_at, closes_at, reason, actor)
    values (p_participant, p_cohort, case when p_opens_at is null and p_closes_at is null then 'override_cleared' else 'override_set' end, p_opens_at, p_closes_at, btrim(p_reason), auth.uid());
end $$;
revoke all on function set_learner_access_override(uuid, uuid, timestamptz, timestamptz, text) from public, anon;
grant execute on function set_learner_access_override(uuid, uuid, timestamptz, timestamptz, text) to authenticated;

create or replace function set_learner_suspension(p_participant uuid, p_cohort uuid, p_suspended boolean, p_reason text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not is_staff() then raise exception 'Only programme staff can change learner access'; end if;
  if p_reason is null or length(btrim(p_reason)) < 5 then raise exception 'A written reason is required'; end if;
  if not exists (select 1 from cohort_enrolments where participant_id = p_participant and cohort_id = p_cohort) then
    raise exception 'The learner is not enrolled in this cohort';
  end if;
  insert into learner_access(participant_id, cohort_id, suspended, updated_by)
    values (p_participant, p_cohort, p_suspended, auth.uid())
  on conflict (participant_id, cohort_id) do update set suspended = excluded.suspended, updated_by = auth.uid(), updated_at = now();
  insert into learner_access_events(participant_id, cohort_id, action, reason, actor)
    values (p_participant, p_cohort, case when p_suspended then 'suspended' else 'reinstated' end, btrim(p_reason), auth.uid());
end $$;
revoke all on function set_learner_suspension(uuid, uuid, boolean, text) from public, anon;
grant execute on function set_learner_suspension(uuid, uuid, boolean, text) to authenticated;

-- Staff overview of one cohort: every enrolled learner with status and effective window.
create or replace function cohort_access_roster(p_cohort uuid)
returns table(participant_id uuid, participant_no text, learner_name text, status learner_access_status, opens_at timestamptz, closes_at timestamptz, has_override boolean)
language sql stable security definer set search_path = public as $$
  select p.id, p.participant_no, btrim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')),
         learner_access_state(p.id, e.cohort_id),
         coalesce(a.opens_at_override, c.access_opens_at), coalesce(a.closes_at_override, c.access_closes_at),
         (a.opens_at_override is not null or a.closes_at_override is not null)
  from cohort_enrolments e
  join cohorts c on c.id = e.cohort_id
  join participants p on p.id = e.participant_id
  join profiles pr on pr.id = p.profile_id
  left join learner_access a on a.participant_id = p.id and a.cohort_id = e.cohort_id
  where e.cohort_id = p_cohort and is_staff()
  order by pr.last_name, pr.first_name $$;
revoke all on function cohort_access_roster(uuid) from public, anon;
grant execute on function cohort_access_roster(uuid) to authenticated;

create or replace function learner_access_history(p_participant uuid)
returns table(created_at timestamptz, cohort_name text, action text, opens_at timestamptz, closes_at timestamptz, reason text, actor_name text)
language sql stable security definer set search_path = public as $$
  select ev.created_at, c.name, ev.action, ev.opens_at, ev.closes_at, ev.reason, btrim(coalesce(ap.first_name, '') || ' ' || coalesce(ap.last_name, ''))
  from learner_access_events ev join cohorts c on c.id = ev.cohort_id left join profiles ap on ap.id = ev.actor
  where ev.participant_id = p_participant and is_staff() order by ev.created_at desc $$;
revoke all on function learner_access_history(uuid) from public, anon;
grant execute on function learner_access_history(uuid) to authenticated;

-- ============ 5. enforcement: restrictive policies on protected programme content ============
do $$ declare t text; begin
  foreach t in array array['learning_resources', 'assignments', 'submissions', 'assessment_results', 'course_modules', 'course_lessons', 'lesson_progress']
  loop
    execute format('drop policy if exists %I on %I', t || '_access_window', t);
    execute format('create policy %I on %I as restrictive for all to authenticated using ((select participant_access_active())) with check ((select participant_access_active()))', t || '_access_window', t);
  end loop;
end $$;

-- Stored files: submissions and learning resources follow the same rule. Other buckets are not affected.
drop policy if exists storage_access_window on storage.objects;
create policy storage_access_window on storage.objects as restrictive for all to authenticated
  using (bucket_id not in ('submissions', 'learning-resources') or (select participant_access_active()))
  with check (bucket_id not in ('submissions', 'learning-resources') or (select participant_access_active()));
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000018', 'cohort_access_windows');
commit;

\echo '== migration 20260101000019 access_rules_v2'
begin;
-- DIRA LEARN: management decisions on learning access (follow-up to migration 18).
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`. Never run first on production.
--
-- DECISIONS IMPLEMENTED (accepted by DIRA, see docs/COHORT_ACCESS.md)
--   1. One programme time zone. programmes.timezone, default 'Africa/Nairobi' (the existing reminder emails already use it).
--      Access times are exact moments; the time zone only decides how they are entered, shown and written in emails.
--   2. A withdrawn learner is treated as Suspended (learning access closes automatically; the record, certificates and profile stay).
--   3. Only a super administrator, Founder, Co-Founder or programme director can extend, shorten or suspend access, and only they can
--      set a cohort's access times. Other staff (coordinator) still see the access roster.
--   4. Reminder emails: 3 days before access opens, 7 days before it closes, and an in-app note plus email whenever one learner's access
--      is changed. Emails only go out when automatic email is approved (existing `email_automation` setting) and never include the
--      staff reason.
--   5. After access expires a learner can still READ their own results (submissions with scores and feedback, assessment results,
--      and the assignment titles and marks they belong to). They cannot submit, and learning materials and stored files stay closed.
--      Scheduled, pending and suspended learners get none of this.

-- ============ 1. programme time zone ============
alter table programmes add column if not exists timezone text not null default 'Africa/Nairobi';
create or replace function guard_programme_timezone() returns trigger language plpgsql as $$
begin
  if not exists (select 1 from pg_timezone_names where name = new.timezone) then
    raise exception 'Unknown time zone: %', new.timezone;
  end if;
  return new;
end $$;
drop trigger if exists trg_programme_timezone on programmes;
create trigger trg_programme_timezone before insert or update of timezone on programmes for each row execute function guard_programme_timezone();

-- ============ 2. who may change access ============
create or replace function can_manage_learner_access() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(app_role() in ('super_admin', 'founder', 'co_founder', 'programme_director'), false) $$;
revoke all on function can_manage_learner_access() from public, anon;
grant execute on function can_manage_learner_access() to authenticated;

-- Rewrite migration 18's functions from their stored source; abort if the expected text is missing.
do $$
declare
  r record; def text; newdef text;
begin
  for r in
    select * from (values
      ('set_learner_access_override(uuid,uuid,timestamptz,timestamptz,text)',
       'if not is_staff() then raise exception ''Only programme staff can change learner access''; end if;',
       'if not can_manage_learner_access() then raise exception ''Only a super administrator, Founder, Co-Founder or programme director can change learner access''; end if;'),
      ('set_learner_suspension(uuid,uuid,boolean,text)',
       'if not is_staff() then raise exception ''Only programme staff can change learner access''; end if;',
       'if not can_manage_learner_access() then raise exception ''Only a super administrator, Founder, Co-Founder or programme director can change learner access''; end if;'),
      ('learner_access_state(uuid,uuid)',
       'select * into a from learner_access where participant_id = p_participant and cohort_id = p_cohort;',
       'if exists (select 1 from participants where id = p_participant and status = ''withdrawn'') then return ''suspended''; end if;' || E'\n  ' ||
       'select * into a from learner_access where participant_id = p_participant and cohort_id = p_cohort;')
    ) as t(sig, old_txt, new_txt)
  loop
    def := pg_get_functiondef(('public.' || r.sig)::regprocedure);
    newdef := replace(def, r.old_txt, r.new_txt);
    if newdef = def then raise exception 'Migration 19: expected text not found in function %, nothing was changed', r.sig; end if;
    execute newdef;
  end loop;
end $$;

-- A cohort's access times decide who can open the portal, so they follow the same rule.
create or replace function guard_cohort_access_times() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if is_trusted_session() then return new; end if;
  if (tg_op = 'INSERT' and (new.access_opens_at is not null or new.access_closes_at is not null))
     or (tg_op = 'UPDATE' and (new.access_opens_at, new.access_closes_at) is distinct from (old.access_opens_at, old.access_closes_at)) then
    if not can_manage_learner_access() then
      raise exception 'Only a super administrator, Founder, Co-Founder or programme director can set a cohort''s access times';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists trg_cohort_access_times on cohorts;
create trigger trg_cohort_access_times before insert or update on cohorts for each row execute function guard_cohort_access_times();

-- ============ 3. results stay readable (read-only) after expiry ============
create or replace function participant_access_expired() returns boolean language sql stable security definer set search_path = public as $$
  select case when app_role() = 'participant' then exists (
    select 1 from cohort_enrolments e join participants p on p.id = e.participant_id
    where p.profile_id = auth.uid() and learner_access_state(e.participant_id, e.cohort_id) = 'expired')
  else false end $$;
revoke all on function participant_access_expired() from public, anon;
grant execute on function participant_access_expired() to authenticated;

do $$ declare t text; begin
  foreach t in array array['assignments', 'submissions', 'assessment_results']
  loop
    execute format('drop policy if exists %I on %I', t || '_access_window', t);
    -- reading: open while Active, and read-only after Expired
    execute format('create policy %I on %I as restrictive for select to authenticated using ((select participant_access_active()) or (select participant_access_expired()))', t || '_access_read', t);
    -- writing: only while Active
    execute format('create policy %I on %I as restrictive for insert to authenticated with check ((select participant_access_active()))', t || '_access_ins', t);
    execute format('create policy %I on %I as restrictive for update to authenticated using ((select participant_access_active())) with check ((select participant_access_active()))', t || '_access_upd', t);
    execute format('create policy %I on %I as restrictive for delete to authenticated using ((select participant_access_active()))', t || '_access_del', t);
  end loop;
end $$;

-- ============ 4. emails and in-app notes ============
insert into email_templates(key, name, subject, body, is_system) values
 ('access_opening_reminder', 'Learning access opens soon', 'Your learning access to {{cohort_name}} opens on {{access_date}}', E'Hello {{first_name}},\n\nYour learning access to {{cohort_name}} opens on {{access_date}}. Until then you can sign in, but programme materials stay closed.', true),
 ('access_closing_reminder', 'Learning access closes soon', 'Your learning access to {{cohort_name}} ends on {{access_date}}', E'Hello {{first_name}},\n\nYour learning access to {{cohort_name}} ends on {{access_date}}. Please finish and submit your work before then. You will still be able to view your results and certificate afterwards.', true),
 ('access_changed', 'Learning access changed', '{{change_title}}', E'Hello {{first_name}},\n\n{{change_body}}\n\nSign in to DIRA Learn for details.', true)
on conflict (key) do nothing;

-- One learner's access changed: tell that learner. The staff reason is internal and is never included.
create or replace function notify_access_change() returns trigger language plpgsql security definer set search_path = public as $$
declare uid uuid; cname text; tz text; ttl text; msg text; fmt constant text := 'FMDay DD Mon YYYY HH24:MI';
begin
  select pa.profile_id into uid from participants pa where pa.id = new.participant_id;
  select c.name, g.timezone into cname, tz from cohorts c join programmes g on g.id = c.programme_id where c.id = new.cohort_id;
  if uid is null or cname is null then return new; end if;
  if new.action = 'suspended' then
    ttl := 'Your learning access is paused'; msg := 'Your access to ' || cname || ' has been paused. Please contact the programme team.';
  elsif new.action = 'reinstated' then
    ttl := 'Your learning access is restored'; msg := 'Your access to ' || cname || ' is open again.';
  elsif new.action = 'override_cleared' then
    ttl := 'Your learning access dates changed'; msg := 'Your access to ' || cname || ' now follows the cohort dates.';
  else
    ttl := 'Your learning access dates changed';
    msg := 'Your access to ' || cname || ' has new dates.'
      || coalesce(' Opens: ' || to_char(new.opens_at at time zone tz, fmt) || '.', '')
      || coalesce(' Closes: ' || to_char(new.closes_at at time zone tz, fmt) || '.', '')
      || ' (Times are in ' || tz || '.)';
  end if;
  insert into notifications(user_id, kind, title, body) values (uid, 'access', ttl, msg);
  if email_automation_enabled() and not exists (select 1 from profiles where id = uid and email_opt_out) then
    perform _enqueue_email(uid, 'access_changed', jsonb_build_object('cohort_name', cname, 'change_title', ttl, 'change_body', msg), now(), 'event:access', null);
  end if;
  return new;
end $$;
drop trigger if exists trg_notify_access_change on learner_access_events;
create trigger trg_notify_access_change after insert on learner_access_events for each row execute function notify_access_change();

-- Scheduled reminders (service role only; the send-emails function calls it after queue_reminders).
create or replace function queue_access_reminders() returns int language plpgsql security definer set search_path = public as $$
declare r record; n int := 0; new_id uuid; kind_key text; fmt constant text := 'FMDay DD Mon YYYY HH24:MI';
begin
  if not email_automation_enabled() then return 0; end if;
  for r in
    select pa.profile_id as uid, e.cohort_id, c.name as cohort_name, g.timezone as tz,
           coalesce(a.opens_at_override, c.access_opens_at) as opens, coalesce(a.closes_at_override, c.access_closes_at) as closes
    from cohort_enrolments e
    join cohorts c on c.id = e.cohort_id
    join programmes g on g.id = c.programme_id
    join participants pa on pa.id = e.participant_id
    join profiles pr on pr.id = pa.profile_id
    left join learner_access a on a.participant_id = e.participant_id and a.cohort_id = e.cohort_id
    where pa.status <> 'withdrawn' and not coalesce(a.suspended, false) and not pr.email_opt_out and pr.status = 'active'
  loop
    if r.opens is not null and r.opens > now() and r.opens <= now() + interval '3 days' then
      kind_key := 'access_open:' || to_char(r.opens at time zone 'UTC', 'YYYYMMDDHH24MI');
      if not exists (select 1 from email_reminder_log l where l.kind = kind_key and l.ref_id = r.cohort_id and l.user_id = r.uid) then
        new_id := _enqueue_email(r.uid, 'access_opening_reminder', jsonb_build_object('cohort_name', r.cohort_name,
          'access_date', to_char(r.opens at time zone r.tz, fmt) || ' (' || r.tz || ')'), now(), 'reminder:access', null);
        insert into email_reminder_log(kind, ref_id, user_id) values (kind_key, r.cohort_id, r.uid) on conflict do nothing;
        if new_id is not null then n := n + 1; end if;
      end if;
    end if;
    if r.closes is not null and r.closes > now() and r.closes <= now() + interval '7 days' and (r.opens is not null and r.opens <= now()) then
      kind_key := 'access_close:' || to_char(r.closes at time zone 'UTC', 'YYYYMMDDHH24MI');
      if not exists (select 1 from email_reminder_log l where l.kind = kind_key and l.ref_id = r.cohort_id and l.user_id = r.uid) then
        new_id := _enqueue_email(r.uid, 'access_closing_reminder', jsonb_build_object('cohort_name', r.cohort_name,
          'access_date', to_char(r.closes at time zone r.tz, fmt) || ' (' || r.tz || ')'), now(), 'reminder:access', null);
        insert into email_reminder_log(kind, ref_id, user_id) values (kind_key, r.cohort_id, r.uid) on conflict do nothing;
        if new_id is not null then n := n + 1; end if;
      end if;
    end if;
  end loop;
  return n;
end $$;
revoke all on function queue_access_reminders() from public, anon, authenticated;
grant execute on function queue_access_reminders() to service_role;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000019', 'access_rules_v2');
commit;

\echo '== migration 20260101000020 individual_assignments'
begin;
-- DIRA LEARN: assign work to individual learners (master instruction, Phase 2).
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`. Never run first on production.
--
-- RULE: an assignment with NO recipient rows is for the whole cohort (or its track), exactly as today.
--       An assignment WITH recipient rows is for those learners only: other learners cannot see it, cannot submit to it,
--       and are not counted as missing it. Existing assignments are unaffected (they have no recipient rows).
-- Learners still only see their own submissions, feedback and grades (unchanged policies). Access windows from migrations 18 and 19 still apply.

create table assignment_recipients (
  assignment_id uuid not null references assignments(id) on delete cascade,
  participant_id uuid not null references participants(id) on delete cascade,
  created_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  primary key (assignment_id, participant_id)
);
create index idx_assignment_recipients_participant on assignment_recipients (participant_id);
create trigger aud_assignment_recipients after insert or update or delete on assignment_recipients for each row execute function audit_row();

-- A recipient must be enrolled in the assignment's cohort (and on its track, if it has one). Work already submitted cannot be unassigned.
create or replace function guard_assignment_recipient() returns trigger language plpgsql security definer set search_path = public as $$
declare a assignments;
begin
  if tg_op = 'INSERT' then
    select * into a from assignments where id = new.assignment_id;
    if not found then raise exception 'Assignment not found'; end if;
    if not exists (select 1 from cohort_enrolments e where e.participant_id = new.participant_id and e.cohort_id = a.cohort_id
                   and (a.track_id is null or e.track_id = a.track_id)) then
      raise exception 'That learner is not enrolled for this assignment';
    end if;
    new.created_by := coalesce(new.created_by, auth.uid());
    return new;
  end if;
  if tg_op = 'DELETE' then
    if exists (select 1 from submissions s where s.assignment_id = old.assignment_id and s.participant_id = old.participant_id)
       and exists (select 1 from assignments a2 where a2.id = old.assignment_id) then
      raise exception 'This learner has already submitted, so the assignment cannot be taken away';
    end if;
    return old;
  end if;
  raise exception 'Recipients cannot be edited; add or remove them';
end $$;
create trigger trg_guard_assignment_recipient before insert or update or delete on assignment_recipients for each row execute function guard_assignment_recipient();

alter table assignment_recipients enable row level security;
-- Read: staff, M&E, the trainer of that cohort, and the learner for their own rows only.
create policy arc_read on assignment_recipients for select to authenticated using (
  is_staff() or app_role() = 'me_officer' or participant_id = my_participant_id()
  or exists (select 1 from assignments a where a.id = assignment_id and a.cohort_id in (select my_trainer_cohorts())));
-- Write: staff, and the trainer of that cohort. Learners can never add themselves.
create policy arc_insert on assignment_recipients for insert to authenticated with check (
  is_staff() or exists (select 1 from assignments a where a.id = assignment_id and a.cohort_id in (select my_trainer_cohorts())));
create policy arc_delete on assignment_recipients for delete to authenticated using (
  is_staff() or exists (select 1 from assignments a where a.id = assignment_id and a.cohort_id in (select my_trainer_cohorts())));

-- Hide an individual assignment from every learner who is not a recipient. Restrictive: it can only narrow existing access.
create or replace function assignment_visible_to_me(p_assignment uuid) returns boolean language sql stable security definer set search_path = public as $$
  select case when app_role() = 'participant' then
    (not exists (select 1 from assignment_recipients r where r.assignment_id = p_assignment)
     or exists (select 1 from assignment_recipients r where r.assignment_id = p_assignment and r.participant_id = my_participant_id()))
  else true end $$;
revoke all on function assignment_visible_to_me(uuid) from public, anon;
grant execute on function assignment_visible_to_me(uuid) to authenticated;

create policy assignments_recipient_scope on assignments as restrictive for select to authenticated using ((select assignment_visible_to_me(id)));

-- ============ existing functions, rewritten from their stored source (abort if the expected text is missing) ============
do $$
declare r record; def text; newdef text;
begin
  for r in
    select * from (values
      -- submitting: a learner who was not chosen cannot submit
      ('guard_submission()',
       E'raise exception ''You are not enrolled for this assignment'';\n    end if;',
       E'raise exception ''You are not enrolled for this assignment'';\n    end if;\n' ||
       E'    if exists (select 1 from assignment_recipients r where r.assignment_id = a.id)\n' ||
       E'       and not exists (select 1 from assignment_recipients r where r.assignment_id = a.id and r.participant_id = new.participant_id) then\n' ||
       E'      raise exception ''This assignment was not assigned to you'';\n    end if;'),
      -- deadline reminders: only remind the chosen learners
      ('queue_reminders()',
       'and not exists (select 1 from submissions sb where sb.assignment_id = a.id and sb.participant_id = pa.id)',
       'and not exists (select 1 from submissions sb where sb.assignment_id = a.id and sb.participant_id = pa.id)' || E'\n      ' ||
       'and (not exists (select 1 from assignment_recipients ar where ar.assignment_id = a.id) or exists (select 1 from assignment_recipients ar where ar.assignment_id = a.id and ar.participant_id = pa.id))')
    ) as t(sig, old_txt, new_txt)
  loop
    def := pg_get_functiondef(('public.' || r.sig)::regprocedure);
    newdef := replace(def, r.old_txt, r.new_txt);
    if newdef = def then raise exception 'Migration 20: expected text not found in function %, nothing was changed', r.sig; end if;
    execute newdef;
  end loop;
end $$;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000020', 'individual_assignments');
commit;

\echo '== migration 20260101000021 daily_briefs'
begin;
-- DIRA LEARN: Daily Briefs (master instruction, Phase 3).
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`. Never run first on production.
--
-- WHAT IT ADDS
--   * daily_briefs: one brief per day, for one cohort or for all cohorts (cohort_id null). Draft, scheduled, published, withdrawn.
--   * brief_publishers: which programme staff and facilitators are AUTHORISED to write and publish briefs. Super Admin, Founder and
--     Co-Founder are always authorised and are the only ones who can grant or remove authorisation.
--   * daily_brief_events: append-only publication history (created, edited, scheduled, published, withdrawn ...).
--   * Scheduling: a scheduled brief becomes visible to learners at its time through the read policy itself (no timer needed);
--     publish_due_briefs() (called by the send-emails schedule) then marks it published and records the history.
-- WHO MAY DO WHAT
--   learners: read published briefs for their own cohort(s), or for all cohorts, while their learning access is Active. Nothing else.
--   authorised facilitators (trainers): write briefs for THEIR OWN cohorts only, never "all cohorts".
--   authorised staff (director, coordinator): any cohort or all cohorts.
--   executives: everything, plus granting authorisation.
--   Everyone else: nothing. Unauthorised publishing is refused by the database, not only hidden on screen.
-- DECISION FOR MANAGEMENT: "authorised" is implemented as an explicit grant by an executive. See docs/DAILY_BRIEFS.md.

create type brief_status as enum ('draft', 'scheduled', 'published', 'withdrawn');

-- ============ authorised publishers ============
create table brief_publishers (
  profile_id uuid primary key references profiles(id) on delete cascade,
  granted_by uuid references profiles(id),
  granted_at timestamptz not null default now()
);
create or replace function guard_brief_publisher() returns trigger language plpgsql security definer set search_path = public as $$
declare r role_code;
begin
  select role into r from profiles where id = new.profile_id;
  if r is null or r not in ('programme_director', 'programme_coordinator', 'trainer') then
    raise exception 'Only programme staff and facilitators can be authorised to publish briefs (executives already can)';
  end if;
  new.granted_by := coalesce(auth.uid(), new.granted_by);
  return new;
end $$;
create trigger trg_guard_brief_publisher before insert on brief_publishers for each row execute function guard_brief_publisher();
create trigger aud_brief_publishers after insert or update or delete on brief_publishers for each row execute function audit_row();
alter table brief_publishers enable row level security;
create policy bp_read   on brief_publishers for select to authenticated using (is_executive() or profile_id = auth.uid());
create policy bp_insert on brief_publishers for insert to authenticated with check (is_executive());
create policy bp_delete on brief_publishers for delete to authenticated using (is_executive());

create or replace function can_publish_briefs() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(is_executive() or (app_role() in ('programme_director', 'programme_coordinator', 'trainer')
         and exists (select 1 from brief_publishers bp where bp.profile_id = auth.uid())), false) $$;
revoke all on function can_publish_briefs() from public, anon;
grant execute on function can_publish_briefs() to authenticated;

-- ============ briefs ============
create table daily_briefs (
  id uuid primary key default gen_random_uuid(),
  brief_date date not null,
  cohort_id uuid references cohorts(id),                         -- null = all relevant cohorts
  title text not null check (length(btrim(title)) between 3 and 120),
  reflection text check (reflection is null or length(reflection) <= 1200),
  objectives text[] not null default '{}' check (cardinality(objectives) <= 8),
  reflection_question text check (reflection_question is null or length(reflection_question) <= 400),
  status brief_status not null default 'draft',
  publish_at timestamptz,
  published_at timestamptz,
  created_by uuid references profiles(id),
  updated_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint daily_briefs_schedule_needs_time check (status <> 'scheduled' or publish_at is not null)
);
-- One live (scheduled or published) brief per day per audience; withdraw it to replace it.
create unique index uq_daily_briefs_live on daily_briefs (brief_date, coalesce(cohort_id, '00000000-0000-0000-0000-000000000000'::uuid)) where status in ('scheduled', 'published');
create index idx_daily_briefs_date on daily_briefs (brief_date desc);
create index idx_daily_briefs_cohort on daily_briefs (cohort_id, brief_date desc);

create or replace function brief_is_live(p_status brief_status, p_publish_at timestamptz) returns boolean language sql stable as $$
  select p_status = 'published' or (p_status = 'scheduled' and p_publish_at is not null and p_publish_at <= now()) $$;

create or replace function guard_daily_brief() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    if not is_trusted_session() then
      if not can_publish_briefs() then raise exception 'You are not authorised to publish daily briefs'; end if;
      if old.status <> 'draft' then raise exception 'Only drafts can be deleted. Withdraw a published brief instead'; end if;
    end if;
    return old;
  end if;

  if not is_trusted_session() then
    if not can_publish_briefs() then raise exception 'You are not authorised to publish daily briefs'; end if;
    if app_role() = 'trainer' then
      if new.cohort_id is null or new.cohort_id not in (select my_trainer_cohorts()) then
        raise exception 'Facilitators can write briefs only for their own cohorts';
      end if;
      if tg_op = 'UPDATE' and (old.cohort_id is null or old.cohort_id not in (select my_trainer_cohorts())) then
        raise exception 'Facilitators can edit briefs only for their own cohorts';
      end if;
    end if;
    if new.status = 'scheduled' and (tg_op = 'INSERT' or old.status is distinct from 'scheduled' or old.publish_at is distinct from new.publish_at)
       and (new.publish_at is null or new.publish_at <= now()) then
      raise exception 'Choose a future time to schedule publication';
    end if;
  end if;

  if tg_op = 'INSERT' then new.created_by := coalesce(auth.uid(), new.created_by); end if;
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  new.updated_at := now();
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then new.published_at := now(); end if;
  if new.status = 'draft' then new.published_at := null; end if;
  if new.status <> 'scheduled' and new.status <> 'published' and new.status <> 'withdrawn' then new.publish_at := null; end if;
  return new;
end $$;
create trigger trg_guard_daily_brief before insert or update or delete on daily_briefs for each row execute function guard_daily_brief();

-- ============ publication history (append-only) ============
create table daily_brief_events (
  id uuid primary key default gen_random_uuid(),
  brief_id uuid not null,                                    -- no foreign key: history outlives a deleted draft
  action text not null check (action in ('created', 'edited', 'scheduled', 'published', 'published_on_schedule', 'withdrawn', 'returned_to_draft')),
  title text not null,
  brief_date date not null,
  cohort_id uuid,
  actor uuid references profiles(id),
  created_at timestamptz not null default now()
);
create index idx_daily_brief_events_brief on daily_brief_events (brief_id, created_at desc);
create or replace function block_brief_event_change() returns trigger language plpgsql as $$
begin raise exception 'Publication history cannot be edited or deleted'; end $$;
create trigger trg_brief_events_append_only before update or delete on daily_brief_events for each row execute function block_brief_event_change();

create or replace function log_daily_brief() returns trigger language plpgsql security definer set search_path = public as $$
declare act text;
begin
  if tg_op = 'INSERT' then act := 'created';
  elsif old.status is distinct from new.status then
    act := case new.status
      when 'published' then case when old.status = 'scheduled' and auth.uid() is null then 'published_on_schedule' else 'published' end
      when 'scheduled' then 'scheduled'
      when 'withdrawn' then 'withdrawn'
      else 'returned_to_draft' end;
  else act := 'edited';
  end if;
  insert into daily_brief_events(brief_id, action, title, brief_date, cohort_id, actor) values (new.id, act, new.title, new.brief_date, new.cohort_id, auth.uid());
  return new;
end $$;
create trigger trg_log_daily_brief after insert or update on daily_briefs for each row execute function log_daily_brief();

-- ============ row level security ============
alter table daily_briefs enable row level security;
alter table daily_brief_events enable row level security;

create policy db_staff_read on daily_briefs for select to authenticated using (is_staff());
create policy db_trainer_read on daily_briefs for select to authenticated using (
  app_role() = 'trainer' and (cohort_id in (select my_trainer_cohorts()) or (cohort_id is null and brief_is_live(status, publish_at))));
create policy db_learner_read on daily_briefs for select to authenticated using (
  app_role() = 'participant' and brief_is_live(status, publish_at)
  and (cohort_id is null or cohort_id in (select e.cohort_id from cohort_enrolments e where e.participant_id = my_participant_id())));
create policy db_insert on daily_briefs for insert to authenticated with check (can_publish_briefs());
create policy db_update on daily_briefs for update to authenticated using (can_publish_briefs()) with check (can_publish_briefs());
create policy db_delete on daily_briefs for delete to authenticated using (can_publish_briefs() and status = 'draft');
-- A learner whose learning access is not Active sees no briefs (migration 18). Restrictive: it can only narrow.
create policy daily_briefs_access_window on daily_briefs as restrictive for select to authenticated using ((select participant_access_active()));

create policy dbe_read on daily_brief_events for select to authenticated using (is_staff() or can_publish_briefs());

-- ============ scheduled publication sweep (service role only; send-emails calls it) ============
create or replace function publish_due_briefs() returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  update daily_briefs set status = 'published', published_at = now() where status = 'scheduled' and publish_at <= now();
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function publish_due_briefs() from public, anon, authenticated;
grant execute on function publish_due_briefs() to service_role;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000021', 'daily_briefs');
commit;

\echo '== migration 20260101000022 dira_connect'
begin;
-- DIRA LEARN: DIRA Connect, private messaging and cohort discussions (master instruction, Phase 4).
-- STATUS: written, NOT yet executed. Local first: `supabase db reset` then `supabase test db`. Never run first on production.
--
-- WHAT IT ADDS
--   * connect_conversations: one DISCUSSION per cohort (created automatically) and PRIVATE conversations, each between one learner
--     and one facilitator (a trainer assigned to that learner's cohort).
--   * connect_messages (plain text, 1 to 2000 characters, no attachments), connect_reads (unread counts), connect_reports,
--     connect_mutes, connect_oversight (explicit grants), connect_oversight_log, connect_hidden_originals.
--   * Row level security on every table, plus access functions so the rules live in the database, not the screen.
--   * Realtime: connect_messages is added to the supabase_realtime publication (Realtime still applies the same read policy).
--
-- WHO CAN SEE WHAT
--   Private conversation: ONLY the learner and that facilitator (and only while the facilitator is still assigned to the learner's
--     cohort and the learner's learning access is Active). No administrator, executive or other staff member can read it by default.
--   Cohort discussion: learners enrolled in that cohort (access Active) and trainers assigned to it. Executives and people granted
--     'discussions' oversight can READ it (not post). Nobody can see another cohort's discussion.
--   Private oversight: only a person explicitly granted 'private' oversight, only through connect_oversight_read() which demands a
--     written reason and writes a log entry that executives can review. NO ONE has this grant when the migration runs.
-- SAFEGUARDING: a member can report any message. The report keeps a snapshot of THAT message only, so a moderator never gets the rest of a
--   private conversation. Moderators (executives and people granted 'reports') can dismiss, hide the message, or escalate. They can also
--   lock a cohort discussion and mute a learner from discussions. The safeguarding PROCESS (who handles an escalation, timelines,
--   under-18 rules) is a management decision and is NOT invented here. See docs/DIRA_CONNECT.md.
-- STARTING A PRIVATE CONVERSATION: learners start them; facilitators respond. (Management decision: may facilitators start them?)

-- ============ tables ============
create table connect_conversations (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('direct', 'cohort')),
  cohort_id uuid references cohorts(id) on delete cascade,          -- cohort discussions
  learner_id uuid references participants(id) on delete cascade,    -- private conversations
  facilitator_id uuid references profiles(id) on delete cascade,    -- private conversations
  locked boolean not null default false,
  locked_by uuid references profiles(id),
  locked_at timestamptz,
  last_message_at timestamptz,
  created_at timestamptz not null default now(),
  constraint connect_conv_shape check (
    (kind = 'cohort' and cohort_id is not null and learner_id is null and facilitator_id is null) or
    (kind = 'direct' and learner_id is not null and facilitator_id is not null and cohort_id is null))
);
create unique index uq_connect_cohort on connect_conversations (cohort_id) where kind = 'cohort';
create unique index uq_connect_direct on connect_conversations (learner_id, facilitator_id) where kind = 'direct';
create index idx_connect_conv_facilitator on connect_conversations (facilitator_id) where kind = 'direct';

create table connect_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references connect_conversations(id) on delete cascade,
  sender_id uuid not null references profiles(id),
  body text not null check (length(btrim(body)) between 1 and 2000),
  created_at timestamptz not null default now(),
  hidden_at timestamptz,
  hidden_by uuid references profiles(id),
  hide_reason text
);
create index idx_connect_messages_conv on connect_messages (conversation_id, created_at desc);
create index idx_connect_messages_sender on connect_messages (sender_id, created_at desc);

create table connect_reads (
  conversation_id uuid not null references connect_conversations(id) on delete cascade,
  profile_id uuid not null references profiles(id) on delete cascade,
  last_read_at timestamptz not null default now(),
  primary key (conversation_id, profile_id)
);

create table connect_hidden_originals (
  message_id uuid primary key references connect_messages(id) on delete cascade,
  body text not null,
  hidden_by uuid references profiles(id),
  created_at timestamptz not null default now()
);

create table connect_reports (
  id uuid primary key default gen_random_uuid(),
  message_id uuid not null references connect_messages(id) on delete cascade,
  conversation_id uuid not null references connect_conversations(id) on delete cascade,
  reporter_id uuid not null references profiles(id),
  reason text not null check (reason in ('bullying_or_harassment', 'inappropriate_content', 'personal_information', 'safety_concern', 'spam', 'other')),
  note text check (note is null or length(note) <= 500),
  snapshot_body text not null,                       -- the reported message only, as it was when reported
  snapshot_sender uuid not null references profiles(id),
  status text not null default 'open' check (status in ('open', 'dismissed', 'hidden', 'escalated')),
  handled_by uuid references profiles(id),
  handled_at timestamptz,
  handler_note text check (handler_note is null or length(handler_note) <= 500),
  created_at timestamptz not null default now(),
  constraint connect_reports_once unique (message_id, reporter_id)
);
create index idx_connect_reports_status on connect_reports (status, created_at desc);

create table connect_mutes (
  profile_id uuid primary key references profiles(id) on delete cascade,
  until timestamptz not null,
  reason text not null check (length(btrim(reason)) >= 5),
  muted_by uuid references profiles(id),
  created_at timestamptz not null default now()
);

create table connect_oversight (
  profile_id uuid not null references profiles(id) on delete cascade,
  scope text not null check (scope in ('discussions', 'reports', 'private')),
  reason text not null check (length(btrim(reason)) >= 10),
  granted_by uuid references profiles(id),
  granted_at timestamptz not null default now(),
  primary key (profile_id, scope)
);

create table connect_oversight_log (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references profiles(id),
  conversation_id uuid not null references connect_conversations(id) on delete cascade,
  reason text not null,
  created_at timestamptz not null default now()
);

-- Cohort discussions are created automatically.
create or replace function create_cohort_discussion() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into connect_conversations(kind, cohort_id) values ('cohort', new.id) on conflict do nothing;
  return new;
end $$;
create trigger trg_cohort_discussion after insert on cohorts for each row execute function create_cohort_discussion();
insert into connect_conversations(kind, cohort_id) select 'cohort', c.id from cohorts c on conflict do nothing;

-- ============ access functions (the rules live here) ============
create or replace function connect_is_moderator() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(is_executive() or exists (select 1 from connect_oversight o where o.profile_id = auth.uid() and o.scope = 'reports'), false) $$;

create or replace function connect_is_discussion_overseer() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(is_executive() or exists (select 1 from connect_oversight o where o.profile_id = auth.uid() and o.scope = 'discussions'), false) $$;

-- Is this facilitator still assigned to a cohort the learner is enrolled in?
create or replace function connect_facilitator_assigned(p_learner uuid, p_facilitator uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from trainer_assignments ta join cohort_enrolments e on e.cohort_id = ta.cohort_id
                 where ta.trainer_id = p_facilitator and e.participant_id = p_learner) $$;

-- Member of the conversation right now (private: the two people; discussion: enrolled learners and assigned trainers).
create or replace function connect_is_member(p_conv uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case c.kind
      when 'direct' then
        (c.learner_id = my_participant_id() and app_role() = 'participant')
        or (c.facilitator_id = auth.uid() and app_role() = 'trainer' and connect_facilitator_assigned(c.learner_id, c.facilitator_id))
      else
        (app_role() = 'trainer' and c.cohort_id in (select my_trainer_cohorts()))
        or (app_role() = 'participant' and exists (select 1 from cohort_enrolments e where e.cohort_id = c.cohort_id and e.participant_id = my_participant_id()))
    end
    from connect_conversations c where c.id = p_conv), false) $$;

create or replace function connect_can_see(p_conv uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case
      when app_role() = 'participant' then connect_is_member(p_conv) and participant_access_active()
      when connect_is_member(p_conv) then true
      else c.kind = 'cohort' and connect_is_discussion_overseer()
    end
    from connect_conversations c where c.id = p_conv), false) $$;

create or replace function connect_can_post(p_conv uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select not c.locked and app_role() in ('participant', 'trainer') and connect_is_member(p_conv)
       and (app_role() <> 'participant' or participant_access_active())
       and (c.kind = 'direct' or not exists (select 1 from connect_mutes m where m.profile_id = auth.uid() and m.until > now()))
    from connect_conversations c where c.id = p_conv), false) $$;

revoke all on function connect_is_moderator(), connect_is_discussion_overseer(), connect_facilitator_assigned(uuid, uuid), connect_is_member(uuid), connect_can_see(uuid), connect_can_post(uuid) from public, anon;
grant execute on function connect_is_moderator(), connect_is_discussion_overseer(), connect_can_see(uuid), connect_can_post(uuid) to authenticated;

-- ============ message guard, bookkeeping and notification ============
create or replace function guard_connect_message() returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.body := btrim(new.body);
  new.sender_id := coalesce(auth.uid(), new.sender_id);
  new.hidden_at := null; new.hidden_by := null; new.hide_reason := null;
  if not is_trusted_session() and (select count(*) from connect_messages m where m.sender_id = new.sender_id and m.created_at > now() - interval '1 minute') >= 15 then
    raise exception 'You are sending messages too quickly. Please wait a moment';
  end if;
  return new;
end $$;
create trigger trg_guard_connect_message before insert on connect_messages for each row execute function guard_connect_message();

create or replace function after_connect_message() returns trigger language plpgsql security definer set search_path = public as $$
declare c connect_conversations; recipient uuid; last_seen timestamptz;
begin
  update connect_conversations set last_message_at = new.created_at where id = new.conversation_id;
  select * into c from connect_conversations where id = new.conversation_id;
  if c.kind = 'direct' then
    select case when new.sender_id = c.facilitator_id then (select profile_id from participants where id = c.learner_id) else c.facilitator_id end into recipient;
    if recipient is not null then
      select last_read_at into last_seen from connect_reads where conversation_id = c.id and profile_id = recipient;
      -- one notification per burst: skip when the recipient already has an unread message from this sender here
      if not exists (select 1 from connect_messages m where m.conversation_id = c.id and m.sender_id = new.sender_id and m.id <> new.id and m.created_at > coalesce(last_seen, '-infinity'::timestamptz)) then
        insert into notifications(user_id, kind, title, body) values (recipient, 'message', 'New private message', 'You have a new message in DIRA Connect.');
      end if;
    end if;
  end if;
  return new;
end $$;
create trigger trg_after_connect_message after insert on connect_messages for each row execute function after_connect_message();

-- Messages are never edited or deleted by users; only the moderation function below changes a message (hide).
create or replace function block_connect_message_delete() returns trigger language plpgsql as $$
begin raise exception 'Messages cannot be deleted'; end $$;
create trigger trg_connect_message_no_delete before delete on connect_messages for each row execute function block_connect_message_delete();

-- ============ row level security ============
alter table connect_conversations enable row level security;
alter table connect_messages enable row level security;
alter table connect_reads enable row level security;
alter table connect_hidden_originals enable row level security;
alter table connect_reports enable row level security;
alter table connect_mutes enable row level security;
alter table connect_oversight enable row level security;
alter table connect_oversight_log enable row level security;

create policy cc_read on connect_conversations for select to authenticated using (connect_can_see(id));
create policy cm_read on connect_messages for select to authenticated using (connect_can_see(conversation_id));
create policy cm_insert on connect_messages for insert to authenticated with check (sender_id = auth.uid() and connect_can_post(conversation_id));
create policy cr_read on connect_reads for select to authenticated using (profile_id = auth.uid());
create policy cr_insert on connect_reads for insert to authenticated with check (profile_id = auth.uid() and connect_can_see(conversation_id));
create policy cr_update on connect_reads for update to authenticated using (profile_id = auth.uid()) with check (profile_id = auth.uid() and connect_can_see(conversation_id));
create policy chO_read on connect_hidden_originals for select to authenticated using (connect_is_moderator());
create policy crep_read on connect_reports for select to authenticated using (reporter_id = auth.uid() or connect_is_moderator());
create policy cmu_read on connect_mutes for select to authenticated using (connect_is_moderator() or profile_id = auth.uid());
create policy cov_read on connect_oversight for select to authenticated using (is_executive() or profile_id = auth.uid());
create policy cov_insert on connect_oversight for insert to authenticated with check (is_executive());
create policy cov_delete on connect_oversight for delete to authenticated using (is_executive());
create policy covl_read on connect_oversight_log for select to authenticated using (is_executive());
-- No insert/update/delete policy exists for conversations, reports, mutes, hidden originals or the oversight log: they change only through the functions below.

-- Oversight grants: only staff and executives, always with a reason; the grant is audited.
create or replace function guard_connect_oversight() returns trigger language plpgsql security definer set search_path = public as $$
declare r role_code;
begin
  select role into r from profiles where id = new.profile_id;
  if r is null or r not in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator') then
    raise exception 'Oversight can only be granted to executives and programme staff';
  end if;
  new.granted_by := coalesce(auth.uid(), new.granted_by);
  return new;
end $$;
create trigger trg_guard_connect_oversight before insert on connect_oversight for each row execute function guard_connect_oversight();
create trigger aud_connect_oversight after insert or update or delete on connect_oversight for each row execute function audit_row();
create trigger aud_connect_mutes after insert or update or delete on connect_mutes for each row execute function audit_row();

-- ============ functions the screens call ============
-- Facilitators a learner may message: trainers assigned to the learner's cohort.
create or replace function connect_my_facilitators() returns table(profile_id uuid, display_name text) language sql stable security definer set search_path = public as $$
  select distinct p.id, btrim(p.first_name || ' ' || p.last_name)
  from cohort_enrolments e join trainer_assignments ta on ta.cohort_id = e.cohort_id join profiles p on p.id = ta.trainer_id
  where app_role() = 'participant' and participant_access_active() and e.participant_id = my_participant_id() and p.role = 'trainer' and p.status = 'active' $$;

create or replace function connect_start_direct(p_facilitator uuid) returns uuid language plpgsql security definer set search_path = public as $$
declare me uuid := my_participant_id(); cid uuid;
begin
  if app_role() <> 'participant' or me is null then raise exception 'Only learners can start a private conversation'; end if;
  if not participant_access_active() then raise exception 'Your learning access is not open'; end if;
  if not exists (select 1 from profiles where id = p_facilitator and role = 'trainer' and status = 'active') or not connect_facilitator_assigned(me, p_facilitator) then
    raise exception 'You can only message a facilitator assigned to your cohort';
  end if;
  insert into connect_conversations(kind, learner_id, facilitator_id) values ('direct', me, p_facilitator) on conflict (learner_id, facilitator_id) where kind = 'direct' do nothing;
  select id into cid from connect_conversations where kind = 'direct' and learner_id = me and facilitator_id = p_facilitator;
  return cid;
end $$;

create or replace function connect_threads()
returns table(conversation_id uuid, kind text, title text, subtitle text, last_message_at timestamptz, unread bigint, locked boolean)
language sql stable security definer set search_path = public as $$
  select c.id, c.kind,
         case c.kind when 'cohort' then (select name from cohorts where id = c.cohort_id)
              else case when c.facilitator_id = auth.uid() then (select btrim(first_name || ' ' || last_name) from profiles where id = (select profile_id from participants where id = c.learner_id))
                        else (select btrim(first_name || ' ' || last_name) from profiles where id = c.facilitator_id) end end,
         case c.kind when 'cohort' then 'Cohort discussion' else 'Private conversation' end,
         c.last_message_at,
         (select count(*) from connect_messages m where m.conversation_id = c.id and m.sender_id <> auth.uid() and m.hidden_at is null
            and m.created_at > coalesce((select r.last_read_at from connect_reads r where r.conversation_id = c.id and r.profile_id = auth.uid()), '-infinity'::timestamptz)),
         c.locked
  from connect_conversations c where connect_can_see(c.id)
  order by c.last_message_at desc nulls last, c.created_at desc $$;

create or replace function connect_thread_messages(p_conversation uuid, p_before timestamptz default null, p_limit int default 50)
returns table(id uuid, sender_id uuid, sender_name text, sender_role text, body text, created_at timestamptz, hidden boolean, mine boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if not connect_can_see(p_conversation) then return; end if;
  return query
    select m.id, m.sender_id,
           case when pr.role = 'trainer' then btrim(pr.first_name || ' ' || pr.last_name)
                else btrim(pr.first_name || ' ' || left(coalesce(pr.last_name, ''), 1) || '.') end,
           case when pr.role = 'trainer' then 'Facilitator' else 'Learner' end,
           m.body, m.created_at, (m.hidden_at is not null), (m.sender_id = auth.uid())
    from connect_messages m join profiles pr on pr.id = m.sender_id
    where m.conversation_id = p_conversation and (p_before is null or m.created_at < p_before)
    order by m.created_at desc, m.id desc limit least(greatest(p_limit, 1), 100);
end $$;

create or replace function connect_mark_read(p_conversation uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if not connect_can_see(p_conversation) then return; end if;
  insert into connect_reads(conversation_id, profile_id, last_read_at) values (p_conversation, auth.uid(), now())
  on conflict (conversation_id, profile_id) do update set last_read_at = now();
end $$;

create or replace function connect_report_message(p_message uuid, p_reason text, p_note text default null) returns void language plpgsql security definer set search_path = public as $$
declare m connect_messages;
begin
  select * into m from connect_messages where id = p_message;
  if not found or not connect_is_member(m.conversation_id) or not connect_can_see(m.conversation_id) then raise exception 'You can only report messages in your own conversations'; end if;
  if m.sender_id = auth.uid() then raise exception 'You cannot report your own message'; end if;
  insert into connect_reports(message_id, conversation_id, reporter_id, reason, note, snapshot_body, snapshot_sender)
  values (m.id, m.conversation_id, auth.uid(), p_reason, nullif(btrim(coalesce(p_note, '')), ''), m.body, m.sender_id)
  on conflict (message_id, reporter_id) do nothing;
end $$;

create or replace function connect_list_reports(p_status text default 'open')
returns table(id uuid, created_at timestamptz, reason text, note text, snapshot_body text, sender_id uuid, sender_name text, conversation_id uuid, conversation_kind text, conversation_title text, status text, handler_note text)
language sql stable security definer set search_path = public as $$
  select r.id, r.created_at, r.reason, r.note, r.snapshot_body, r.snapshot_sender, btrim(sp.first_name || ' ' || sp.last_name), r.conversation_id, c.kind,
         case c.kind when 'cohort' then (select name from cohorts where id = c.cohort_id) else 'Private conversation' end, r.status, r.handler_note
  from connect_reports r join connect_conversations c on c.id = r.conversation_id join profiles sp on sp.id = r.snapshot_sender
  where connect_is_moderator() and (p_status = 'all' or r.status = p_status) order by r.created_at desc limit 200 $$;

create or replace function connect_handle_report(p_report uuid, p_action text, p_note text default null) returns void language plpgsql security definer set search_path = public as $$
declare r connect_reports;
begin
  if not connect_is_moderator() then raise exception 'Only moderators can handle reports'; end if;
  if p_action not in ('dismiss', 'hide', 'escalate') then raise exception 'Unknown action'; end if;
  select * into r from connect_reports where id = p_report;
  if not found then raise exception 'Report not found'; end if;
  if p_action = 'hide' then
    insert into connect_hidden_originals(message_id, body, hidden_by) select m.id, m.body, auth.uid() from connect_messages m where m.id = r.message_id and m.hidden_at is null on conflict do nothing;
    update connect_messages set body = 'This message was removed by a moderator.', hidden_at = now(), hidden_by = auth.uid(), hide_reason = nullif(btrim(coalesce(p_note, '')), '') where id = r.message_id and hidden_at is null;
  end if;
  update connect_reports set status = case p_action when 'dismiss' then 'dismissed' when 'hide' then 'hidden' else 'escalated' end,
         handled_by = auth.uid(), handled_at = now(), handler_note = nullif(btrim(coalesce(p_note, '')), '') where id = p_report;
end $$;

create or replace function connect_set_lock(p_conversation uuid, p_locked boolean) returns void language plpgsql security definer set search_path = public as $$
begin
  if not connect_is_moderator() then raise exception 'Only moderators can lock a discussion'; end if;
  update connect_conversations set locked = p_locked, locked_by = case when p_locked then auth.uid() end, locked_at = case when p_locked then now() end
   where id = p_conversation and kind = 'cohort';
  if not found then raise exception 'Only cohort discussions can be locked'; end if;
end $$;

create or replace function connect_mute(p_profile uuid, p_until timestamptz, p_reason text) returns void language plpgsql security definer set search_path = public as $$
begin
  if not connect_is_moderator() then raise exception 'Only moderators can mute'; end if;
  if p_until <= now() then raise exception 'Choose a future time'; end if;
  if not exists (select 1 from profiles where id = p_profile and role in ('participant', 'trainer')) then raise exception 'Only learners and facilitators can be muted'; end if;
  insert into connect_mutes(profile_id, until, reason, muted_by) values (p_profile, p_until, btrim(p_reason), auth.uid())
  on conflict (profile_id) do update set until = excluded.until, reason = excluded.reason, muted_by = auth.uid(), created_at = now();
end $$;
create or replace function connect_unmute(p_profile uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if not connect_is_moderator() then raise exception 'Only moderators can unmute'; end if;
  delete from connect_mutes where profile_id = p_profile;
end $$;

-- The ONLY way anyone but the two people can read a private conversation: an explicit 'private' grant, a written reason, and a log entry.
create or replace function connect_oversight_read(p_conversation uuid, p_reason text)
returns table(id uuid, sender_name text, body text, created_at timestamptz)
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from connect_oversight o where o.profile_id = auth.uid() and o.scope = 'private') then
    raise exception 'You have not been granted private conversation oversight';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'A written reason of at least 10 characters is required'; end if;
  if not exists (select 1 from connect_conversations c where c.id = p_conversation and c.kind = 'direct') then raise exception 'Not a private conversation'; end if;
  insert into connect_oversight_log(profile_id, conversation_id, reason) values (auth.uid(), p_conversation, btrim(p_reason));
  return query select m.id, btrim(pr.first_name || ' ' || pr.last_name), m.body, m.created_at
    from connect_messages m join profiles pr on pr.id = m.sender_id where m.conversation_id = p_conversation order by m.created_at desc limit 200;
end $$;

revoke all on function connect_my_facilitators(), connect_start_direct(uuid), connect_threads(), connect_thread_messages(uuid, timestamptz, int), connect_mark_read(uuid),
  connect_report_message(uuid, text, text), connect_list_reports(text), connect_handle_report(uuid, text, text), connect_set_lock(uuid, boolean),
  connect_mute(uuid, timestamptz, text), connect_unmute(uuid), connect_oversight_read(uuid, text) from public, anon;
grant execute on function connect_my_facilitators(), connect_start_direct(uuid), connect_threads(), connect_thread_messages(uuid, timestamptz, int), connect_mark_read(uuid),
  connect_report_message(uuid, text, text), connect_list_reports(text), connect_handle_report(uuid, text, text), connect_set_lock(uuid, boolean),
  connect_mute(uuid, timestamptz, text), connect_unmute(uuid), connect_oversight_read(uuid, text) to authenticated;

-- ============ Realtime ============
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table connect_messages;
  end if;
end $$;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000022', 'dira_connect');
commit;

\echo '== migration 20260101000023 v8_audit_fixes'
begin;
-- DIRA LEARN: fixes found by the V8 handover audit (19 Nov 2026), the first time migrations 1-22 were executed on PostgreSQL.
-- STATUS: executed and tested locally on PostgreSQL 16 with a Supabase stand-in (see docs/HANDOVER_AUDIT_V8.md). Not yet on Supabase.
-- No data is changed. Rollback: supabase/rollback/20260101000023_v8_audit_fixes_down.sql
--
-- 1. learner_access_state(): NULL-logic slip. For a signed-in user who is not a learner (for example an applicant or a mentor),
--    "p_participant = my_participant_id()" is NULL, so "not (... or NULL or ...)" is NULL and the guard did not stop them:
--    they could look up any learner's access status. Now only staff, the learner, the learner's trainer, or a trusted server
--    session (reminder jobs) get an answer; everyone else gets NULL.
-- 2. Workflow flags no longer outlive the function that sets them. transition_application(), decide_application() and
--    review_curriculum_topic() switched a transaction-wide flag on and never off, so a later direct UPDATE in the SAME transaction
--    could skip the application-status and topic guards. Through the app every request is its own transaction, so this was not
--    reachable from the screens, but it is closed now (defence in depth).
-- 3. DIRA Connect: sending a message "as someone else" is refused. Before, the database silently rewrote the sender to the
--    signed-in person and posted the message; nobody could impersonate anyone, but the message was still posted. Now it is rejected.

do $$
declare r record; def text; newdef text;
begin
  for r in
    select * from (values
      ('learner_access_state(uuid,uuid)',
       'if not (is_staff() or p_participant = my_participant_id() or trainer_can_see_participant(p_participant)) then return null; end if;',
       'if not coalesce(is_trusted_session() or is_staff() or p_participant = my_participant_id() or trainer_can_see_participant(p_participant), false) then return null; end if;'),
      ('transition_application(uuid,application_status,text)',
       'update applications set status = p_to where id = p_app;',
       'update applications set status = p_to where id = p_app;' || E'\n  ' || 'perform set_config(''dira.application_transition'', ''off'', true);'),
      ('decide_application(uuid,text,text)',
       'return jsonb_build_object(''status'', new_status, ''participant_id'', pid);',
       'perform set_config(''dira.application_transition'', ''off'', true);' || E'\n  ' ||
       'perform set_config(''dira.application_decision'', ''off'', true);' || E'\n  ' ||
       'return jsonb_build_object(''status'', new_status, ''participant_id'', pid);'),
      ('review_curriculum_topic(uuid,text,text)',
       'return jsonb_build_object(''status'', new_state);',
       'perform set_config(''dira.topic_review'', ''off'', true);' || E'\n  ' || 'return jsonb_build_object(''status'', new_state);'),
      ('guard_connect_message()',
       'new.sender_id := coalesce(auth.uid(), new.sender_id);',
       'if not is_trusted_session() and new.sender_id is distinct from auth.uid() then' || E'\n    ' ||
       'raise exception ''You can only send messages as yourself'';' || E'\n  ' || 'end if;' || E'\n  ' ||
       'new.sender_id := coalesce(auth.uid(), new.sender_id);')
    ) as t(sig, old_txt, new_txt)
  loop
    def := pg_get_functiondef(('public.' || r.sig)::regprocedure);
    if (length(def) - length(replace(def, r.old_txt, ''))) / length(r.old_txt) <> 1 then
      raise exception 'Migration 23: expected text not found exactly once in function %, nothing was changed', r.sig;
    end if;
    newdef := replace(def, r.old_txt, r.new_txt);
    execute newdef;
  end loop;
end $$;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000023', 'v8_audit_fixes');
commit;

\echo '== migration 20260101000024 safeguarding_officers'
begin;
-- DIRA LEARN: Phase 4 completion, part 1 – designated safeguarding officers, confidential safeguarding records, escalation,
-- and stricter private-conversation oversight (management decisions of 19 Nov 2026, see docs/SAFEGUARDING.md).
-- STATUS: executed and tested locally (PostgreSQL 16 + Supabase stand-in). NOT applied to any Supabase project.
-- Rollback: supabase/rollback/20260101000024_safeguarding_officers_down.sql
--
-- WHAT IT DOES
--   * Safeguarding Lead and Deputy are DESIGNATED positions (table safeguarding_officers). Nobody holds them when this runs.
--     An executive appoints them, never themselves. The Deputy acts when the Lead is unavailable or not appointed.
--   * Safeguarding records become confidential: ONLY the current Lead and Deputy can read or change them. Executives lose their
--     automatic access (they keep it only through an explicit, time-limited, audited exceptional grant made by someone else).
--   * Records gain urgency, acknowledgement target, responsible officer, status history (safeguarding_actions), resolution,
--     legal hold and a retention-review date. Nothing is deleted, and records are NOT written to the general audit log
--     (which executives can read); they have their own restricted logs.
--   * Escalating a DIRA Connect report creates a safeguarding record (with a copy of the reported message) and notifies the
--     acting officer. A report with reason "safety concern" goes to safeguarding automatically.
--   * Notifications and emails never contain names or details.
--   * Private-conversation oversight: no self-granting; a 'private' grant reads only REPORTED or ESCALATED conversations; the
--     acting Safeguarding Lead may read another private conversation only with a documented safeguarding record and a reason.
--     Every read is logged.
-- NOT DONE HERE (management decisions): the safeguarding records retention period; the exact "prompt action" time for urgent
--   concerns (defaults below: acknowledge urgent within 60 minutes, others within 24 hours, both editable by executives).

-- ============ 1. designated officers ============
create table safeguarding_officers (
  position text primary key check (position in ('lead', 'deputy')),
  profile_id uuid not null unique references profiles(id),
  appointed_by uuid not null references profiles(id),
  appointed_at timestamptz not null default now(),
  reason text not null check (length(btrim(reason)) >= 10),
  unavailable_until timestamptz,
  unavailable_note text check (unavailable_note is null or length(unavailable_note) <= 300),
  constraint sg_no_self_appointment check (profile_id <> appointed_by)
);

create table safeguarding_officer_history (
  id uuid primary key default gen_random_uuid(),
  position text not null,
  profile_id uuid references profiles(id),
  event text not null check (event in ('appointed', 'removed', 'unavailable', 'available')),
  actor_id uuid references profiles(id),
  reason text,
  created_at timestamptz not null default now()
);

create table safeguarding_settings (
  id boolean primary key default true check (id),
  urgent_ack_minutes int not null default 60 check (urgent_ack_minutes between 5 and 1440),
  standard_ack_hours int not null default 24 check (standard_ack_hours between 1 and 168),
  updated_by uuid references profiles(id),
  updated_at timestamptz not null default now()
);
insert into safeguarding_settings(id) values (true);

-- The signed-in person's position, if any (an inactive account holds no position).
create or replace function sg_my_position() returns text language sql stable security definer set search_path = public as $$
  select o.position from safeguarding_officers o join profiles p on p.id = o.profile_id
  where o.profile_id = auth.uid() and p.status = 'active' $$;
create or replace function is_safeguarding_officer() returns boolean language sql stable security definer set search_path = public as $$
  select sg_my_position() is not null $$;
-- Who acts as Lead right now: the Lead unless unavailable or not appointed, otherwise the Deputy.
create or replace function sg_acting_officer() returns uuid language sql stable security definer set search_path = public as $$
  select coalesce(
    (select o.profile_id from safeguarding_officers o join profiles p on p.id = o.profile_id
      where o.position = 'lead' and p.status = 'active' and (o.unavailable_until is null or o.unavailable_until <= now())),
    (select o.profile_id from safeguarding_officers o join profiles p on p.id = o.profile_id where o.position = 'deputy' and p.status = 'active')) $$;
create or replace function sg_is_acting_lead() returns boolean language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and sg_acting_officer() = auth.uid() $$;
create or replace function sg_officer_ids() returns setof uuid language sql stable security definer set search_path = public as $$
  select o.profile_id from safeguarding_officers o join profiles p on p.id = o.profile_id where p.status = 'active' $$;

-- Confidential notification: no names, no details. Email only when automatic email is approved.
create or replace function sg_notify(p_user uuid, p_title text) returns void language plpgsql security definer set search_path = public as $$
begin
  if p_user is null then return; end if;
  insert into notifications(user_id, kind, title, body) values (p_user, 'safeguarding', p_title, 'Open Safeguarding in DIRA LEARN. Details are only shown there.');
  if email_automation_enabled() then
    perform _enqueue_email(p_user, 'safeguarding_alert', jsonb_build_object('alert_title', p_title), now(), 'safeguarding', null);
  end if;
end $$;
revoke all on function sg_notify(uuid, text) from public, anon, authenticated;

insert into email_templates(key, name, subject, body, is_system) values
 ('safeguarding_alert', 'Safeguarding alert', 'DIRA LEARN: {{alert_title}}',
  E'Hello {{first_name}},\n\n{{alert_title}}.\n\nFor confidentiality this email contains no details. Please sign in to DIRA LEARN and open Safeguarding.\n\nDIRA Foundation', true)
on conflict (key) do nothing;

-- ============ 2. confidential records ============
alter table safeguarding_records drop constraint chk_safeguarding_status;
alter table safeguarding_records
  add constraint chk_safeguarding_status check (status in ('open', 'under_review', 'acknowledged', 'in_progress', 'referred', 'resolved', 'closed')),
  add column urgency text not null default 'standard' check (urgency in ('urgent', 'standard')),
  add column source text not null default 'manual' check (source in ('manual', 'raised_by_staff', 'connect_report', 'connect_safety_report')),
  add column source_report_id uuid references connect_reports(id) on delete set null,
  add column conversation_id uuid references connect_conversations(id) on delete set null,
  add column reported_message text,
  add column reported_sender uuid references profiles(id),
  add column ack_due_at timestamptz,
  add column acknowledged_at timestamptz,
  add column acknowledged_by uuid references profiles(id),
  add column responsible_officer uuid references profiles(id),
  add column resolution text check (resolution is null or length(resolution) <= 2000),
  add column resolved_at timestamptz,
  add column legal_hold boolean not null default false,
  add column legal_hold_reason text,
  add column retention_review_on date,
  add column overdue_alerted_at timestamptz;
create index idx_sg_records_status on safeguarding_records (status, created_at desc);
create index idx_sg_records_conversation on safeguarding_records (conversation_id);

create table safeguarding_actions (
  id uuid primary key default gen_random_uuid(),
  record_id uuid not null references safeguarding_records(id),
  action text not null check (action in ('created', 'acknowledged', 'status_changed', 'assigned', 'note', 'referral', 'legal_hold_on', 'legal_hold_off', 'resolved', 'conversation_read', 'exceptional_read')),
  from_status text, to_status text,
  note text check (note is null or length(note) <= 2000),
  actor_id uuid references profiles(id),
  created_at timestamptz not null default now()
);
create index idx_sg_actions_record on safeguarding_actions (record_id, created_at);

-- Exceptional, time-limited access for someone who is not an officer (for example an executive during an investigation).
create table safeguarding_access_grants (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references profiles(id),
  reason text not null check (length(btrim(reason)) >= 20),
  granted_by uuid not null references profiles(id),
  granted_at timestamptz not null default now(),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  revoked_by uuid references profiles(id),
  constraint sg_grant_not_self check (profile_id <> granted_by)
);

-- Who read what, and why (no content): officers and executives can review it.
create table safeguarding_access_log (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references profiles(id),
  record_id uuid references safeguarding_records(id),
  conversation_id uuid references connect_conversations(id) on delete set null,
  basis text not null check (basis in ('exceptional_grant', 'reported_conversation', 'escalated_conversation', 'safeguarding_concern')),
  reason text not null,
  created_at timestamptz not null default now()
);

-- Records: defaults, timestamps, and an automatic history entry for every meaningful change.
create or replace function guard_safeguarding() returns trigger language plpgsql security definer set search_path = public as $$
declare s safeguarding_settings;
begin
  select * into s from safeguarding_settings limit 1;
  if tg_op = 'INSERT' then
    new.reported_by := coalesce(auth.uid(), new.reported_by);
    new.created_at := now();
    new.status := 'open';
    new.acknowledged_at := null; new.acknowledged_by := null; new.resolved_at := null; new.overdue_alerted_at := null;
    new.ack_due_at := now() + case when new.urgency = 'urgent' then make_interval(mins => s.urgent_ack_minutes) else make_interval(hours => s.standard_ack_hours) end;
  else
    new.reported_by := old.reported_by; new.created_at := old.created_at; new.source := old.source; new.source_report_id := old.source_report_id;
    new.reported_message := old.reported_message; new.reported_sender := old.reported_sender;
    if not is_trusted_session() then new.ack_due_at := old.ack_due_at; end if;  -- only server-side corrections may move the target
    if old.status = 'open' and new.status <> 'open' and old.acknowledged_at is null then
      new.acknowledged_at := now(); new.acknowledged_by := auth.uid();
    else
      new.acknowledged_at := old.acknowledged_at; new.acknowledged_by := old.acknowledged_by;
    end if;
    if new.status in ('resolved', 'closed') and old.status not in ('resolved', 'closed') then new.resolved_at := now();
    elsif new.status not in ('resolved', 'closed') then new.resolved_at := null;
    else new.resolved_at := old.resolved_at; end if;
    if new.legal_hold and coalesce(btrim(new.legal_hold_reason), '') = '' then raise exception 'A legal hold needs a reason'; end if;
  end if;
  new.updated_at := now();
  return new;
end $$;

create or replace function log_safeguarding_change() returns trigger language plpgsql security definer set search_path = public as $$
declare actor uuid := auth.uid();
begin
  if tg_op = 'INSERT' then
    insert into safeguarding_actions(record_id, action, to_status, note, actor_id) values (new.id, 'created', new.status, null, actor);
    -- urgent: the Lead AND the Deputy at once; otherwise the acting officer
    if new.urgency = 'urgent' then
      perform sg_notify(o, 'An URGENT safeguarding concern needs your attention now') from sg_officer_ids() o;
    else
      perform sg_notify(sg_acting_officer(), 'A safeguarding concern needs acknowledgement within the target time');
    end if;
    return new;
  end if;
  if new.status is distinct from old.status then
    insert into safeguarding_actions(record_id, action, from_status, to_status, actor_id)
    values (new.id, case when old.status = 'open' and old.acknowledged_at is null then 'acknowledged'
                         when new.status in ('resolved', 'closed') then 'resolved'
                         else 'status_changed' end, old.status, new.status, actor);
  end if;
  if new.responsible_officer is distinct from old.responsible_officer then
    insert into safeguarding_actions(record_id, action, note, actor_id) values (new.id, 'assigned', null, actor);
  end if;
  if new.legal_hold is distinct from old.legal_hold then
    insert into safeguarding_actions(record_id, action, note, actor_id) values (new.id, case when new.legal_hold then 'legal_hold_on' else 'legal_hold_off' end, new.legal_hold_reason, actor);
  end if;
  return new;
end $$;
create trigger trg_log_safeguarding after insert or update on safeguarding_records for each row execute function log_safeguarding_change();

create or replace function block_safeguarding_delete() returns trigger language plpgsql as $$
begin raise exception 'Safeguarding records and their history cannot be deleted'; end $$;
create trigger trg_safeguarding_no_delete before delete on safeguarding_records for each row execute function block_safeguarding_delete();
create trigger trg_sg_actions_no_delete before update or delete on safeguarding_actions for each row execute function block_safeguarding_delete();
create trigger trg_sg_access_log_no_change before update or delete on safeguarding_access_log for each row execute function block_safeguarding_delete();
create trigger trg_sg_history_no_change before update or delete on safeguarding_officer_history for each row execute function block_safeguarding_delete();

create or replace function guard_safeguarding_action() returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.actor_id := coalesce(auth.uid(), new.actor_id);
  new.created_at := now();
  return new;
end $$;
create trigger trg_guard_sg_action before insert on safeguarding_actions for each row execute function guard_safeguarding_action();

-- ============ 3. row level security: officers only ============
drop policy if exists safe_admin_read on safeguarding_records;
drop policy if exists safe_admin_insert on safeguarding_records;
drop policy if exists safe_admin_update on safeguarding_records;
create policy sg_officer_read on safeguarding_records for select to authenticated using (is_safeguarding_officer());
create policy sg_officer_insert on safeguarding_records for insert to authenticated with check (is_safeguarding_officer());
create policy sg_officer_update on safeguarding_records for update to authenticated using (is_safeguarding_officer()) with check (is_safeguarding_officer());

alter table safeguarding_officers enable row level security;
alter table safeguarding_officer_history enable row level security;
alter table safeguarding_settings enable row level security;
alter table safeguarding_actions enable row level security;
alter table safeguarding_access_grants enable row level security;
alter table safeguarding_access_log enable row level security;
-- Who holds the positions is not secret inside the organisation: staff and executives can see it.
create policy sgo_read on safeguarding_officers for select to authenticated using (is_staff());
create policy sgoh_read on safeguarding_officer_history for select to authenticated using (is_executive() or is_safeguarding_officer());
create policy sgs_read on safeguarding_settings for select to authenticated using (is_staff() or is_safeguarding_officer());
create policy sgs_update on safeguarding_settings for update to authenticated using (is_executive()) with check (is_executive());
create policy sga_read on safeguarding_actions for select to authenticated using (is_safeguarding_officer());
create policy sga_insert on safeguarding_actions for insert to authenticated with check (is_safeguarding_officer() and action in ('note', 'referral')
  and exists (select 1 from safeguarding_records r where r.id = record_id));
create policy sgg_read on safeguarding_access_grants for select to authenticated using (is_safeguarding_officer() or is_executive() or profile_id = auth.uid());
create policy sgl_read on safeguarding_access_log for select to authenticated using (is_safeguarding_officer() or is_executive());
-- officers, grants and logs change only through the functions below (no insert/update/delete policies).
create trigger aud_safeguarding_settings after update on safeguarding_settings for each row execute function audit_row();

-- ============ 4. functions: officers ============
create or replace function sg_appoint(p_position text, p_profile uuid, p_reason text) returns void language plpgsql security definer set search_path = public as $$
declare r role_code; st account_status; prev uuid; pending int;
begin
  if not is_executive() then raise exception 'Only a super administrator, Founder or Co-Founder can appoint safeguarding officers'; end if;
  if p_position not in ('lead', 'deputy') then raise exception 'Choose Lead or Deputy'; end if;
  if p_profile = auth.uid() then raise exception 'You cannot appoint yourself. Another executive must make this appointment'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'Write a reason of at least 10 characters'; end if;
  select role, status into r, st from profiles where id = p_profile;
  if r is null or st <> 'active' or r not in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator') then
    raise exception 'Safeguarding officers must be active executives or programme staff';
  end if;
  if exists (select 1 from safeguarding_officers where profile_id = p_profile and position <> p_position) then
    raise exception 'The Lead and the Deputy must be different people';
  end if;
  select profile_id into prev from safeguarding_officers where position = p_position;
  if prev is not null then
    insert into safeguarding_officer_history(position, profile_id, event, actor_id, reason) values (p_position, prev, 'removed', auth.uid(), 'Replaced: ' || btrim(p_reason));
    delete from safeguarding_officers where position = p_position;
  end if;
  insert into safeguarding_officers(position, profile_id, appointed_by, reason) values (p_position, p_profile, auth.uid(), btrim(p_reason));
  insert into safeguarding_officer_history(position, profile_id, event, actor_id, reason) values (p_position, p_profile, 'appointed', auth.uid(), btrim(p_reason));
  perform sg_notify(p_profile, case p_position when 'lead' then 'You have been appointed Safeguarding Lead' else 'You have been appointed Safeguarding Deputy' end);
  select count(*) into pending from safeguarding_records where status = 'open';
  if pending > 0 then perform sg_notify(p_profile, 'Safeguarding concerns are waiting for acknowledgement'); end if;
end $$;

create or replace function sg_remove_officer(p_position text, p_reason text) returns void language plpgsql security definer set search_path = public as $$
declare prev uuid;
begin
  if not is_executive() then raise exception 'Only a super administrator, Founder or Co-Founder can remove safeguarding officers'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'Write a reason of at least 10 characters'; end if;
  select profile_id into prev from safeguarding_officers where position = p_position;
  if prev is null then raise exception 'Nobody holds that position'; end if;
  delete from safeguarding_officers where position = p_position;
  insert into safeguarding_officer_history(position, profile_id, event, actor_id, reason) values (p_position, prev, 'removed', auth.uid(), btrim(p_reason));
end $$;

-- The Lead (or an executive on the Lead's behalf) marks the Lead unavailable; the Deputy then acts and is told.
create or replace function sg_set_unavailable(p_until timestamptz, p_note text default null) returns void language plpgsql security definer set search_path = public as $$
declare lead uuid; dep uuid;
begin
  select profile_id into lead from safeguarding_officers where position = 'lead';
  if lead is null then raise exception 'No Safeguarding Lead is appointed'; end if;
  if not (auth.uid() = lead or is_executive()) then raise exception 'Only the Safeguarding Lead or an executive can change the Lead''s availability'; end if;
  if p_until is not null and p_until <= now() then raise exception 'Choose a future time, or clear it to mark the Lead available'; end if;
  update safeguarding_officers set unavailable_until = p_until, unavailable_note = nullif(btrim(coalesce(p_note, '')), '') where position = 'lead';
  insert into safeguarding_officer_history(position, profile_id, event, actor_id, reason)
  values ('lead', lead, case when p_until is null then 'available' else 'unavailable' end, auth.uid(), nullif(btrim(coalesce(p_note, '')), ''));
  select profile_id into dep from safeguarding_officers where position = 'deputy';
  if p_until is not null then perform sg_notify(dep, 'You are acting Safeguarding Lead while the Lead is unavailable'); end if;
end $$;

create or replace function sg_officers()
returns table(officer_position text, profile_id uuid, display_name text, appointed_at timestamptz, unavailable_until timestamptz, acting boolean)
language sql stable security definer set search_path = public as $$
  select o.position, o.profile_id, btrim(p.first_name || ' ' || p.last_name), o.appointed_at, o.unavailable_until, o.profile_id = sg_acting_officer()
  from safeguarding_officers o join profiles p on p.id = o.profile_id
  where is_staff() or is_safeguarding_officer() order by o.position desc $$;

-- Executives see THAT escalations are waiting with nobody appointed, never what they are.
create or replace function sg_waiting_without_officer() returns int language sql stable security definer set search_path = public as $$
  select case when is_executive() and sg_acting_officer() is null then (select count(*)::int from safeguarding_records where status = 'open') else 0 end $$;

-- ============ 5. functions: concerns and records ============
-- Any staff member, facilitator or mentor can raise a concern. They cannot read it back afterwards.
create or replace function sg_raise_concern(p_participant uuid, p_summary text, p_urgency text default 'standard') returns void language plpgsql security definer set search_path = public as $$
begin
  if coalesce(app_role()::text, '') not in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator', 'trainer', 'mentor', 'me_officer') then
    raise exception 'Only DIRA staff, facilitators and mentors can raise a safeguarding concern here. Learners can use Report or message the safeguarding team';
  end if;
  if p_summary is null or length(btrim(p_summary)) < 20 then raise exception 'Describe the concern factually in at least 20 characters'; end if;
  if p_urgency not in ('urgent', 'standard') then raise exception 'Choose urgent or standard'; end if;
  insert into safeguarding_records(participant_id, summary, urgency, source) values (p_participant, btrim(p_summary), p_urgency, 'raised_by_staff');
end $$;

-- Exceptional access for a non-officer: granted by an officer or by a DIFFERENT executive, at most 7 days, never to oneself.
create or replace function sg_grant_exceptional_access(p_profile uuid, p_days int, p_reason text) returns void language plpgsql security definer set search_path = public as $$
begin
  if not (is_safeguarding_officer() or is_executive()) then raise exception 'Only a safeguarding officer or an executive can grant exceptional access'; end if;
  if p_profile = auth.uid() then raise exception 'You cannot grant access to yourself'; end if;
  if p_days not between 1 and 7 then raise exception 'Exceptional access lasts between 1 and 7 days'; end if;
  if p_reason is null or length(btrim(p_reason)) < 20 then raise exception 'Write a reason of at least 20 characters'; end if;
  if not exists (select 1 from profiles where id = p_profile and status = 'active' and role in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator')) then
    raise exception 'Exceptional access can only be given to active executives or programme staff';
  end if;
  insert into safeguarding_access_grants(profile_id, reason, granted_by, expires_at) values (p_profile, btrim(p_reason), auth.uid(), now() + make_interval(days => p_days));
  perform sg_notify(sg_acting_officer(), 'Exceptional access to safeguarding records was granted');
end $$;

create or replace function sg_revoke_exceptional_access(p_grant uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if not (is_safeguarding_officer() or is_executive()) then raise exception 'Only a safeguarding officer or an executive can revoke access'; end if;
  update safeguarding_access_grants set revoked_at = now(), revoked_by = auth.uid() where id = p_grant and revoked_at is null;
end $$;

-- An exceptional reader sees one record and its history, with a written reason, logged, and the acting officer is told.
create or replace function sg_exceptional_read(p_record uuid, p_reason text)
returns table(id uuid, created_at timestamptz, urgency text, status text, summary text, reported_message text, resolution text, history jsonb)
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from safeguarding_access_grants g where g.profile_id = auth.uid() and g.revoked_at is null and g.expires_at > now()) then
    raise exception 'You do not have exceptional access to safeguarding records';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'A written reason of at least 10 characters is required'; end if;
  if not exists (select 1 from safeguarding_records r where r.id = p_record) then raise exception 'Record not found'; end if;
  insert into safeguarding_access_log(profile_id, record_id, basis, reason) values (auth.uid(), p_record, 'exceptional_grant', btrim(p_reason));
  insert into safeguarding_actions(record_id, action, note, actor_id) values (p_record, 'exceptional_read', btrim(p_reason), auth.uid());
  perform sg_notify(sg_acting_officer(), 'A safeguarding record was opened under exceptional access');
  return query select r.id, r.created_at, r.urgency, r.status, r.summary, r.reported_message, r.resolution,
    coalesce((select jsonb_agg(jsonb_build_object('action', a.action, 'at', a.created_at, 'note', a.note) order by a.created_at) from safeguarding_actions a where a.record_id = r.id), '[]'::jsonb)
    from safeguarding_records r where r.id = p_record;
end $$;
-- Record ids an exceptional reader may choose from (dates and urgency only).
create or replace function sg_exceptional_index() returns table(id uuid, created_at timestamptz, urgency text, status text) language sql stable security definer set search_path = public as $$
  select r.id, r.created_at, r.urgency, r.status from safeguarding_records r
  where exists (select 1 from safeguarding_access_grants g where g.profile_id = auth.uid() and g.revoked_at is null and g.expires_at > now())
  order by r.created_at desc limit 200 $$;

-- Reminder job (send-emails schedule): unacknowledged concerns past their target alert BOTH officers, once.
create or replace function sg_overdue_check() returns int language plpgsql security definer set search_path = public as $$
declare r record; n int := 0;
begin
  for r in select id from safeguarding_records where status = 'open' and acknowledged_at is null and ack_due_at < now() and overdue_alerted_at is null loop
    perform sg_notify(o, 'A safeguarding concern has passed its acknowledgement target') from sg_officer_ids() o;
    update safeguarding_records set overdue_alerted_at = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;

-- ============ 6. DIRA Connect: escalation and oversight ============
-- Escalation creates a confidential record; the moderator chooses the urgency. Other actions are unchanged.
drop function if exists connect_handle_report(uuid, text, text);
create or replace function connect_handle_report(p_report uuid, p_action text, p_note text default null, p_urgency text default 'standard') returns void
language plpgsql security definer set search_path = public as $$
declare r connect_reports; c connect_conversations; learner uuid;
begin
  if not connect_is_moderator() then raise exception 'Only moderators can handle reports'; end if;
  if p_action not in ('dismiss', 'hide', 'escalate') then raise exception 'Unknown action'; end if;
  select * into r from connect_reports where id = p_report;
  if not found then raise exception 'Report not found'; end if;
  if p_action = 'hide' then
    insert into connect_hidden_originals(message_id, body, hidden_by) select m.id, m.body, auth.uid() from connect_messages m where m.id = r.message_id and m.hidden_at is null on conflict do nothing;
    update connect_messages set body = 'This message was removed by a moderator.', hidden_at = now(), hidden_by = auth.uid(), hide_reason = nullif(btrim(coalesce(p_note, '')), '') where id = r.message_id and hidden_at is null;
  end if;
  if p_action = 'escalate' then
    if r.status = 'escalated' then raise exception 'This report is already with safeguarding'; end if;
    if p_urgency not in ('urgent', 'standard') then raise exception 'Choose urgent or standard'; end if;
    perform sg_escalate_report(r.id, p_urgency, coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Escalated from a DIRA Connect report'), 'connect_report');
    return;
  end if;
  if r.status = 'escalated' then
    if p_action = 'dismiss' then raise exception 'An escalated report is handled by safeguarding and cannot be dismissed'; end if;
    return;  -- hiding an escalated message keeps the report with safeguarding
  end if;
  update connect_reports set status = case p_action when 'dismiss' then 'dismissed' else 'hidden' end,
         handled_by = auth.uid(), handled_at = now(), handler_note = nullif(btrim(coalesce(p_note, '')), '') where id = p_report;
end $$;

-- Shared by moderator escalation and automatic safety-concern routing. Not callable from the app.
create or replace function sg_escalate_report(p_report uuid, p_urgency text, p_summary text, p_source text) returns uuid language plpgsql security definer set search_path = public as $$
declare r connect_reports; c connect_conversations; learner uuid; rid uuid;
begin
  select * into r from connect_reports where id = p_report;
  select * into c from connect_conversations where id = r.conversation_id;
  learner := coalesce(c.learner_id, (select p.id from participants p where p.profile_id = r.snapshot_sender));
  insert into safeguarding_records(participant_id, summary, urgency, source, source_report_id, conversation_id, reported_message, reported_sender)
  values (learner, left(p_summary, 2000), p_urgency, p_source, r.id, r.conversation_id, r.snapshot_body, r.snapshot_sender) returning id into rid;
  update connect_reports set status = 'escalated', handled_by = auth.uid(), handled_at = now(), handler_note = left(p_summary, 500) where id = p_report;
  return rid;
end $$;
revoke all on function sg_escalate_report(uuid, text, text, text) from public, anon, authenticated;

-- A "safety concern" report goes straight to safeguarding (moderators still see that it was escalated).
create or replace function route_safety_report() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.reason = 'safety_concern' then
    perform sg_escalate_report(new.id, 'standard', 'A learner or facilitator reported a message as a safety concern' ||
      coalesce(': ' || new.note, ''), 'connect_safety_report');
  end if;
  return new;
end $$;
create trigger trg_route_safety_report after insert on connect_reports for each row execute function route_safety_report();

-- No self-granting of any oversight permission: a DIFFERENT executive must grant it.
create or replace function guard_connect_oversight() returns trigger language plpgsql security definer set search_path = public as $$
declare r role_code;
begin
  select role into r from profiles where id = new.profile_id;
  if r is null or r not in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator') then
    raise exception 'Oversight can only be granted to executives and programme staff';
  end if;
  if not is_trusted_session() and new.profile_id = auth.uid() then
    raise exception 'You cannot grant oversight to yourself. Another executive must approve it';
  end if;
  new.granted_by := coalesce(auth.uid(), new.granted_by);
  new.granted_at := now();
  return new;
end $$;

alter table connect_oversight_log
  add column basis text not null default 'reported_conversation' check (basis in ('reported_conversation', 'escalated_conversation', 'safeguarding_concern')),
  add column safeguarding_record_id uuid references safeguarding_records(id);

-- The ONLY way anyone outside a private conversation reads it.
--   * holders of the 'private' grant, and safeguarding officers: only conversations that were REPORTED or ESCALATED;
--   * the ACTING Safeguarding Lead: any private conversation, but only by naming a safeguarding record and giving a reason.
-- Every read is logged (and, for a record, added to its history). Hidden messages are shown with their original text.
drop function if exists connect_oversight_read(uuid, text);
create or replace function connect_oversight_read(p_conversation uuid, p_reason text, p_safeguarding_record uuid default null)
returns table(id uuid, sender_name text, body text, created_at timestamptz, hidden boolean)
language plpgsql security definer set search_path = public as $$
declare has_grant boolean; officer boolean; reported boolean; escalated boolean; b text;
begin
  has_grant := exists (select 1 from connect_oversight o where o.profile_id = auth.uid() and o.scope = 'private');
  officer := is_safeguarding_officer();
  if not (has_grant or officer) then raise exception 'You have not been granted private conversation oversight'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'A written reason of at least 10 characters is required'; end if;
  if not exists (select 1 from connect_conversations c where c.id = p_conversation and c.kind = 'direct') then raise exception 'Not a private conversation'; end if;
  escalated := exists (select 1 from connect_reports r where r.conversation_id = p_conversation and r.status = 'escalated')
            or exists (select 1 from safeguarding_records s where s.conversation_id = p_conversation);
  reported := exists (select 1 from connect_reports r where r.conversation_id = p_conversation);
  if p_safeguarding_record is not null then
    if not sg_is_acting_lead() then raise exception 'Only the acting Safeguarding Lead can open a conversation for a safeguarding record'; end if;
    if not exists (select 1 from safeguarding_records s where s.id = p_safeguarding_record and s.status not in ('resolved', 'closed')) then
      raise exception 'Name an open safeguarding record';
    end if;
    b := 'safeguarding_concern';
  elsif escalated then b := 'escalated_conversation';
  elsif reported then b := 'reported_conversation';
  else raise exception 'This conversation has not been reported or escalated. The acting Safeguarding Lead can open it only for a documented safeguarding record';
  end if;
  insert into connect_oversight_log(profile_id, conversation_id, reason, basis, safeguarding_record_id) values (auth.uid(), p_conversation, btrim(p_reason), b, p_safeguarding_record);
  if officer then
    insert into safeguarding_access_log(profile_id, record_id, conversation_id, basis, reason) values (auth.uid(), p_safeguarding_record, p_conversation, b, btrim(p_reason));
  end if;
  if p_safeguarding_record is not null then
    insert into safeguarding_actions(record_id, action, note, actor_id) values (p_safeguarding_record, 'conversation_read', btrim(p_reason), auth.uid());
  end if;
  return query select m.id, btrim(pr.first_name || ' ' || pr.last_name), coalesce(h.body, m.body), m.created_at, (m.hidden_at is not null)
    from connect_messages m join profiles pr on pr.id = m.sender_id left join connect_hidden_originals h on h.message_id = m.id
    where m.conversation_id = p_conversation order by m.created_at desc limit 200;
end $$;

-- ============ 7. grants ============
revoke all on function sg_my_position(), is_safeguarding_officer(), sg_acting_officer(), sg_is_acting_lead(), sg_officer_ids(),
  sg_appoint(text, uuid, text), sg_remove_officer(text, text), sg_set_unavailable(timestamptz, text), sg_officers(), sg_waiting_without_officer(),
  sg_raise_concern(uuid, text, text), sg_grant_exceptional_access(uuid, int, text), sg_revoke_exceptional_access(uuid),
  sg_exceptional_read(uuid, text), sg_exceptional_index(), sg_overdue_check(),
  connect_handle_report(uuid, text, text, text), connect_oversight_read(uuid, text, uuid) from public, anon;
grant execute on function sg_my_position(), is_safeguarding_officer(), sg_is_acting_lead(),
  sg_appoint(text, uuid, text), sg_remove_officer(text, text), sg_set_unavailable(timestamptz, text), sg_officers(), sg_waiting_without_officer(),
  sg_raise_concern(uuid, text, text), sg_grant_exceptional_access(uuid, int, text), sg_revoke_exceptional_access(uuid),
  sg_exceptional_read(uuid, text), sg_exceptional_index(),
  connect_handle_report(uuid, text, text, text), connect_oversight_read(uuid, text, uuid) to authenticated;
revoke execute on function sg_overdue_check(), sg_acting_officer(), sg_officer_ids() from authenticated;
grant execute on function sg_overdue_check() to service_role;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000024', 'safeguarding_officers');
commit;

\echo '== migration 20260101000025 connect_phase4_completion'
begin;
-- DIRA LEARN: Phase 4 completion, part 2 – DIRA Connect messaging changes (management decisions of 19 Nov 2026).
-- STATUS: executed and tested locally (PostgreSQL 16 + Supabase stand-in). NOT applied to any Supabase project.
-- Rollback: supabase/rollback/20260101000025_connect_phase4_completion_down.sql
--
-- WHAT IT DOES
--   * Facilitators (trainers formally assigned to the learner's cohort) may START private conversations with those learners.
--   * Closed learning access (scheduled, expired, suspended, withdrawn) no longer cuts a learner off from SUPPORT: they keep
--     their private conversations with their assigned facilitators and can message the safeguarding team. Cohort discussions
--     and learning materials stay closed. Cohort discussions now follow the access of THAT cohort.
--   * Safeguarding-team conversations: a learner can message the designated safeguarding officers privately. Only the learner
--     and the current Lead and Deputy can read them; no oversight grant, moderator or executive can. They are never purged.
--   * Attachments: PDF, Word, Excel, PowerPoint, JPG and PNG, up to 10 MB, at most 3 per message, in a private bucket.
--     Access follows the conversation. Files are NOT virus-scanned (Supabase has no built-in scanner): the screen says so,
--     and a file marked "infected" by a future scanner is blocked. Links in messages are shown safely by the screens.
--   * Retention: ordinary messages are deleted 12 months after the learner's (or the cohort's) last cohort end date, but only
--     when an executive switches retention ON (it is OFF after this migration). Never deleted: safeguarding-team
--     conversations, conversations with any report, conversations linked to a safeguarding record (or of a learner with one),
--     and anything under a legal hold.

-- ============ 1. conversation kinds ============
alter table connect_conversations drop constraint connect_conv_shape;
alter table connect_conversations drop constraint if exists connect_conversations_kind_check;
alter table connect_conversations add constraint connect_conversations_kind_check check (kind in ('direct', 'cohort', 'safeguarding'));
alter table connect_conversations add constraint connect_conv_shape check (
  (kind = 'cohort' and cohort_id is not null and learner_id is null and facilitator_id is null) or
  (kind = 'direct' and learner_id is not null and facilitator_id is not null and cohort_id is null) or
  (kind = 'safeguarding' and learner_id is not null and facilitator_id is null and cohort_id is null));
alter table connect_conversations add column started_by uuid references profiles(id);
create unique index uq_connect_safeguarding on connect_conversations (learner_id) where kind = 'safeguarding';

-- ============ 2. access rules ============
create or replace function connect_is_member(p_conv uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case c.kind
      when 'direct' then
        (c.learner_id = my_participant_id() and app_role() = 'participant')
        or (c.facilitator_id = auth.uid() and app_role() = 'trainer' and connect_facilitator_assigned(c.learner_id, c.facilitator_id))
      when 'safeguarding' then
        (c.learner_id = my_participant_id() and app_role() = 'participant') or is_safeguarding_officer()
      else
        (app_role() = 'trainer' and c.cohort_id in (select my_trainer_cohorts()))
        or (app_role() = 'participant' and exists (select 1 from cohort_enrolments e where e.cohort_id = c.cohort_id and e.participant_id = my_participant_id()))
    end
    from connect_conversations c where c.id = p_conv), false) $$;

-- Learners read a cohort discussion only while THEIR access to that cohort is Active; private and safeguarding conversations stay open.
create or replace function connect_can_see(p_conv uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select case
      when connect_is_member(p_conv) then
        c.kind <> 'cohort' or app_role() <> 'participant' or learner_access_state(my_participant_id(), c.cohort_id) = 'active'
      else c.kind = 'cohort' and connect_is_discussion_overseer()
    end
    from connect_conversations c where c.id = p_conv), false) $$;

create or replace function connect_can_post(p_conv uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((
    select not c.locked and connect_is_member(p_conv) and case c.kind
      when 'cohort' then app_role() in ('participant', 'trainer')
        and (app_role() <> 'participant' or learner_access_state(my_participant_id(), c.cohort_id) = 'active')
        and not exists (select 1 from connect_mutes m where m.profile_id = auth.uid() and m.until > now())
      when 'direct' then app_role() in ('participant', 'trainer')
      else true end
    from connect_conversations c where c.id = p_conv), false) $$;

-- ============ 3. starting conversations ============
create or replace function connect_my_facilitators() returns table(profile_id uuid, display_name text) language sql stable security definer set search_path = public as $$
  select distinct p.id, btrim(p.first_name || ' ' || p.last_name)
  from cohort_enrolments e join trainer_assignments ta on ta.cohort_id = e.cohort_id join profiles p on p.id = ta.trainer_id
  where app_role() = 'participant' and e.participant_id = my_participant_id() and p.role = 'trainer' and p.status = 'active' $$;

create or replace function connect_start_direct(p_facilitator uuid) returns uuid language plpgsql security definer set search_path = public as $$
declare me uuid := my_participant_id(); cid uuid;
begin
  if app_role() is distinct from 'participant' or me is null then raise exception 'Only learners can start a private conversation with a facilitator'; end if;
  if not exists (select 1 from profiles where id = p_facilitator and role = 'trainer' and status = 'active') or not connect_facilitator_assigned(me, p_facilitator) then
    raise exception 'You can only message a facilitator assigned to your cohort';
  end if;
  insert into connect_conversations(kind, learner_id, facilitator_id, started_by) values ('direct', me, p_facilitator, auth.uid())
  on conflict (learner_id, facilitator_id) where kind = 'direct' do nothing;
  select id into cid from connect_conversations where kind = 'direct' and learner_id = me and facilitator_id = p_facilitator;
  return cid;
end $$;

-- Learners a facilitator may message: those enrolled in a cohort the facilitator is assigned to.
create or replace function connect_my_learners() returns table(participant_id uuid, display_name text, cohort_names text) language sql stable security definer set search_path = public as $$
  select pa.id, btrim(p.first_name || ' ' || p.last_name), string_agg(distinct co.name, ', ')
  from trainer_assignments ta join cohort_enrolments e on e.cohort_id = ta.cohort_id join cohorts co on co.id = e.cohort_id
  join participants pa on pa.id = e.participant_id join profiles p on p.id = pa.profile_id
  where app_role() = 'trainer' and ta.trainer_id = auth.uid() and p.status = 'active'
  group by pa.id, p.first_name, p.last_name order by 2 $$;

create or replace function connect_start_direct_with_learner(p_learner uuid) returns uuid language plpgsql security definer set search_path = public as $$
declare cid uuid;
begin
  if app_role() is distinct from 'trainer' then raise exception 'Only facilitators can start a conversation with a learner'; end if;
  if not exists (select 1 from participants pa join profiles p on p.id = pa.profile_id where pa.id = p_learner and p.status = 'active')
     or not connect_facilitator_assigned(p_learner, auth.uid()) then
    raise exception 'You can only message learners in a cohort you are assigned to';
  end if;
  insert into connect_conversations(kind, learner_id, facilitator_id, started_by) values ('direct', p_learner, auth.uid(), auth.uid())
  on conflict (learner_id, facilitator_id) where kind = 'direct' do nothing;
  select id into cid from connect_conversations where kind = 'direct' and learner_id = p_learner and facilitator_id = auth.uid();
  return cid;
end $$;

-- What support a learner can reach (shown on the Connect page).
create or replace function connect_my_support() returns table(safeguarding_available boolean, learning_access_open boolean) language sql stable security definer set search_path = public as $$
  select sg_acting_officer() is not null, participant_access_active() where app_role() = 'participant' $$;

create or replace function connect_start_safeguarding() returns uuid language plpgsql security definer set search_path = public as $$
declare me uuid := my_participant_id(); cid uuid;
begin
  if app_role() is distinct from 'participant' or me is null then raise exception 'Only learners can start a conversation with the safeguarding team'; end if;
  if sg_acting_officer() is null then
    raise exception 'The safeguarding team has not been set up yet. Please speak to your facilitator or contact DIRA Foundation directly';
  end if;
  insert into connect_conversations(kind, learner_id, started_by) values ('safeguarding', me, auth.uid())
  on conflict (learner_id) where kind = 'safeguarding' do nothing;
  select id into cid from connect_conversations where kind = 'safeguarding' and learner_id = me;
  return cid;
end $$;

-- ============ 4. thread list and messages ============
create or replace function connect_threads()
returns table(conversation_id uuid, kind text, title text, subtitle text, last_message_at timestamptz, unread bigint, locked boolean)
language sql stable security definer set search_path = public as $$
  select c.id, c.kind,
         case c.kind
           when 'cohort' then (select name from cohorts where id = c.cohort_id)
           when 'safeguarding' then case when c.learner_id = my_participant_id() then 'Safeguarding team'
                                     else (select btrim(first_name || ' ' || last_name) from profiles where id = (select profile_id from participants where id = c.learner_id)) end
           else case when c.facilitator_id = auth.uid() then (select btrim(first_name || ' ' || last_name) from profiles where id = (select profile_id from participants where id = c.learner_id))
                     else (select btrim(first_name || ' ' || last_name) from profiles where id = c.facilitator_id) end end,
         case c.kind when 'cohort' then 'Cohort discussion' when 'safeguarding' then 'Safeguarding (confidential)' else 'Private conversation' end,
         c.last_message_at,
         (select count(*) from connect_messages m where m.conversation_id = c.id and m.sender_id <> auth.uid() and m.hidden_at is null
            and m.created_at > coalesce((select r.last_read_at from connect_reads r where r.conversation_id = c.id and r.profile_id = auth.uid()), '-infinity'::timestamptz)),
         c.locked
  from connect_conversations c where connect_can_see(c.id)
  order by c.last_message_at desc nulls last, c.created_at desc $$;

drop function if exists connect_thread_messages(uuid, timestamptz, int);
create or replace function connect_thread_messages(p_conversation uuid, p_before timestamptz default null, p_limit int default 50)
returns table(id uuid, sender_id uuid, sender_name text, sender_role text, body text, created_at timestamptz, hidden boolean, mine boolean, attachments jsonb)
language plpgsql stable security definer set search_path = public as $$
declare learner_profile uuid; k text;
begin
  if not connect_can_see(p_conversation) then return; end if;
  select c.kind, pa.profile_id into k, learner_profile from connect_conversations c left join participants pa on pa.id = c.learner_id where c.id = p_conversation;
  return query
    select m.id, m.sender_id,
           case when pr.role = 'trainer' or (k = 'safeguarding' and m.sender_id is distinct from learner_profile) then btrim(pr.first_name || ' ' || pr.last_name)
                else btrim(pr.first_name || ' ' || left(coalesce(pr.last_name, ''), 1) || '.') end,
           case when k = 'safeguarding' and m.sender_id is distinct from learner_profile then 'Safeguarding team'
                when pr.role = 'trainer' then 'Facilitator' else 'Learner' end,
           m.body, m.created_at, (m.hidden_at is not null), (m.sender_id = auth.uid()),
           case when m.hidden_at is not null then '[]'::jsonb else coalesce((
             select jsonb_agg(jsonb_build_object('id', a.id, 'name', a.file_name, 'path', a.storage_path, 'mime', a.mime_type, 'size', a.size_bytes, 'scan', a.scan_status) order by a.created_at)
             from connect_attachments a where a.message_id = m.id and a.scan_status <> 'infected'), '[]'::jsonb) end
    from connect_messages m join profiles pr on pr.id = m.sender_id
    where m.conversation_id = p_conversation and (p_before is null or m.created_at < p_before)
    order by m.created_at desc, m.id desc limit least(greatest(p_limit, 1), 100);
end $$;

-- Notifications: one per burst; safeguarding messages from a learner alert the acting officer (no details anywhere).
create or replace function after_connect_message() returns trigger language plpgsql security definer set search_path = public as $$
declare c connect_conversations; recipient uuid; learner_profile uuid; last_seen timestamptz;
begin
  update connect_conversations set last_message_at = new.created_at where id = new.conversation_id;
  select * into c from connect_conversations where id = new.conversation_id;
  if c.kind = 'cohort' then return new; end if;
  select profile_id into learner_profile from participants where id = c.learner_id;
  if c.kind = 'direct' then
    recipient := case when new.sender_id = c.facilitator_id then learner_profile else c.facilitator_id end;
  else
    recipient := case when new.sender_id = learner_profile then sg_acting_officer() else learner_profile end;
  end if;
  if recipient is null then return new; end if;
  select last_read_at into last_seen from connect_reads where conversation_id = c.id and profile_id = recipient;
  if exists (select 1 from connect_messages m where m.conversation_id = c.id and m.sender_id = new.sender_id and m.id <> new.id
             and m.created_at > coalesce(last_seen, '-infinity'::timestamptz)) then
    return new;
  end if;
  if c.kind = 'safeguarding' and new.sender_id = learner_profile then
    perform sg_notify(recipient, 'A learner has sent a message to the safeguarding team');
  elsif c.kind = 'safeguarding' then
    insert into notifications(user_id, kind, title, body) values (recipient, 'message', 'New message from the safeguarding team', 'Open DIRA Connect to read it.');
  else
    insert into notifications(user_id, kind, title, body) values (recipient, 'message', 'New private message', 'You have a new message in DIRA Connect.');
  end if;
  return new;
end $$;

-- Safeguarding-team conversations are not reported to moderators (that would show them to people outside the team).
create or replace function connect_report_message(p_message uuid, p_reason text, p_note text default null) returns void language plpgsql security definer set search_path = public as $$
declare m connect_messages; files text;
begin
  select * into m from connect_messages where id = p_message;
  if not found or not connect_is_member(m.conversation_id) or not connect_can_see(m.conversation_id) then raise exception 'You can only report messages in your own conversations'; end if;
  if (select kind from connect_conversations where id = m.conversation_id) = 'safeguarding' then
    raise exception 'Safeguarding conversations cannot be reported to moderators. Please contact DIRA Foundation directly about any concern';
  end if;
  if m.sender_id = auth.uid() then raise exception 'You cannot report your own message'; end if;
  select string_agg(a.file_name, ', ') into files from connect_attachments a where a.message_id = m.id;
  insert into connect_reports(message_id, conversation_id, reporter_id, reason, note, snapshot_body, snapshot_sender)
  values (m.id, m.conversation_id, auth.uid(), p_reason, nullif(btrim(coalesce(p_note, '')), ''), m.body || coalesce(E'\n[Attachments: ' || files || ']', ''), m.sender_id)
  on conflict (message_id, reporter_id) do nothing;
end $$;

-- ============ 5. attachments ============
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('connect-attachments', 'connect-attachments', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png',
   'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
   'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
   'application/vnd.openxmlformats-officedocument.presentationml.presentation'])
on conflict (id) do nothing;

create table connect_attachments (
  id uuid primary key default gen_random_uuid(),
  message_id uuid not null references connect_messages(id) on delete cascade,
  conversation_id uuid not null references connect_conversations(id) on delete cascade,
  storage_path text not null unique,
  file_name text not null check (length(file_name) between 1 and 200),
  mime_type text not null,
  size_bytes bigint not null check (size_bytes between 1 and 10485760),
  scan_status text not null default 'not_scanned' check (scan_status in ('not_scanned', 'pending', 'clean', 'infected')),
  uploaded_by uuid not null references profiles(id),
  created_at timestamptz not null default now()
);
create index idx_connect_attach_msg on connect_attachments (message_id);

create or replace function connect_allowed_mime(p text) returns boolean language sql immutable as $$
  select p in ('application/pdf', 'image/jpeg', 'image/png', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
               'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.openxmlformats-officedocument.presentationml.presentation') $$;

-- Path rule: <conversation id>/<uploader id>/<file>. The uploader must be allowed to post there.
create or replace function connect_attachment_upload_ok(p_name text) returns boolean language plpgsql stable security definer set search_path = public as $$
declare parts text[] := string_to_array(p_name, '/'); conv uuid;
begin
  if array_length(parts, 1) <> 3 or parts[2] is distinct from auth.uid()::text then return false; end if;
  begin conv := parts[1]::uuid; exception when others then return false; end;
  return connect_can_post(conv);
end $$;
-- Download rule: the file belongs to a visible, not hidden, not infected message, or the reader opened this conversation
-- through logged oversight in the last hour.
create or replace function connect_attachment_read_ok(p_name text) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from connect_attachments a join connect_messages m on m.id = a.message_id
                 where a.storage_path = p_name and a.scan_status <> 'infected'
                   and ((m.hidden_at is null and connect_can_see(a.conversation_id))
                        or exists (select 1 from connect_oversight_log l where l.profile_id = auth.uid() and l.conversation_id = a.conversation_id
                                   and l.created_at > now() - interval '1 hour'))) $$;
revoke all on function connect_attachment_upload_ok(text), connect_attachment_read_ok(text) from public, anon;
grant execute on function connect_attachment_upload_ok(text), connect_attachment_read_ok(text) to authenticated;

create policy connect_attach_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'connect-attachments' and connect_attachment_upload_ok(name));
create policy connect_attach_read on storage.objects for select to authenticated
  using (bucket_id = 'connect-attachments' and connect_attachment_read_ok(name));

-- The attachment row is checked against the stored file: size and type are taken from what Storage recorded for the upload,
-- not from the attachment row. Storage records the type the uploader declared (it does not inspect contents), so this stops
-- mismatches and wrong declarations; only a virus scanner can detect a disguised file (see docs/DIRA_CONNECT.md).
create or replace function guard_connect_attachment() returns trigger language plpgsql security definer set search_path = public as $$
declare m connect_messages; obj storage.objects; real_size bigint; real_mime text;
begin
  if is_trusted_session() then return new; end if;
  select * into m from connect_messages where id = new.message_id;
  if not found or m.sender_id <> auth.uid() or m.conversation_id <> new.conversation_id or m.hidden_at is not null or m.created_at < now() - interval '15 minutes' then
    raise exception 'Attach files only to a message you have just sent';
  end if;
  if new.storage_path not like new.conversation_id::text || '/' || auth.uid()::text || '/%' then raise exception 'The file is not in this conversation''s folder'; end if;
  select * into obj from storage.objects where bucket_id = 'connect-attachments' and name = new.storage_path;
  if not found then raise exception 'Upload the file before attaching it'; end if;
  real_size := coalesce((obj.metadata ->> 'size')::bigint, new.size_bytes);
  real_mime := coalesce(obj.metadata ->> 'mimetype', new.mime_type);
  if not connect_allowed_mime(real_mime) then raise exception 'Only PDF, Word, Excel, PowerPoint, JPG and PNG files can be attached'; end if;
  if real_size > 10485760 then raise exception 'Files can be at most 10 MB'; end if;
  if (select count(*) from connect_attachments where message_id = new.message_id) >= 3 then raise exception 'At most 3 files per message'; end if;
  new.size_bytes := real_size; new.mime_type := real_mime;
  new.file_name := left(regexp_replace(btrim(new.file_name), '[\\/\x00-\x1f<>:"|?*]', '_', 'g'), 200);
  new.uploaded_by := auth.uid(); new.scan_status := 'not_scanned'; new.created_at := now();
  return new;
end $$;
create trigger trg_guard_connect_attachment before insert on connect_attachments for each row execute function guard_connect_attachment();

alter table connect_attachments enable row level security;
create policy cat_read on connect_attachments for select to authenticated using (connect_attachment_read_ok(storage_path));
create policy cat_insert on connect_attachments for insert to authenticated with check (uploaded_by = auth.uid() and connect_can_post(conversation_id));

-- ============ 6. retention and legal holds ============
create table connect_retention_settings (
  id boolean primary key default true check (id),
  enabled boolean not null default false,
  months int not null default 12 check (months between 1 and 120),
  updated_by uuid references profiles(id),
  updated_at timestamptz not null default now()
);
insert into connect_retention_settings(id) values (true);

create table connect_legal_holds (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid references connect_conversations(id) on delete cascade,
  participant_id uuid references participants(id) on delete cascade,
  cohort_id uuid references cohorts(id) on delete cascade,
  reason text not null check (length(btrim(reason)) >= 10),
  placed_by uuid references profiles(id),
  placed_at timestamptz not null default now(),
  released_by uuid references profiles(id),
  released_at timestamptz,
  release_reason text,
  constraint connect_hold_one_target check (num_nonnulls(conversation_id, participant_id, cohort_id) = 1)
);

create table connect_retention_log (
  id uuid primary key default gen_random_uuid(),
  run_at timestamptz not null default now(),
  conversations int not null, messages int not null, files int not null
);

alter table connect_retention_settings enable row level security;
alter table connect_legal_holds enable row level security;
alter table connect_retention_log enable row level security;
create policy crs_read on connect_retention_settings for select to authenticated using (is_executive() or is_safeguarding_officer());
create policy crs_update on connect_retention_settings for update to authenticated using (is_executive()) with check (is_executive());
create policy clh_read on connect_legal_holds for select to authenticated using (is_executive() or is_safeguarding_officer());
create policy crl_read on connect_retention_log for select to authenticated using (is_executive());
create trigger aud_connect_retention_settings after update on connect_retention_settings for each row execute function audit_row();
create trigger aud_connect_legal_holds after insert or update on connect_legal_holds for each row execute function audit_row();

create or replace function guard_connect_retention_settings() returns trigger language plpgsql security definer set search_path = public as $$
begin new.updated_by := coalesce(auth.uid(), new.updated_by); new.updated_at := now(); return new; end $$;
create trigger trg_guard_connect_retention before update on connect_retention_settings for each row execute function guard_connect_retention_settings();

create or replace function connect_place_hold(p_conversation uuid, p_participant uuid, p_cohort uuid, p_reason text) returns uuid language plpgsql security definer set search_path = public as $$
declare hid uuid;
begin
  if not (is_executive() or is_safeguarding_officer()) then raise exception 'Only executives and safeguarding officers can place a legal hold'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'Write a reason of at least 10 characters'; end if;
  insert into connect_legal_holds(conversation_id, participant_id, cohort_id, reason, placed_by) values (p_conversation, p_participant, p_cohort, btrim(p_reason), auth.uid()) returning id into hid;
  return hid;
end $$;
create or replace function connect_release_hold(p_hold uuid, p_reason text) returns void language plpgsql security definer set search_path = public as $$
begin
  if not (is_executive() or is_safeguarding_officer()) then raise exception 'Only executives and safeguarding officers can release a legal hold'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'Write a reason of at least 10 characters'; end if;
  update connect_legal_holds set released_at = now(), released_by = auth.uid(), release_reason = btrim(p_reason) where id = p_hold and released_at is null;
  if not found then raise exception 'That hold is not active'; end if;
end $$;

-- One row per conversation: when it ends, when it may be purged, and whether something protects it.
create or replace function connect_retention_candidates()
returns table(conversation_id uuid, kind text, ends_on date, purge_after date, held boolean, hold_reason text)
language sql stable security definer set search_path = public as $$
  with s as (select months from connect_retention_settings limit 1),
  base as (
    select c.id, c.kind, c.learner_id, c.cohort_id,
           case when c.kind = 'cohort' then (select co.end_date from cohorts co where co.id = c.cohort_id)
                else (select max(co.end_date) from cohort_enrolments e join cohorts co on co.id = e.cohort_id where e.participant_id = c.learner_id) end as ends_on
    from connect_conversations c)
  select b.id, b.kind, b.ends_on, (b.ends_on + make_interval(months => (select months from s)))::date,
         h.reason is not null, h.reason
  from base b
  left join lateral (select case
      when b.kind = 'safeguarding' then 'Safeguarding conversation (separate retention policy)'
      when exists (select 1 from connect_reports r where r.conversation_id = b.id) then 'Contains a reported message'
      when exists (select 1 from safeguarding_records sr where sr.conversation_id = b.id or (b.learner_id is not null and sr.participant_id = b.learner_id)) then 'Linked to a safeguarding record'
      when exists (select 1 from connect_legal_holds lh where lh.released_at is null and (lh.conversation_id = b.id
                     or (b.learner_id is not null and lh.participant_id = b.learner_id)
                     or lh.cohort_id = b.cohort_id
                     or (b.learner_id is not null and lh.cohort_id in (select e.cohort_id from cohort_enrolments e where e.participant_id = b.learner_id)))) then 'Legal hold'
    end as reason) h on true $$;
revoke all on function connect_retention_candidates() from public, anon, authenticated;

-- Preview for executives and officers (no message content).
create or replace function connect_retention_status()
returns table(conversation_id uuid, kind text, messages bigint, ends_on date, purge_after date, due boolean, held boolean, hold_reason text)
language sql stable security definer set search_path = public as $$
  select r.conversation_id, r.kind, (select count(*) from connect_messages m where m.conversation_id = r.conversation_id),
         r.ends_on, r.purge_after, coalesce(r.purge_after <= current_date, false), r.held, r.hold_reason
  from connect_retention_candidates() r
  where (is_executive() or is_safeguarding_officer()) and exists (select 1 from connect_messages m where m.conversation_id = r.conversation_id)
  order by r.purge_after nulls last $$;

-- Run by the send-emails schedule (service role). Returns the stored files to remove from Storage.
create or replace function connect_retention_purge() returns table(storage_path text) language plpgsql security definer set search_path = public as $$
declare en boolean; cv record; nconv int := 0; nmsg int := 0; nfile int := 0; paths text[] := '{}'; k int;
begin
  select enabled into en from connect_retention_settings limit 1;
  if not coalesce(en, false) then return; end if;
  perform set_config('dira.connect_purge', 'on', true);
  for cv in select r.conversation_id from connect_retention_candidates() r where r.purge_after <= current_date and not r.held loop
    paths := paths || coalesce(array(select a.storage_path from connect_attachments a where a.conversation_id = cv.conversation_id), '{}');
    delete from connect_attachments a where a.conversation_id = cv.conversation_id; get diagnostics k = row_count; nfile := nfile + k;
    delete from connect_reads r where r.conversation_id = cv.conversation_id;
    delete from connect_messages m where m.conversation_id = cv.conversation_id; get diagnostics k = row_count;
    if k > 0 then nconv := nconv + 1; nmsg := nmsg + k; end if;
  end loop;
  perform set_config('dira.connect_purge', 'off', true);
  if nconv > 0 then insert into connect_retention_log(conversations, messages, files) values (nconv, nmsg, nfile); end if;
  return query select unnest(paths);
end $$;

-- Users still can never delete messages; only the retention job can, inside a trusted server session.
create or replace function block_connect_message_delete() returns trigger language plpgsql as $$
begin
  if current_setting('dira.connect_purge', true) = 'on' and is_trusted_session() then return old; end if;
  raise exception 'Messages cannot be deleted';
end $$;

-- ============ 7. grants ============
revoke all on function connect_my_learners(), connect_start_direct_with_learner(uuid), connect_my_support(), connect_start_safeguarding(),
  connect_thread_messages(uuid, timestamptz, int), connect_place_hold(uuid, uuid, uuid, text), connect_release_hold(uuid, text),
  connect_retention_status(), connect_retention_purge() from public, anon;
grant execute on function connect_my_learners(), connect_start_direct_with_learner(uuid), connect_my_support(), connect_start_safeguarding(),
  connect_thread_messages(uuid, timestamptz, int), connect_place_hold(uuid, uuid, uuid, text), connect_release_hold(uuid, text),
  connect_retention_status() to authenticated;
revoke execute on function connect_retention_purge() from authenticated;

-- Realtime: new attachments appear live too (Realtime applies the cat_read policy).
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table connect_attachments;
  end if;
end $$;
grant execute on function connect_retention_purge() to service_role;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000025', 'connect_phase4_completion');
commit;

\echo '== migration 20260101000026 minimum_age'
begin;
-- DIRA LEARN: minimum age (management decision of 19 Nov 2026). DIRA LEARN is for participants aged 18 to 25.
-- Applications from people below 18 must not be accepted. Any future programme for minors needs a separately approved policy.
-- STATUS: executed and tested locally. NOT applied to any Supabase project. Rollback: supabase/rollback/20260101000026_minimum_age_down.sql
--
--   * An applicant submitting through the app must give a valid date of birth showing they are at least 18 today.
--   * Nobody (staff, server functions or the SQL editor) can accept an application, or create a participant record,
--     for someone whose recorded date of birth shows they are under 18.
--   * Existing records are not changed. The upper limit of 25 is still checked by the application form only
--     (decision pending: see docs/SAFEGUARDING.md).

create or replace function dob_from_form(f jsonb) returns date language plpgsql immutable as $$
begin return (f ->> 'dateOfBirth')::date; exception when others then return null; end $$;

create or replace function guard_application_min_age() returns trigger language plpgsql security definer set search_path = public as $$
declare dob date := dob_from_form(new.form_data);
begin
  if new.status = 'submitted' and (tg_op = 'INSERT' or old.status is distinct from 'submitted') and not is_trusted_session() then
    if dob is null then raise exception 'Enter your date of birth before submitting your application'; end if;
  end if;
  if new.status in ('submitted', 'accepted') and (tg_op = 'INSERT' or old.status is distinct from new.status)
     and dob is not null and dob > (current_date - interval '18 years')::date then
    raise exception 'DIRA LEARN is for people aged 18 to 25. Applications from people under 18 cannot be accepted';
  end if;
  return new;
end $$;
create trigger trg_application_min_age before insert or update of status, form_data on applications
  for each row execute function guard_application_min_age();

create or replace function guard_participant_min_age() returns trigger language plpgsql as $$
begin
  if new.date_of_birth is not null and (tg_op = 'INSERT' or new.date_of_birth is distinct from old.date_of_birth)
     and new.date_of_birth > (current_date - interval '18 years')::date then
    raise exception 'DIRA LEARN participants must be at least 18 years old';
  end if;
  return new;
end $$;
create trigger trg_participant_min_age before insert or update of date_of_birth on participants
  for each row execute function guard_participant_min_age();
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000026', 'minimum_age');
commit;

\echo '== migration 20260101000027 learner_performance'
begin;
-- DIRA LEARN: Phase 6 – Individual Learner Performance.
-- STATUS: executed and tested locally (PostgreSQL 16 + Supabase stand-in). NOT applied to any Supabase project.
-- Rollback: supabase/rollback/20260101000027_learner_performance_down.sql
--
-- WHAT IT ADDS
--   * learner_metrics(cohort): one row per learner with attendance, sessions, assignments, scores, the DRAFT weighted result,
--     completion requirements and completion status. It mirrors the Results page calculation exactly (src/features/results),
--     so the learner's view and management reports cannot disagree. No pass mark is applied: none has been approved.
--   * learner_feedback: facilitator feedback on a learner's overall progress, shared with the learner or staff-only.
--   * learner_progress_snapshots: a daily snapshot per learner (taken by the send-emails schedule), for performance history.
--   * performance_settings: DRAFT "may need support" thresholds, editable by executives (management decision pending).
-- WHO SEES WHAT (enforced here, not only on screen)
--   * a learner: only their OWN record, and only while their access to that cohort is Active or Expired (read-only results,
--     as decided for migration 19); shared feedback only.
--   * a facilitator: only learners of cohorts they are assigned to; all feedback for those learners.
--   * a mentor: only their own mentees; shared feedback only.
--   * programme staff and executives: everyone.
--   * M&E officers, applicants and everyone else: no individual records (cohort figures come in Phase 7).

-- ============ 1. settings (draft) ============
create table performance_settings (
  id boolean primary key default true check (id),
  support_attendance_below numeric not null default 75 check (support_attendance_below between 0 and 100),
  support_overdue_at_least int not null default 2 check (support_overdue_at_least between 1 and 50),
  support_score_below numeric check (support_score_below is null or support_score_below between 0 and 100),
  is_approved boolean not null default false,
  updated_by uuid references profiles(id),
  updated_at timestamptz not null default now()
);
insert into performance_settings(id) values (true);
alter table performance_settings enable row level security;
create policy perf_settings_read on performance_settings for select to authenticated using (true);
create policy perf_settings_update on performance_settings for update to authenticated using (is_executive()) with check (is_executive());
create or replace function guard_performance_settings() returns trigger language plpgsql security definer set search_path = public as $$
begin new.updated_by := coalesce(auth.uid(), new.updated_by); new.updated_at := now(); return new; end $$;
create trigger trg_guard_performance_settings before update on performance_settings for each row execute function guard_performance_settings();
create trigger aud_performance_settings after update on performance_settings for each row execute function audit_row();

-- ============ 2. the calculation (internal: no permission filter, never granted to users) ============
create or replace function _learner_metrics(p_cohort uuid)
returns table(
  participant_id uuid, participant_no text, display_name text, track_id uuid, track_name text, participant_status text, access_status text,
  attendance_records int, attendance_rate numeric, sessions_attended int, core_attended int, core_total int,
  assignments_expected int, submitted int, graded int, returned int, overdue int, late int,
  tasks_pct numeric, tasks_graded int, tasks_total int, final_pct numeric, final_graded int, final_total int,
  reflection_pct numeric, reflection_graded int, reflection_total int,
  overall numeric, provisional boolean, final_submitted boolean, reflection_submitted boolean,
  completion_met boolean, certified boolean, completion_status text, needs_support boolean, support_reasons text[])
language sql stable security definer set search_path = public as $$
  with s as (select * from performance_settings limit 1),
  en as (
    select e.participant_id, e.track_id, pa.participant_no, pa.status::text as pstatus,
           btrim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')) as name
    from cohort_enrolments e join participants pa on pa.id = e.participant_id left join profiles pr on pr.id = pa.profile_id
    where e.cohort_id = p_cohort),
  sch as (
    select ss.id, ss.curriculum_session_id, ss.status::text as status, cs.track_id as cs_track
    from session_schedules ss left join curriculum_sessions cs on cs.id = ss.curriculum_session_id where ss.cohort_id = p_cohort),
  core as (select count(distinct curriculum_session_id)::int as n from sch where cs_track is null),
  att as (   -- the learner's attendance on sessions that apply to them (core or their track), not cancelled
    select en.participant_id, a.status::text as status, sch.curriculum_session_id, (sch.cs_track is null) as is_core
    from en join sch on sch.status <> 'cancelled' and (sch.cs_track is null or sch.cs_track = en.track_id)
    join attendance a on a.schedule_id = sch.id and a.participant_id = en.participant_id),
  att_sum as (
    select en.participant_id,
      count(a.status) filter (where a.status is not null)::int as records,
      count(a.status) filter (where a.status <> 'excused')::int as counted,
      count(a.status) filter (where a.status in ('present', 'late'))::int as attended,
      count(distinct a.curriculum_session_id) filter (where a.status in ('present', 'late'))::int as sessions,
      count(distinct a.curriculum_session_id) filter (where a.status in ('present', 'late') and a.is_core)::int as core_sessions
    from en left join att a on a.participant_id = en.participant_id group by en.participant_id),
  asg as (   -- assignments that apply to each learner (track rule and individual recipients)
    select en.participant_id, x.id, x.component, x.max_score, x.due_at
    from en join assignments x on x.cohort_id = p_cohort and (x.track_id is null or x.track_id = en.track_id)
    where not exists (select 1 from assignment_recipients r where r.assignment_id = x.id)
       or exists (select 1 from assignment_recipients r where r.assignment_id = x.id and r.participant_id = en.participant_id)),
  lat as (   -- the latest attempt per learner and assignment
    select distinct on (sb.participant_id, sb.assignment_id) sb.participant_id, sb.assignment_id, sb.status::text as status, sb.score
    from submissions sb join asg on asg.id = sb.assignment_id and asg.participant_id = sb.participant_id
    order by sb.participant_id, sb.assignment_id, sb.attempt desc),
  per as (
    select asg.participant_id, asg.id, asg.component, asg.max_score, asg.due_at, lat.status, lat.score,
           case when lat.status = 'graded' and asg.max_score is not null and asg.max_score > 0 and lat.score is not null
                then round(lat.score / asg.max_score * 100, 1) end as pct
    from asg left join lat on lat.participant_id = asg.participant_id and lat.assignment_id = asg.id),
  comp as (
    select participant_id, component,
           round(avg(pct), 1) as pct,
           count(pct)::int as graded_n,
           count(*) filter (where max_score is not null)::int as total_n,
           bool_or(status is not null) as any_submitted
    from per group by participant_id, component),
  asg_sum as (
    select participant_id, count(*)::int as expected, count(status)::int as submitted,
           count(*) filter (where status = 'graded')::int as graded, count(*) filter (where status = 'returned')::int as returned,
           count(*) filter (where status is null and due_at is not null and due_at < now())::int as overdue,
           count(*) filter (where status = 'late')::int as late
    from per group by participant_id),
  base as (
    select en.participant_id, en.participant_no, coalesce(nullif(en.name, ''), 'Participant') as display_name, en.track_id, t.name as track_name, en.pstatus,
      learner_access_state(en.participant_id, p_cohort)::text as access_status,
      coalesce(a.records, 0) as records,
      case when coalesce(a.counted, 0) = 0 then null else round(a.attended::numeric / a.counted * 100, 1) end as engagement,
      coalesce(a.sessions, 0) as sessions, coalesce(a.core_sessions, 0) as core_sessions, (select n from core) as core_total,
      coalesce(x.expected, 0) as expected, coalesce(x.submitted, 0) as submitted, coalesce(x.graded, 0) as graded,
      coalesce(x.returned, 0) as returned, coalesce(x.overdue, 0) as overdue, coalesce(x.late, 0) as late,
      ct.pct as t_pct, coalesce(ct.graded_n, 0) as t_graded, coalesce(ct.total_n, 0) as t_total,
      cf.pct as f_pct, coalesce(cf.graded_n, 0) as f_graded, coalesce(cf.total_n, 0) as f_total,
      cr.pct as r_pct, coalesce(cr.graded_n, 0) as r_graded, coalesce(cr.total_n, 0) as r_total,
      coalesce(cf.any_submitted, false) as f_sub, coalesce(cr.any_submitted, false) as r_sub,
      exists (select 1 from certificates c where c.participant_id = en.participant_id and c.cohort_id = p_cohort and not c.revoked) as certified
    from en left join tracks t on t.id = en.track_id left join att_sum a on a.participant_id = en.participant_id
    left join asg_sum x on x.participant_id = en.participant_id
    left join comp ct on ct.participant_id = en.participant_id and ct.component = 'task'
    left join comp cf on cf.participant_id = en.participant_id and cf.component = 'final_project'
    left join comp cr on cr.participant_id = en.participant_id and cr.component = 'reflection'),
  calc as (
    select b.*,
      case when b.engagement is null or b.t_pct is null or b.f_pct is null or b.r_pct is null then null
           else round((b.engagement * 20 + b.t_pct * 30 + b.f_pct * 40 + b.r_pct * 10) / 100, 1) end as overall,
      (b.sessions >= 6 and b.core_total > 0 and b.core_sessions >= b.core_total and b.f_sub and b.r_sub) as met
    from base b)
  select c.participant_id, c.participant_no, c.display_name, c.track_id, c.track_name, c.pstatus, c.access_status,
    c.records, c.engagement, c.sessions, c.core_sessions, c.core_total,
    c.expected, c.submitted, c.graded, c.returned, c.overdue, c.late,
    c.t_pct, c.t_graded, c.t_total, c.f_pct, c.f_graded, c.f_total, c.r_pct, c.r_graded, c.r_total,
    c.overall, (c.overall is not null and (c.t_graded < c.t_total or c.f_graded < c.f_total or c.r_graded < c.r_total)),
    c.f_sub, c.r_sub, c.met, c.certified,
    case when c.certified then 'certified' when c.pstatus = 'withdrawn' then 'withdrawn' when c.met then 'requirements_met' else 'in_progress' end,
    (c.pstatus <> 'withdrawn' and not c.certified and cardinality(r.reasons) > 0),
    case when c.pstatus = 'withdrawn' or c.certified then '{}'::text[] else r.reasons end
  from calc c cross join s
  cross join lateral (select array_remove(array[
      case when c.engagement is not null and c.engagement < s.support_attendance_below then 'attendance' end,
      case when c.overdue >= s.support_overdue_at_least then 'overdue_work' end,
      case when c.returned > 0 then 'work_returned' end,
      case when s.support_score_below is not null and c.overall is not null and c.overall < s.support_score_below then 'low_score' end], null) as reasons) r
  order by c.display_name $$;
revoke all on function _learner_metrics(uuid) from public, anon, authenticated;

-- ============ 3. who may see which learner ============
create or replace function can_view_learner_performance(p_participant uuid, p_cohort uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    is_staff()
    or (app_role() = 'trainer' and p_cohort in (select my_trainer_cohorts()))
    or (app_role() = 'mentor' and mentor_has_mentee(p_participant))
    or (app_role() = 'participant' and p_participant = my_participant_id()
        and learner_access_state(p_participant, p_cohort) in ('active', 'expired')),
    false) $$;

-- Rows the caller may see for one cohort (staff and the cohort's facilitators: all; mentors: mentees; learners: themselves).
create or replace function learner_metrics(p_cohort uuid)
returns table(
  participant_id uuid, participant_no text, display_name text, track_id uuid, track_name text, participant_status text, access_status text,
  attendance_records int, attendance_rate numeric, sessions_attended int, core_attended int, core_total int,
  assignments_expected int, submitted int, graded int, returned int, overdue int, late int,
  tasks_pct numeric, tasks_graded int, tasks_total int, final_pct numeric, final_graded int, final_total int,
  reflection_pct numeric, reflection_graded int, reflection_total int,
  overall numeric, provisional boolean, final_submitted boolean, reflection_submitted boolean,
  completion_met boolean, certified boolean, completion_status text, needs_support boolean, support_reasons text[])
language sql stable security definer set search_path = public as $$
  select m.* from _learner_metrics(p_cohort) m where can_view_learner_performance(m.participant_id, p_cohort) $$;

-- The signed-in learner's own records, one per cohort they may see.
create or replace function my_performance()
returns table(cohort_id uuid, cohort_name text, metrics jsonb)
language sql stable security definer set search_path = public as $$
  select e.cohort_id, co.name, to_jsonb(m)
  from cohort_enrolments e join cohorts co on co.id = e.cohort_id
  cross join lateral (select * from _learner_metrics(e.cohort_id) x where x.participant_id = e.participant_id) m
  where app_role() = 'participant' and e.participant_id = my_participant_id() and can_view_learner_performance(e.participant_id, e.cohort_id)
  order by co.start_date desc $$;

-- ============ 4. facilitator feedback ============
create table learner_feedback (
  id uuid primary key default gen_random_uuid(),
  participant_id uuid not null references participants(id) on delete cascade,
  cohort_id uuid not null references cohorts(id) on delete cascade,
  author_id uuid not null references profiles(id),
  body text not null check (length(btrim(body)) between 5 and 2000),
  shared_with_learner boolean not null default true,
  created_at timestamptz not null default now()
);
create index idx_learner_feedback on learner_feedback (participant_id, cohort_id, created_at desc);

create or replace function can_give_learner_feedback(p_participant uuid, p_cohort uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(exists (select 1 from cohort_enrolments e where e.participant_id = p_participant and e.cohort_id = p_cohort)
    and (is_staff() or (app_role() = 'trainer' and p_cohort in (select my_trainer_cohorts()))), false) $$;

create or replace function guard_learner_feedback() returns trigger language plpgsql security definer set search_path = public as $$
declare learner_profile uuid;
begin
  if not is_trusted_session() then
    if not can_give_learner_feedback(new.participant_id, new.cohort_id) then
      raise exception 'Only the learner''s facilitators and programme staff can give feedback';
    end if;
    new.author_id := auth.uid();
  end if;
  new.body := btrim(new.body);
  new.created_at := now();
  if new.shared_with_learner then
    select profile_id into learner_profile from participants where id = new.participant_id;
    insert into notifications(user_id, kind, title, body) values (learner_profile, 'feedback', 'New feedback on your progress', 'Open Performance in DIRA LEARN to read it.');
  end if;
  return new;
end $$;
create trigger trg_guard_learner_feedback before insert on learner_feedback for each row execute function guard_learner_feedback();
create or replace function block_feedback_change() returns trigger language plpgsql as $$
begin
  if is_trusted_session() then return coalesce(new, old); end if;
  raise exception 'Feedback cannot be changed or deleted. Add a new note instead';
end $$;
create trigger trg_feedback_no_change before update or delete on learner_feedback for each row execute function block_feedback_change();
create trigger aud_learner_feedback after insert on learner_feedback for each row execute function audit_row();

alter table learner_feedback enable row level security;
create policy lf_read on learner_feedback for select to authenticated using (
  is_staff()
  or (app_role() = 'trainer' and cohort_id in (select my_trainer_cohorts()))
  or (shared_with_learner and app_role() = 'mentor' and mentor_has_mentee(participant_id))
  or (shared_with_learner and app_role() = 'participant' and participant_id = my_participant_id()
      and learner_access_state(participant_id, cohort_id) in ('active', 'expired')));
create policy lf_insert on learner_feedback for insert to authenticated with check (can_give_learner_feedback(participant_id, cohort_id));
-- no update or delete policies: feedback is append-only

-- ============ 5. performance history ============
create table learner_progress_snapshots (
  participant_id uuid not null references participants(id) on delete cascade,
  cohort_id uuid not null references cohorts(id) on delete cascade,
  taken_on date not null,
  attendance_rate numeric, sessions_attended int not null, submitted int not null, graded int not null, overdue int not null,
  overall numeric, completion_status text not null, needs_support boolean not null,
  created_at timestamptz not null default now(),
  primary key (participant_id, cohort_id, taken_on)
);
alter table learner_progress_snapshots enable row level security;
create policy lps_read on learner_progress_snapshots for select to authenticated using (can_view_learner_performance(participant_id, cohort_id));
-- written only by take_progress_snapshots() (no insert/update/delete policies)

-- Run by the send-emails schedule: at most one snapshot per learner per day, for cohorts running now or ended in the last 14 days.
create or replace function take_progress_snapshots() returns int language plpgsql security definer set search_path = public as $$
declare c record; n int := 0; k int;
begin
  for c in select id from cohorts where not archived and start_date <= current_date and end_date >= current_date - 14 loop
    insert into learner_progress_snapshots(participant_id, cohort_id, taken_on, attendance_rate, sessions_attended, submitted, graded, overdue, overall, completion_status, needs_support)
    select m.participant_id, c.id, current_date, m.attendance_rate, m.sessions_attended, m.submitted, m.graded, m.overdue, m.overall, m.completion_status, m.needs_support
    from _learner_metrics(c.id) m
    on conflict (participant_id, cohort_id, taken_on) do nothing;
    get diagnostics k = row_count; n := n + k;
  end loop;
  return n;
end $$;

create or replace function learner_performance_history(p_participant uuid, p_cohort uuid)
returns setof learner_progress_snapshots language sql stable security definer set search_path = public as $$
  select * from learner_progress_snapshots s
  where s.participant_id = p_participant and s.cohort_id = p_cohort and can_view_learner_performance(p_participant, p_cohort)
  order by s.taken_on $$;

-- Cohorts the caller may open on the Performance page (mentors cannot list cohorts otherwise).
create or replace function performance_cohorts() returns table(id uuid, name text, start_date date, end_date date) language sql stable security definer set search_path = public as $$
  select c.id, c.name, c.start_date, c.end_date from cohorts c
  where is_staff()
     or (app_role() = 'trainer' and c.id in (select my_trainer_cohorts()))
     or (app_role() = 'mentor' and exists (select 1 from cohort_enrolments e join mentorship_assignments m on m.participant_id = e.participant_id
                                            where e.cohort_id = c.id and m.mentor_id = auth.uid()))
  order by c.start_date desc $$;

-- ============ 6. grants ============
revoke all on function can_view_learner_performance(uuid, uuid), learner_metrics(uuid), my_performance(), can_give_learner_feedback(uuid, uuid),
  take_progress_snapshots(), learner_performance_history(uuid, uuid), performance_cohorts() from public, anon;
grant execute on function can_view_learner_performance(uuid, uuid), learner_metrics(uuid), my_performance(), can_give_learner_feedback(uuid, uuid),
  learner_performance_history(uuid, uuid), performance_cohorts() to authenticated;
revoke execute on function take_progress_snapshots() from authenticated;
grant execute on function take_progress_snapshots() to service_role;
;
