insert into supabase_migrations.schema_migrations(version, name) values ('20260101000032', 'curriculum_v13_2');
commit;

\echo '== migration 20260101000033 security_null_role'
begin;
-- DIRA LEARN: security fix found in the production-readiness audit (20 Nov 2026).
-- STATUS: executed and tested locally (PostgreSQL 16 + Supabase stand-in). NOT applied to any Supabase project.
-- Rollback: supabase/rollback/20260101000033_security_null_role_down.sql
--
-- THE PROBLEM
--   Several role checks were written as  `if app_role() not in (...) then raise ...`.  For a caller without an active profile
--   (a signed-out visitor using the public API key, or a deactivated account) app_role() is NULL, the condition is NULL, and
--   PL/pgSQL does NOT raise. Tested locally: a signed-out visitor could approve a curriculum session with set_curriculum_approval.
--   issue_certificate / revoke_certificate had the same gap. sg_is_acting_lead() returned NULL when no Lead or Deputy is
--   appointed, so `if not sg_is_acting_lead()` did not stop the safeguarding-record route of connect_oversight_read.
--   Supabase also lets signed-out visitors (role anon) call every public function by default.
--
-- THE FIX (no table, row, policy or curriculum content changes)
--   1. The NULL-unsafe role checks now treat an unknown role as "not allowed".
--   2. guard_curriculum_session treats only real trusted sessions (migrations, service role) as trusted, not "no user id".
--   3. sg_is_acting_lead() returns false instead of NULL.
--   4. Signed-out visitors may call only the two functions the public pages need (verify_certificate, first_admin_needed).
--      Signed-in users and the service role keep exactly the access they have now. Trigger functions are not touched.
--   Everything changed is recorded in security_fix_33_backup so the rollback can restore it exactly.

create table security_fix_33_backup (kind text not null, name text not null, data text not null, primary key (kind, name));
alter table security_fix_33_backup enable row level security;      -- no policies: not readable through the API
revoke all on security_fix_33_backup from anon, authenticated;

-- ============ 1-3. NULL-safe role checks ============
insert into security_fix_33_backup(kind, name, data)
select 'function', p.oid::regprocedure::text, pg_get_functiondef(p.oid)
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
 where n.nspname = 'public' and p.proname in ('set_curriculum_approval', 'issue_certificate', 'revoke_certificate', 'guard_curriculum_session', 'sg_is_acting_lead');

do $$
declare r record; d text; nd text;
begin
  for r in select p.oid, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace
            where n.nspname = 'public' and p.proname in ('set_curriculum_approval', 'issue_certificate', 'revoke_certificate', 'guard_curriculum_session') loop
    d := pg_get_functiondef(r.oid);
    nd := regexp_replace(d, 'app_role\(\)\s+not\s+in\s+(\([^()]*\))', 'coalesce(app_role() not in \1, true)', 'g');
    if r.proname = 'guard_curriculum_session' then
      nd := replace(nd, 'if auth.uid() is null then return new; end if;', 'if is_trusted_session() then return new; end if;');
    end if;
    if nd = d then raise exception 'security fix 33: % was not changed (unexpected definition)', r.proname; end if;
    execute nd;
  end loop;
end $$;

create or replace function sg_is_acting_lead() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(auth.uid() is not null and sg_acting_officer() = auth.uid(), false) $$;

-- ============ 4. signed-out visitors: only the functions the public pages use ============
do $$
declare r record; had_public boolean; had_auth boolean; had_service boolean;
begin
  for r in select p.oid, p.oid::regprocedure::text as sig, p.proacl, p.proowner
             from pg_proc p join pg_namespace n on n.oid = p.pronamespace
            where n.nspname = 'public' and p.prokind = 'f'
              and p.prorettype not in ('trigger'::regtype, 'event_trigger'::regtype)
              and p.proname not in ('verify_certificate', 'first_admin_needed')
              and has_function_privilege('anon', p.oid, 'execute') loop
    had_public := exists (select 1 from aclexplode(coalesce(r.proacl, acldefault('f', r.proowner))) a where a.grantee = 0 and a.privilege_type = 'EXECUTE');
    had_auth := has_function_privilege('authenticated', r.oid, 'execute');
    had_service := has_function_privilege('service_role', r.oid, 'execute');
    insert into security_fix_33_backup(kind, name, data)
    values ('grant', r.sig, json_build_object('public', had_public, 'anon', true, 'authenticated', had_auth, 'service_role', had_service, 'acl', coalesce(r.proacl, acldefault('f', r.proowner))::text)::text);
    execute format('revoke execute on function %s from public, anon', r.sig);
    if had_auth then execute format('grant execute on function %s to authenticated', r.sig); end if;
    if had_service then execute format('grant execute on function %s to service_role', r.sig); end if;
  end loop;
end $$;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000033', 'security_null_role');
commit;

\echo '== migration 20260101000034 account_status_enforcement'
begin;
-- Migration 34 - account status enforcement (post-audit fix H1/M1, 20 Nov 2026).
-- Problem: access helpers such as my_trainer_cohorts() looked only at assignment rows, so a deactivated trainer (or a trainer
-- whose role was changed) kept reading cohort submissions and enrolments and could create and edit assignments. Deactivation
-- also left the person able to sign in.
-- This migration:
--   1. account_is_active(): the one definition of "this signed-in person may use DIRA LEARN" (profile status = active).
--   2. check_request(): runs before every Data API request (PostgREST pre-request) and refuses inactive accounts, so an
--      existing session token stops working at once - also for SECURITY DEFINER functions.
--   3. A RESTRICTIVE policy on every table with row-level security, and on storage.objects, so the same rule holds for
--      Storage and Realtime, which do not run the pre-request check.
--   4. Access helpers re-check status and role (trainer, mentor, learner), so a role change or the removal of a cohort
--      assignment takes effect on the next request.
--   5. admin_set_account_status(): the only way to deactivate or reactivate (super administrator, reason required, never the
--      own account, never the last active super administrator); every change is kept in account_status_events.
--      Blocking sign-in itself (Supabase Auth ban) is done by the set-account-status Edge Function after this call.
-- Nothing is deleted: accounts, submissions, messages, audit logs and all other records stay as they are.
-- Rollback: supabase/rollback/20260101000034_account_status_enforcement_down.sql (restores the saved definitions).

-- ---------- 0. backup of everything this migration replaces (used by the rollback) ----------
create table security_fix_34_backup (kind text not null, name text not null, data text, primary key (kind, name));
alter table security_fix_34_backup enable row level security;
revoke all on security_fix_34_backup from anon, authenticated;

insert into security_fix_34_backup(kind, name, data)
select 'function', p.oid::regprocedure::text, pg_get_functiondef(p.oid)
from pg_proc p
where p.pronamespace = 'public'::regnamespace
  and p.proname in ('my_trainer_cohorts', 'mentor_has_mentee', 'is_course_trainer', 'my_participant_id', 'my_learning_access',
                    'connect_facilitator_assigned');
insert into security_fix_34_backup(kind, name, data)
select 'role_setting', 'authenticator', s from pg_roles r, unnest(coalesce(r.rolconfig, '{}'::text[])) s
where r.rolname = 'authenticator' and s like 'pgrst.db_pre_request=%' and s <> 'pgrst.db_pre_request=public.check_request';

-- ---------- 1. the rule ----------
create or replace function account_is_active() returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select p.status = 'active' from profiles p where p.id = auth.uid()), false) $$;
comment on function account_is_active() is 'True only for a signed-in person whose DIRA LEARN profile is active (migration 34).';

-- ---------- 2. pre-request check for the Data API ----------
create or replace function check_request() returns void language plpgsql stable security definer set search_path = public as $$
begin
  -- Signed-out visitors and server calls (no user id) pass; RLS and grants still apply to them.
  if auth.uid() is not null and exists (select 1 from profiles p where p.id = auth.uid() and p.status <> 'active') then
    raise exception using errcode = '42501', message = 'DIRA_ACCOUNT_INACTIVE',
      hint = 'This account is not active. Contact the DIRA Foundation programme team.';
  end if;
end $$;
comment on function check_request() is 'PostgREST pre-request check (migration 34): refuses every Data API request from an inactive account.';

do $$
declare previous text := (select data from security_fix_34_backup where kind = 'role_setting' and name = 'authenticator');
begin
  if previous is not null and previous <> 'pgrst.db_pre_request=public.check_request' then
    raise exception 'The API already uses another pre-request function (%). Stop and combine them by hand; nothing was changed.', previous;
  end if;
  execute 'alter role authenticator set pgrst.db_pre_request = ''public.check_request''';
  notify pgrst, 'reload config';
exception when insufficient_privilege then
  -- The table-level rules below still protect every table; report the missing step instead of failing the deployment.
  raise warning 'Could not register check_request() as the API pre-request function (no permission). Run in the SQL Editor: alter role authenticator set pgrst.db_pre_request = ''public.check_request''; notify pgrst, ''reload config'';';
end $$;

-- ---------- 3. restrictive policies: inactive accounts see and change nothing (Data API, Storage, Realtime) ----------
do $$
declare t record;
begin
  for t in select c.relname from pg_class c
           where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p') and c.relrowsecurity
           order by 1 loop
    execute format('create policy dira_active_account on public.%I as restrictive for all to authenticated '
                   'using ((select account_is_active())) with check ((select account_is_active()))', t.relname);
  end loop;
end $$;
create policy dira_active_account on storage.objects as restrictive for all to authenticated
  using ((select account_is_active())) with check ((select account_is_active()));

-- ---------- 4. access helpers re-check status and role ----------
-- app_role() already returns NULL for inactive profiles, so "app_role() = 'trainer'" means "an active trainer, now".
create or replace function my_trainer_cohorts() returns setof uuid language sql stable security definer set search_path = public as $$
  select ta.cohort_id from trainer_assignments ta where ta.trainer_id = auth.uid() and app_role() = 'trainer' $$;
create or replace function mentor_has_mentee(pid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select app_role() is not distinct from 'mentor'
     and exists (select 1 from mentorship_assignments m where m.mentor_id = auth.uid() and m.participant_id = pid) $$;
create or replace function is_course_trainer(cid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select app_role() is not distinct from 'trainer'
     and exists (select 1 from course_trainers where course_id = cid and trainer_id = auth.uid()) $$;
create or replace function my_participant_id() returns uuid language sql stable security definer set search_path = public as $$
  select pa.id from participants pa join profiles p on p.id = pa.profile_id
  where pa.profile_id = auth.uid() and p.status = 'active' $$;
create or replace function my_learning_access()
returns table(cohort_id uuid, cohort_name text, status learner_access_status, opens_at timestamptz, closes_at timestamptz)
language sql stable security definer set search_path = public as $$
  select e.cohort_id, c.name, learner_access_state(e.participant_id, e.cohort_id),
         coalesce(a.opens_at_override, c.access_opens_at), coalesce(a.closes_at_override, c.access_closes_at)
  from cohort_enrolments e
  join participants p on p.id = e.participant_id and p.profile_id = auth.uid()
  join profiles pr on pr.id = p.profile_id and pr.status = 'active'
  join cohorts c on c.id = e.cohort_id
  left join learner_access a on a.participant_id = e.participant_id and a.cohort_id = e.cohort_id $$;
-- A learner cannot start or continue a private conversation with someone who is no longer an active trainer.
create or replace function connect_facilitator_assigned(p_learner uuid, p_facilitator uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from trainer_assignments ta
                 join cohort_enrolments e on e.cohort_id = ta.cohort_id
                 join profiles f on f.id = ta.trainer_id and f.status = 'active' and f.role = 'trainer'
                 where ta.trainer_id = p_facilitator and e.participant_id = p_learner) $$;

-- ---------- 5. deactivation and reactivation ----------
create table account_status_events (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references profiles(id),
  old_status account_status not null,
  new_status account_status not null,
  reason text not null check (length(btrim(reason)) between 10 and 500),
  changed_by uuid references profiles(id),
  sign_in_blocked boolean,               -- set by the set-account-status Edge Function after the Supabase Auth ban or unban
  created_at timestamptz not null default now()
);
create index account_status_events_profile_idx on account_status_events(profile_id, created_at desc);
alter table account_status_events enable row level security;
create policy dira_active_account on account_status_events as restrictive for all to authenticated
  using ((select account_is_active())) with check ((select account_is_active()));
create policy ase_read on account_status_events for select to authenticated using (is_executive());
revoke insert, update, delete, truncate on account_status_events from anon, authenticated;

create or replace function guard_account_status_events() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then raise exception 'Account status history cannot be deleted'; end if;
  if not is_trusted_session()
     or new.profile_id <> old.profile_id or new.old_status <> old.old_status or new.new_status <> old.new_status
     or new.reason <> old.reason or new.changed_by is distinct from old.changed_by or new.created_at <> old.created_at then
    raise exception 'Account status history cannot be changed';
  end if;
  return new;
end $$;
create trigger trg_guard_account_status_events before update or delete on account_status_events
  for each row execute function guard_account_status_events();
create trigger aud_account_status_events after insert or update on account_status_events for each row execute function audit_row();

-- Status changes outside admin_set_account_status() (or a server process) are refused, so every change has a reason.
create or replace function guard_profile_status_change() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status is distinct from old.status and not is_trusted_session()
     and coalesce(current_setting('dira.account_status_change', true), '') <> 'on' then
    raise exception 'Account status is changed only with Deactivate or Reactivate on the Users page (a reason is required)';
  end if;
  return new;
end $$;
create trigger trg_guard_profile_status_change before update of status on profiles
  for each row execute function guard_profile_status_change();

create or replace function admin_set_account_status(p_profile uuid, p_status account_status, p_reason text) returns uuid
language plpgsql volatile security definer set search_path = public as $$
declare cur record; ev uuid;
begin
  if not is_admin() then
    raise exception 'Only a super administrator can deactivate or reactivate accounts' using errcode = '42501';
  end if;
  if p_profile is null or p_profile = auth.uid() then raise exception 'You cannot change the status of your own account'; end if;
  if p_status is null or p_status not in ('active', 'deactivated') then raise exception 'The new status must be active or deactivated'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 or length(btrim(p_reason)) > 500 then
    raise exception 'Give a reason of 10 to 500 characters';
  end if;
  select id, role, status into cur from profiles where id = p_profile for update;
  if not found then raise exception 'Account not found'; end if;
  if cur.status = p_status then raise exception 'The account is already %', p_status; end if;
  if p_status = 'deactivated' and cur.role = 'super_admin'
     and not exists (select 1 from profiles where role = 'super_admin' and status = 'active' and id <> p_profile) then
    raise exception 'The last active super administrator cannot be deactivated';
  end if;
  perform set_config('dira.account_status_change', 'on', true);
  update profiles set status = p_status where id = p_profile;
  perform set_config('dira.account_status_change', 'off', true);
  insert into account_status_events(profile_id, old_status, new_status, reason, changed_by)
  values (p_profile, cur.status, p_status, btrim(p_reason), auth.uid()) returning id into ev;
  return ev;
end $$;
comment on function admin_set_account_status(uuid, account_status, text) is
  'Deactivate or reactivate an account with a reason (super administrator only). Records account_status_events. Migration 34.';

-- ---------- 6. execute rights (new functions are not callable by signed-out visitors, except the pre-request check) ----------
revoke execute on function account_is_active(), admin_set_account_status(uuid, account_status, text),
  guard_account_status_events(), guard_profile_status_change() from public, anon;
grant execute on function account_is_active(), admin_set_account_status(uuid, account_status, text) to authenticated, service_role;
revoke execute on function check_request() from public;
grant execute on function check_request() to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000034', 'account_status_enforcement');
commit;

\echo '== migration 20260101000035 file_scanning'
begin;
-- Migration 35 - virus scan before download for every uploaded file (post-audit fix M2, 20 Nov 2026).
-- Until now only DIRA Connect attachments were scanned (migration 29). This extends the same rule to every other bucket:
-- application documents, assignment submissions, project evidence, course materials and learning resources.
-- Rule: a stored file can be opened (downloaded, or a signed link created) only when the virus scan of exactly this version
-- of the file said "clean". Pending, scanning, failed and infected files cannot be opened by anyone through the API, except
-- that the person who uploaded a file may still open their own copy while it waits (never when it was found infected).
-- Staff keep seeing the list of files and their scan status, so review workflows are unchanged once files are scanned.
-- Files already stored when this migration runs have no scan yet, so they become "waiting for virus check" (not deleted).
-- Without a configured scanner nothing is scanned and these files stay unavailable - the same safe default as migration 29.
-- Rollback: supabase/rollback/20260101000035_file_scanning_down.sql

create or replace function scanned_bucket(p_bucket text) returns boolean language sql immutable set search_path = public as $$
  select p_bucket in ('application-documents', 'submissions', 'project-evidence', 'course-materials', 'learning-resources') $$;
comment on function scanned_bucket(text) is 'Buckets whose files must pass the virus scan of migration 35 (DIRA Connect has its own, migration 29).';

create table storage_file_scans (
  bucket_id text not null,
  object_name text not null,
  object_updated_at timestamptz not null,        -- the version of the file this result is for; a re-upload needs a new scan
  status text not null default 'pending' check (status in ('pending', 'scanning', 'clean', 'infected', 'scan_failed')),
  attempts int not null default 0,
  claimed_at timestamptz,
  scanned_at timestamptz,
  engine text,
  detail text,
  uploaded_by uuid,
  primary key (bucket_id, object_name)
);
create index storage_file_scans_queue_idx on storage_file_scans (status, claimed_at) where status in ('pending', 'scanning');
create table storage_file_scan_log (
  id bigint generated always as identity primary key,
  bucket_id text not null, object_name text not null, object_updated_at timestamptz not null,
  result text not null check (result in ('clean', 'infected', 'error')), engine text, detail text,
  created_at timestamptz not null default now()
);
alter table storage_file_scans enable row level security;
alter table storage_file_scan_log enable row level security;
create policy dira_active_account on storage_file_scans as restrictive for all to authenticated
  using ((select account_is_active())) with check ((select account_is_active()));
create policy dira_active_account on storage_file_scan_log as restrictive for all to authenticated
  using ((select account_is_active())) with check ((select account_is_active()));
-- Status of a file: programme staff and executives, and the uploader for their own files. Written only by the scanner.
create policy sfs_read on storage_file_scans for select to authenticated using (is_staff() or is_executive() or uploaded_by = auth.uid());
create policy sfsl_read on storage_file_scan_log for select to authenticated using (is_staff() or is_executive());
revoke insert, update, delete, truncate on storage_file_scans, storage_file_scan_log from anon, authenticated;

-- Opening a file: only a clean scan of this exact version (updated_at) counts.
create or replace function file_is_downloadable(p_bucket text, p_name text, p_updated_at timestamptz, p_owner uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select not scanned_bucket(p_bucket)
      or exists (select 1 from storage_file_scans s where s.bucket_id = p_bucket and s.object_name = p_name
                 and s.status = 'clean' and s.object_updated_at = p_updated_at)
      or (p_owner is not null and p_owner = auth.uid()
          and not exists (select 1 from storage_file_scans s where s.bucket_id = p_bucket and s.object_name = p_name
                          and s.status = 'infected' and s.object_updated_at = p_updated_at)) $$;

create policy dira_scanned_files on storage.objects as restrictive for select to authenticated
  using (file_is_downloadable(bucket_id, name, updated_at, owner));

-- Scanner queue (service role only): files with no result for their current version are claimed; abandoned claims after 15 minutes.
create or replace function claim_file_scans(p_limit int default 10)
returns table(bucket_id text, object_name text, object_updated_at timestamptz, mime_type text, size_bytes bigint)
language plpgsql security definer set search_path = public as $$
begin
  -- new or re-uploaded files enter the queue
  insert into storage_file_scans as s (bucket_id, object_name, object_updated_at, status, uploaded_by)
  select o.bucket_id, o.name, o.updated_at, 'pending', o.owner from storage.objects o
  where scanned_bucket(o.bucket_id) and o.updated_at is not null
    and not exists (select 1 from storage_file_scans x where x.bucket_id = o.bucket_id and x.object_name = o.name and x.object_updated_at = o.updated_at)
  on conflict on constraint storage_file_scans_pkey do update
    set object_updated_at = excluded.object_updated_at, status = 'pending', attempts = 0, claimed_at = null, scanned_at = null,
        engine = null, detail = null, uploaded_by = excluded.uploaded_by;
  return query
  with c as (
    select s.bucket_id, s.object_name from storage_file_scans s
    where s.status = 'pending' or (s.status = 'scanning' and s.claimed_at < now() - interval '15 minutes')
    order by s.object_updated_at limit greatest(1, least(p_limit, 50)) for update skip locked)
  update storage_file_scans s set status = 'scanning', claimed_at = now(), attempts = s.attempts + 1
  from c, storage.objects o
  where s.bucket_id = c.bucket_id and s.object_name = c.object_name and o.bucket_id = s.bucket_id and o.name = s.object_name
  returning s.bucket_id, s.object_name, s.object_updated_at, (o.metadata ->> 'mimetype'), nullif(o.metadata ->> 'size', '')::bigint;
end $$;

-- Record a result for the version that was scanned. 'error' re-queues, or marks scan_failed after 3 attempts.
create or replace function record_file_scan(p_bucket text, p_name text, p_updated_at timestamptz, p_result text, p_engine text default null, p_detail text default null)
returns text language plpgsql security definer set search_path = public as $$
declare s storage_file_scans; final text;
begin
  if p_result not in ('clean', 'infected', 'error') then raise exception 'Result must be clean, infected or error'; end if;
  select * into s from storage_file_scans where bucket_id = p_bucket and object_name = p_name for update;
  if not found then raise exception 'File not in the scan queue'; end if;
  insert into storage_file_scan_log(bucket_id, object_name, object_updated_at, result, engine, detail)
  values (p_bucket, p_name, p_updated_at, p_result, left(p_engine, 100), left(p_detail, 500));
  if s.object_updated_at <> p_updated_at then return 'superseded'; end if;   -- the file was replaced meanwhile; the new version is queued
  final := case p_result when 'error' then (case when s.attempts >= 3 then 'scan_failed' else 'pending' end) else p_result end;
  update storage_file_scans set status = final, scanned_at = case when p_result = 'error' then scanned_at else now() end,
         engine = coalesce(left(p_engine, 100), engine), detail = left(p_detail, 500), claimed_at = null
  where bucket_id = p_bucket and object_name = p_name;
  if final = 'infected' and s.uploaded_by is not null then
    insert into notifications(user_id, kind, title, body) values (s.uploaded_by, 'message', 'A file you uploaded was blocked',
      'Our virus check found a problem with ' || left(regexp_replace(p_name, '^.*/', ''), 100) || '. It cannot be opened. Please upload a clean copy.');
  end if;
  return final;
end $$;

-- How many files wait (to notice when no scanner is configured): staff and executives.
create or replace function file_scan_queue() returns table(bucket_id text, waiting int, clean int, infected int, scan_failed int, oldest_waiting timestamptz)
language sql stable security definer set search_path = public as $$
  select o.bucket_id,
         count(*) filter (where s.status is null or s.object_updated_at <> o.updated_at or s.status in ('pending', 'scanning'))::int,
         count(*) filter (where s.status = 'clean' and s.object_updated_at = o.updated_at)::int,
         count(*) filter (where s.status = 'infected' and s.object_updated_at = o.updated_at)::int,
         count(*) filter (where s.status = 'scan_failed' and s.object_updated_at = o.updated_at)::int,
         min(o.updated_at) filter (where s.status is null or s.object_updated_at <> o.updated_at or s.status in ('pending', 'scanning'))
  from storage.objects o left join storage_file_scans s on s.bucket_id = o.bucket_id and s.object_name = o.name
  where scanned_bucket(o.bucket_id) and (is_staff() or is_executive())
  group by o.bucket_id $$;

-- Found while testing this fix: any trainer (and the M&E officer) could open EVERY learner's submission and project files and
-- every applicant's application documents, in every cohort. Now: application documents - programme staff only;
-- submissions and project evidence - programme staff, the M&E officer, and trainers only for learners in their own cohorts.
drop policy storage_staff_read on storage.objects;
create policy storage_staff_read on storage.objects for select to authenticated using (
  (bucket_id = 'application-documents' and is_staff())
  or (bucket_id in ('submissions', 'project-evidence') and (
        is_staff() or app_role() = 'me_officer'
        or (app_role() = 'trainer' and exists (
              select 1 from participants p join cohort_enrolments e on e.participant_id = p.id
              where p.profile_id::text = (storage.foldername(name))[1] and e.cohort_id in (select my_trainer_cohorts()))))));

-- Learning resources accepted any file type (audit M2). Limit them to the document, image and video types the site shows.
-- Files already stored are not touched; the previous setting is kept for the rollback.
create table file_scanning_35_backup (name text primary key, data text);
alter table file_scanning_35_backup enable row level security;
revoke all on file_scanning_35_backup from anon, authenticated;
create policy dira_active_account on file_scanning_35_backup as restrictive for all to authenticated
  using ((select account_is_active())) with check ((select account_is_active()));
insert into file_scanning_35_backup(name, data)
select 'learning-resources.allowed_mime_types', coalesce(array_to_string(allowed_mime_types, ','), '(none)') from storage.buckets where id = 'learning-resources';
update storage.buckets set allowed_mime_types = array['application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-powerpoint', 'image/jpeg', 'image/png', 'video/mp4']
where id = 'learning-resources' and allowed_mime_types is null;

revoke execute on function scanned_bucket(text), file_is_downloadable(text, text, timestamptz, uuid), claim_file_scans(int),
  record_file_scan(text, text, timestamptz, text, text, text), file_scan_queue() from public, anon;
revoke execute on function claim_file_scans(int), record_file_scan(text, text, timestamptz, text, text, text) from authenticated;
grant execute on function claim_file_scans(int), record_file_scan(text, text, timestamptz, text, text, text) to service_role;
grant execute on function scanned_bucket(text), file_is_downloadable(text, text, timestamptz, uuid), file_scan_queue() to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000035', 'file_scanning');
commit;

\echo '== migration 20260101000036 profile_bootstrap_repair'
begin;
-- Migration 36 - every sign-in account has exactly one profile (repair for "Loading your account…", 20 Nov 2026).
-- New accounts get their profile from the trigger on_auth_user_created (migration 02): role 'applicant', status 'active',
-- the lowest access in DIRA LEARN. If that trigger is missing or was disabled in a database, people can register and verify
-- their email but have no profile, and the app cannot let them in. This migration:
--   1. keeps handle_new_user() exactly as before, except that it never fails or duplicates when a profile already exists;
--   2. (re)creates the trigger on auth.users if it is missing or disabled;
--   3. gives every existing sign-in account WITHOUT a profile the same profile the trigger would have created.
-- Nobody gets more access than a new applicant; existing profiles (roles, statuses) are not touched; nothing is deleted.
-- Safe to run more than once. Rollback: supabase/rollback/20260101000036_profile_bootstrap_repair_down.sql

create table if not exists profile_repair_36_backup (kind text not null, name text not null, data text, primary key (kind, name));
alter table profile_repair_36_backup enable row level security;
revoke all on profile_repair_36_backup from anon, authenticated;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'profile_repair_36_backup' and policyname = 'dira_active_account') then
    create policy dira_active_account on profile_repair_36_backup as restrictive for all to authenticated
      using ((select account_is_active())) with check ((select account_is_active()));
  end if;
end $$;

insert into profile_repair_36_backup(kind, name, data)
select 'function', 'handle_new_user', pg_get_functiondef('public.handle_new_user()'::regprocedure)
on conflict do nothing;
insert into profile_repair_36_backup(kind, name, data)
select 'trigger', 'on_auth_user_created', coalesce((select case tgenabled when 'D' then 'disabled' else 'enabled' end
  from pg_trigger where tgrelid = 'auth.users'::regclass and tgname = 'on_auth_user_created'), 'missing')
on conflict do nothing;

create or replace function handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into profiles(id, role, status) values (new.id, 'applicant', 'active') on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function handle_new_user();

do $$
declare n int;
begin
  with added as (
    insert into profiles(id, role, status)
    select u.id, 'applicant', 'active' from auth.users u
    where not exists (select 1 from profiles p where p.id = u.id)
    on conflict (id) do nothing
    returning id)
  insert into profile_repair_36_backup(kind, name, data) select 'backfilled', id::text, now()::text from added on conflict do nothing;
  get diagnostics n = row_count;
  raise notice 'migration 36: % sign-in account(s) without a profile received the applicant profile; trigger before: %', n,
    (select data from profile_repair_36_backup where kind = 'trigger');
end $$;

;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000036', 'profile_bootstrap_repair');
commit;

\echo '== migration 20260101000037 digital_marketing_topic_sessions'
begin;
-- Migration 37 - Digital Marketing topic proposals follow the V13.2 sessions; DIRA's 8 Nov 2026 approval is recorded (21 Nov 2026).
-- DIRA (owner) approved Digital Marketing Sessions 5, 6 and 7 - their topics and practical outputs - on 8 Nov 2026
-- (docs/ASSUMPTIONS_AND_DECISIONS.md). V13 (19 Nov 2026) later spread that content over Sessions 3-8, but the 11 topic proposals
-- created by migration 16 still pointed at the 8 Nov session numbers. This migration:
--   1. moves each of the 11 Digital Marketing proposals to the session that teaches the topic in V13.2 (titles unchanged) and writes
--      the 8 Nov approval into its description. ALL 11 STAY PENDING: they are approved formally in the Curriculum Approval Centre;
--   2. redefines seed_initial_topic_proposals() with the corrected sessions (every other row unchanged), so a re-run of the seed
--      can never recreate them at the old session numbers;
--   3. sets the topics list of Digital Marketing draft records 3-7 to the proposals they now carry, and adds a note to records 3-8
--      saying which approved topics and outputs they carry forward. The records stay DRAFT (is_approved = false).
-- It never: approves anything, changes a status, reviewer or history row, edits an approved session record, a lesson plan, a
-- duration, another track, the Entrepreneurship Session 4 proposals or record, or programmes.is_approved.
-- It REFUSES (and changes nothing) if any of the 11 proposals has already been reviewed, or if a move would duplicate a topic.
-- Idempotent: running it or apply_digital_marketing_approval_37() again changes nothing. seed.sql calls the function too, because
-- on a fresh database the curriculum sessions are created by the seed, after the migrations.
-- Rollback: supabase/rollback/20260101000037_digital_marketing_topic_sessions_down.sql

-- ============ 1. the mapping (8 Nov session -> V13.2 session), one place for everything below ============
create or replace function digital_marketing_topic_map_37()
returns table(title text, approved_session int, current_session int) language sql immutable as $$
  values ('Digital footprint and online safety', 5, 3),
         ('Introduction to digital marketing', 5, 3),
         ('Social media marketing (Facebook, Instagram, TikTok, LinkedIn)', 5, 4),
         ('Content planning and creation', 5, 5),
         ('Canva for marketing graphics', 6, 5),
         ('Marketing copywriting, captions and calls to action', 6, 6),
         ('WhatsApp Business', 6, 4),
         ('Digital advertising fundamentals', 7, 7),
         ('SEO fundamentals', 7, 6),
         ('Marketing analytics and measuring campaign performance', 7, 7),
         ('Developing a practical digital marketing strategy', 7, 7) $$;
revoke all on function digital_marketing_topic_map_37() from public, anon, authenticated;
grant execute on function digital_marketing_topic_map_37() to service_role;

-- ============ 2. apply: re-map, describe, topics lists and notes (idempotent) ============
create or replace function apply_digital_marketing_approval_37() returns text
language plpgsql security definer set search_path = public as $$
declare
  prog constant uuid := '00000000-0000-0000-0000-0000000000a1';
  marker constant text := 'DIRA approval of 8 Nov 2026';
  dm uuid; n_moved int := 0; n_desc int := 0; n_topics int := 0; n_notes int := 0; bad text;
begin
  select id into dm from tracks where programme_id = prog and code = 'digital';
  if dm is null then return 'migration 37: no Digital Marketing track, nothing to do'; end if;

  -- refuse if any of the 11 has been reviewed (approved, rejected, reopened or with any history)
  select string_agg(p.title || ' (' || p.status || ')', '; ') into bad
    from curriculum_topic_proposals p join digital_marketing_topic_map_37() m on lower(btrim(p.title)) = lower(m.title)
   where p.track_id = dm
     and (p.status <> 'pending' or p.reviewed_by is not null or p.reviewed_at is not null
          or exists (select 1 from curriculum_topic_events e where e.proposal_id = p.id));
  if bad is not null then
    raise exception 'migration 37: these Digital Marketing topics have already been reviewed and are not moved: %. Nothing was changed.', bad;
  end if;

  -- refuse if a move would put the same topic twice on one session
  select string_agg(m.title, '; ') into bad
    from digital_marketing_topic_map_37() m
   where (select count(*) from curriculum_topic_proposals p where p.track_id = dm and lower(btrim(p.title)) = lower(m.title)) > 1;
  if bad is not null then
    raise exception 'migration 37: these Digital Marketing topics exist more than once: %. Nothing was changed.', bad;
  end if;

  -- 1. move to the V13.2 session (only pending, never-reviewed proposals reach this point)
  with target as (
    select m.title, cs.id as session_id from digital_marketing_topic_map_37() m
      join curriculum_sessions cs on cs.programme_id = prog and cs.track_id = dm and cs.session_no = m.current_session)
  update curriculum_topic_proposals p set session_id = t.session_id
    from target t where p.track_id = dm and lower(btrim(p.title)) = lower(t.title) and p.session_id <> t.session_id;
  get diagnostics n_moved = row_count;

  -- 2. the approval, visible to the reviewer in the Approval Centre
  update curriculum_topic_proposals p
     set description = format('Approved by DIRA on 8 Nov 2026 as a topic of Digital Marketing Session %s (owner''s written approval of '
                              'Sessions 5, 6 and 7, their topics and practical outputs; see docs/ASSUMPTIONS_AND_DECISIONS.md). '
                              'Taught in Session %s since the V13.2 revision. Awaiting formal approval in the Curriculum Approval Centre.',
                              m.approved_session, m.current_session)
    from digital_marketing_topic_map_37() m
   where p.track_id = dm and lower(btrim(p.title)) = lower(m.title) and p.status = 'pending'
     and p.description is distinct from format('Approved by DIRA on 8 Nov 2026 as a topic of Digital Marketing Session %s (owner''s written approval of '
                              'Sessions 5, 6 and 7, their topics and practical outputs; see docs/ASSUMPTIONS_AND_DECISIONS.md). '
                              'Taught in Session %s since the V13.2 revision. Awaiting formal approval in the Curriculum Approval Centre.',
                              m.approved_session, m.current_session);
  get diagnostics n_desc = row_count;

  -- 3. topics lists of the DRAFT records 3-7 = the proposals they carry (approved records are never edited)
  update curriculum_sessions cs
     set topics = coalesce((select array_agg(m.title order by m.approved_session, m.title) from digital_marketing_topic_map_37() m
                             where m.current_session = cs.session_no), '{}')
   where cs.programme_id = prog and cs.track_id = dm and cs.session_no between 3 and 7 and not cs.is_approved
     and cs.topics is distinct from coalesce((select array_agg(m.title order by m.approved_session, m.title) from digital_marketing_topic_map_37() m
                                              where m.current_session = cs.session_no), '{}');
  get diagnostics n_topics = row_count;

  -- 4. notes on the DRAFT records 3-8: which approved topics and outputs they carry forward
  update curriculum_sessions cs
     set assessment_notes = coalesce(cs.assessment_notes || ' ', '') || v.note
    from (values
      (3, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Digital footprint and online safety" and "Introduction to digital marketing" and the approved output "improved online profile" (all from approved Session 5). This V13.2 record itself is a draft awaiting session approval.'),
      (4, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Social media marketing (Facebook, Instagram, TikTok, LinkedIn)" (from approved Session 5) and "WhatsApp Business" and the approved output "WhatsApp Business profile plan" (both from approved Session 6). This V13.2 record itself is a draft awaiting session approval.'),
      (5, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Content planning and creation" (approved Session 5) and "Canva for marketing graphics" (from approved Session 6), the approved output "two-week content calendar" (approved Session 5) and the graphics for the approved output "three posts with captions" (from approved Session 6). This V13.2 record itself is a draft awaiting session approval.'),
      (6, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Marketing copywriting, captions and calls to action" (approved Session 6) and "SEO fundamentals" (from approved Session 7) and the captions for the approved output "three posts with captions" (approved Session 6). This V13.2 record itself is a draft awaiting session approval.'),
      (7, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session carries the approved topics "Digital advertising fundamentals", "Marketing analytics and measuring campaign performance" and "Developing a practical digital marketing strategy" and the approved output "digital marketing portfolio project" (built here as the campaign plan) with practice of the "three-minute walk-through" (all approved Session 7). This V13.2 record itself is a draft awaiting session approval.'),
      (8, marker || ' (Digital Marketing Sessions 5-7, topics and practical outputs): this session delivers the approved output "three-minute walk-through" of the digital marketing portfolio project (from approved Session 7), now the three-minute campaign presentation. This V13.2 record itself is a draft awaiting session approval.')
    ) as v(session_no, note)
   where cs.programme_id = prog and cs.track_id = dm and cs.session_no = v.session_no and not cs.is_approved
     and position(marker in coalesce(cs.assessment_notes, '')) = 0;
  get diagnostics n_notes = row_count;

  return format('migration 37: %s proposal(s) moved, %s description(s) written, %s topics list(s) and %s note(s) updated; nothing approved',
                n_moved, n_desc, n_topics, n_notes);
end $$;
revoke all on function apply_digital_marketing_approval_37() from public, anon, authenticated;
grant execute on function apply_digital_marketing_approval_37() to service_role;

-- ============ 3. the initial queue with the corrected Digital Marketing sessions (other rows exactly as in migration 16) ============
create or replace function seed_initial_topic_proposals() returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  insert into curriculum_topic_proposals(session_id, title)
  select cs.id, v.title
  from (select 'digital'::text as track_code, m.current_session as session_no, m.title from digital_marketing_topic_map_37() m
        union all
        select * from (values
          ('content', 6, 'Visual hierarchy'),
          ('content', 6, 'Consistent branding'),
          ('content', 6, 'Consent and credit for people, images and music'),
          ('entrepreneurship', 4, 'Introduction to digital marketing'),
          ('entrepreneurship', 4, 'Social media marketing (Facebook, Instagram, TikTok, LinkedIn)'),
          ('entrepreneurship', 4, 'Content planning and creation'),
          ('entrepreneurship', 4, 'Canva for marketing graphics'),
          ('entrepreneurship', 4, 'Marketing copywriting, captions and calls to action'),
          ('entrepreneurship', 4, 'WhatsApp Business'),
          ('entrepreneurship', 4, 'Digital advertising fundamentals'),
          ('entrepreneurship', 4, 'SEO fundamentals'),
          ('entrepreneurship', 4, 'Marketing analytics and measuring campaign performance'),
          ('entrepreneurship', 4, 'Developing a practical digital marketing strategy')) as o(track_code, session_no, title)
       ) as v(track_code, session_no, title)
  join tracks t on t.programme_id = '00000000-0000-0000-0000-0000000000a1' and t.code = v.track_code
  join curriculum_sessions cs on cs.track_id = t.id and cs.session_no = v.session_no
  -- a Digital Marketing topic that already exists on another session is moved by apply_digital_marketing_approval_37(), not duplicated
  where not (v.track_code = 'digital' and exists (select 1 from curriculum_topic_proposals p
                                                   where p.track_id = t.id and lower(btrim(p.title)) = lower(btrim(v.title))))
  on conflict do nothing;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function seed_initial_topic_proposals() from public, anon, authenticated;

-- ============ 4. run it on this database (a fresh database has no sessions yet: seed.sql runs it again at the end) ============
do $$ begin raise notice '%', apply_digital_marketing_approval_37(); end $$;
;
insert into supabase_migrations.schema_migrations(version, name) values ('20260101000037', 'digital_marketing_topic_sessions');
commit;

\echo '== migration 20260101000038 explicit_api_grants'
begin;
-- Migration 38 - explicit Data API grants (21 Nov 2026).
-- WHY: in production every signed-in request to public.profiles returned 403 ("permission denied for table profiles"),
-- although the profile existed with role super_admin and status active. Cause: migrations 01-37 never granted table
-- privileges to the API roles; they relied on Supabase granting every new public table, sequence and function to anon,
-- authenticated and service_role automatically. Supabase stopped doing that (new projects since 30 May 2026, all
-- projects since 30 Oct 2026). Reproduced locally on 21 Nov 2026: 5 of 106 tables readable by signed-in users.
-- WHAT: writes the authored intent of migrations 01-37 down as explicit grants (generated by
-- tools/release/generate_grants_38.py, reviewed):
--   * signed-in users (authenticated): only SELECT/INSERT/UPDATE/DELETE that a permissive RLS policy allows and that the
--     earlier migrations did not deliberately withhold. RLS stays on everywhere and still decides WHICH ROWS. Never
--     TRUNCATE, REFERENCES or TRIGGER (the old automatic defaults granted those too; they are removed here).
--   * signed-out visitors (anon): no table at all; only check_request() (API pre-request check) and verify_certificate().
--   * service_role (Edge Functions, server only): all tables, sequences and functions in public.
--   * functions: execute exactly as authored (122 for signed-in users; the 26 internal ones stay server-only).
-- SAFE on both kinds of project: on a project that still had the old automatic grants it narrows them to the intent; on
-- a new-style project it adds the missing grants. No data, row, policy or function body is changed.
-- SELF-CHECK at the end: the migration aborts (and changes nothing) if the result breaks any rule above.
-- Rollback: supabase/rollback/20260101000038_explicit_api_grants_down.sql restores the privileges recorded below exactly.

-- ============ 1. record the privileges as they are now (for an exact rollback) ============
create table if not exists grants_38_backup (
  object_kind text not null, object_name text not null, grantee text not null, privilege text not null,
  recorded_at timestamptz not null default now(),
  primary key (object_kind, object_name, grantee, privilege));
alter table grants_38_backup enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'grants_38_backup' and policyname = 'dira_active_account') then
    create policy dira_active_account on grants_38_backup as restrictive for all to authenticated
      using ((select account_is_active())) with check ((select account_is_active()));
  end if;
end $$;
revoke all on grants_38_backup from anon, authenticated;
grant select, insert, update, delete on grants_38_backup to service_role;

insert into grants_38_backup(object_kind, object_name, grantee, privilege)
select 'relation', c.oid::regclass::text, coalesce(r.rolname, 'PUBLIC'), a.privilege_type
  from pg_class c cross join lateral aclexplode(c.relacl) a left join pg_roles r on r.oid = a.grantee
 where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p', 'v', 'm', 'S') and c.relname <> 'grants_38_backup'
   and coalesce(r.rolname, 'PUBLIC') in ('anon', 'authenticated', 'service_role', 'PUBLIC')
union all
select 'function', p.oid::regprocedure::text, coalesce(r.rolname, 'PUBLIC'), a.privilege_type
  from pg_proc p cross join lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a left join pg_roles r on r.oid = a.grantee
 where p.pronamespace = 'public'::regnamespace and coalesce(r.rolname, 'PUBLIC') in ('anon', 'authenticated', 'service_role', 'PUBLIC')
on conflict do nothing;

-- ============ 2. start from nothing for the API roles (no broad grants survive) ============
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke execute on all functions in schema public from public, anon, authenticated;

-- ============ 3. server side ============
grant select, insert, update, delete on all tables in schema public to service_role;
grant usage, select, update on all sequences in schema public to service_role;
grant execute on all functions in schema public to service_role;

-- ============ 4. explicit grants (generated, reviewed) ============
